// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================
// SECURITY MIDDLEWARE
// ============================================================

// Add security headers with helmet
app.use(helmet());

// Body parser with size limits to prevent DOS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiter to all requests
app.use(limiter);

// ============================================================
// REQUEST LOGGING
// ============================================================

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// ============================================================
// ROUTES WITH VALIDATION
// ============================================================

/**
 * Health check endpoint
 * No validation needed - readonly endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

/**
 * Get users endpoint
 * - Query parameter validation for filtering/pagination
 * - Input sanitization
 * - Response validation
 */
app.get('/users', 
  // Input validation middleware
  query('skip')
    .optional()
    .isInt({ min: 0 })
    .withMessage('skip must be a non-negative integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be between 1 and 100'),
  query('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 50 })
    .withMessage('name must be between 1 and 50 characters')
    .matches(/^[a-zA-Z\s]+$/)
    .withMessage('name can only contain letters and spaces'),

  // Handler
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array().map(err => ({
            field: err.param,
            message: err.msg
          }))
        });
      }

      // Mock data (in production, this would come from a database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Extract and sanitize query parameters
      const skip = parseInt(req.query.skip) || 0;
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const nameFilter = req.query.name ? req.query.name.toLowerCase() : null;

      // Filter results
      let results = allUsers;
      if (nameFilter) {
        results = results.filter(user => 
          user.name.toLowerCase().includes(nameFilter)
        );
      }

      // Paginate results
      const paginatedResults = results.slice(skip, skip + limit);

      // Return structured response
      res.json({
        success: true,
        data: paginatedResults,
        pagination: {
          skip,
          limit,
          total: results.length
        }
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// ============================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = err.message || 'Internal server error';

  console.error('Error:', {
    status,
    message,
    path: req.path,
    method: req.method,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Don't leak error details in production
  res.status(status).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? message : undefined,
    status
  });
});

// ============================================================
// SERVER INITIALIZATION
// ============================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${process.env.NODE_ENV || 'development'} mode)`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

