// Improved application with security best practices
// Enhanced error handling, input validation, and security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const validator = require('validator');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Body parser with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use('/api/', limiter);

// ============================================
// REQUEST LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
    });
  });

  next();
});

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * @route GET /health
 * @returns {Object} Status and timestamp
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

/**
 * Get users endpoint with pagination and filtering
 * @route GET /api/users
 * @query {number} page - Page number (default: 1)
 * @query {number} limit - Results per page (default: 10, max: 100)
 * @returns {Object} Paginated users list
 */
app.get('/api/users', (req, res, next) => {
  try {
    // Input validation
    const page = validatePageNumber(req.query.page);
    const limit = validateLimit(req.query.limit);

    if (!page || !limit) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid pagination parameters',
      });
    }

    // Mock users database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const users = allUsers.slice(startIndex, startIndex + limit);

    res.status(200).json({
      status: 'success',
      data: users,
      pagination: {
        page,
        limit,
        total: allUsers.length,
      },
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// INPUT VALIDATION FUNCTIONS
// ============================================

/**
 * Validate page number parameter
 * @param {*} page - Page number to validate
 * @returns {number|null} Valid page number or null
 */
function validatePageNumber(page) {
  const pageNum = parseInt(page, 10);

  // Check if valid number and greater than 0
  if (!Number.isInteger(pageNum) || pageNum < 1) {
    return null;
  }

  // Cap at reasonable maximum to prevent memory issues
  if (pageNum > 10000) {
    return null;
  }

  return pageNum;
}

/**
 * Validate limit parameter
 * @param {*} limit - Limit to validate
 * @returns {number|null} Valid limit or null
 */
function validateLimit(limit) {
  const limitNum = parseInt(limit, 10);

  // Check if valid number
  if (!Number.isInteger(limitNum) || limitNum < 1) {
    return 10; // Default limit
  }

  // Maximum 100 items per page to prevent abuse
  return Math.min(limitNum, 100);
}

/**
 * Sanitize string input to prevent XSS
 * @param {string} input - Input string to sanitize
 * @returns {string} Sanitized string
 */
function sanitizeInput(input) {
  if (typeof input !== 'string') {
    return '';
  }

  return validator.escape(input).trim();
}

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use((error, req, res, next) => {
  const statusCode = error.statusCode || 500;
  const isDevelopment = NODE_ENV === 'development';

  console.error({
    timestamp: new Date().toISOString(),
    error: {
      message: error.message,
      stack: isDevelopment ? error.stack : undefined,
    },
    request: {
      method: req.method,
      path: req.path,
      ip: req.ip,
    },
  });

  res.status(statusCode).json({
    status: 'error',
    message: isDevelopment 
      ? error.message 
      : 'Internal server error',
    ...(isDevelopment && { stack: error.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const server = app.listen(PORT, () => {
  console.log({
    timestamp: new Date().toISOString(),
    message: `Server running on port ${PORT}`,
    environment: NODE_ENV,
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error({
    timestamp: new Date().toISOString(),
    message: 'Unhandled Rejection at:',
    promise,
    reason,
  });
  process.exit(1);
});

module.exports = app;

/**
 * Example test cases for security and error handling
 * Install: npm install --save-dev jest supertest
 */

const request = require('supertest');
const app = require('./app-improved');

describe('Security and Error Handling Tests', () => {

  // ============================================
  // INPUT VALIDATION TESTS
  // ============================================

  describe('Input Validation - /api/users', () => {

    test('should accept valid pagination parameters', async () => {
      const response = await request(app)
        .get('/api/users')
        .query({ page: 1, limit: 10 });

      expect(response.status).toBe(200);
      expect(response.body.status).toBe('success');
      expect(response.body.pagination.page).toBe(1);
    });

    test('should reject negative page numbers', async () => {
      const response = await request(app)
        .get('/api/users')
        .query({ page: -1 });

      expect(response.status).toBe(400);
      expect(response.body.status).toBe('error');
    });

    test('should reject non-numeric page numbers', async () => {
      const response = await request(app)
        .get('/api/users')
        .query({ page: 'abc' });

      expect(response.status).toBe(400);
    });

    test('should reject excessively large page numbers', async () => {
      const response = await request(app)
        .get('/api/users')
        .query({ page: 999999999 });

      expect(response.status).toBe(400);
    });

    test('should cap limit at 100', async () => {
      const response = await request(app)
        .get('/api/users')
        .query({ limit: 500 });

      expect(response.status).toBe(200);
      expect(response.body.pagination.limit).toBe(100);
    });

    test('should default to limit 10 if invalid', async () => {
      const response = await request(app)
        .get('/api/users')
        .query({ limit: 'invalid' });

      expect(response.status).toBe(200);
      expect(response.body.pagination.limit).toBe(10);
    });
  });

  // ============================================
  // SECURITY HEADER TESTS
  // ============================================

  describe('Security Headers', () => {

    test('should include X-Content-Type-Options header', async () => {
      const response = await request(app).get('/health');

      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    test('should include X-Frame-Options header', async () => {
      const response = await request(app).get('/health');

      expect(response.headers['x-frame-options']).toBe('DENY');
    });

    test('should include Content-Security-Policy header', async () => {
      const response = await request(app).get('/health');

      expect(response.headers['content-security-policy']).toBeDefined();
    });
  });

  // ============================================
  // ERROR HANDLING TESTS
  // ============================================

  describe('Error Handling', () => {

    test('should handle 404 with proper error response', async () => {
      const response = await request(app)
        .get('/non-existent-route');

      expect(response.status).toBe(404);
      expect(response.body.status).toBe('error');
      expect(response.body.message).toBe('Route not found');
    });

    test('should not expose stack trace in production', async () => {
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/non-existent-route');

      expect(response.body.stack).toBeUndefined();

      process.env.NODE_ENV = 'development';
    });

    test('should expose stack trace in development', async () => {
      process.env.NODE_ENV = 'development';

      const response = await request(app)
        .get('/non-existent-route');

      expect(response.body.stack).toBeDefined();
    });
  });

  // ============================================
  // RATE LIMITING TESTS
  // ============================================

  describe('Rate Limiting', () => {

    test('should include rate limit headers', async () => {
      const response = await request(app).get('/api/users');

      expect(response.headers['ratelimit-limit']).toBeDefined();
      expect(response.headers['ratelimit-remaining']).toBeDefined();
    });

    test('should enforce rate limit', async () => {
      // Note: This is simplified. In real tests, you'd need to:
      // 1. Make many requests
      // 2. Track when 429 status is returned
      // 3. Verify rate limit message

      const response = await request(app).get('/api/users');
      expect([200, 429]).toContain(response.status);
    });
  });

  // ============================================
  // PAYLOAD SIZE TESTS
  // ============================================

  describe('Payload Size Limits', () => {

    test('should reject requests larger than 10kb', async () => {
      const largePayload = 'a'.repeat(11 * 1024);

      const response = await request(app)
        .post('/api/users')
        .send({ data: largePayload });

      // Should either reject or at least not process the entire payload
      expect(response.status).not.toBe(200);
    });
  });

  // ============================================
  // DATA SANITIZATION TESTS
  // ============================================

  describe('Data Sanitization', () => {

    test('should sanitize input to prevent NoSQL injection', async () => {
      const maliciousInput = {
        $ne: null,
      };

      const response = await request(app)
        .post('/api/users')
        .send(maliciousInput);

      // Should not process the injection
      expect(response.status).not.toBe(200);
    });

    test('should escape HTML in responses', async () => {
      const xssPayload = '<script>alert("xss")</script>';

      const response = await request(app)
        .post('/api/users')
        .send({ name: xssPayload });

      // Response should not contain unescaped script tags
      expect(JSON.stringify(response.body)).not.toContain('<script>');
    });
  });

  // ============================================
  // RESPONSE VALIDATION TESTS
  // ============================================

  describe('Response Format', () => {

    test('/health should return proper response format', async () => {
      const response = await request(app).get('/health');

      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status', 'ok');
      expect(response.body).toHaveProperty('timestamp');
      expect(response.body).toHaveProperty('environment');
    });

    test('/api/users should return proper response format', async () => {
      const response = await request(app).get('/api/users');

      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status', 'success');
      expect(response.body).toHaveProperty('data');
      expect(response.body).toHaveProperty('pagination');
      expect(Array.isArray(response.body.data)).toBe(true);
    });
  });

  // ============================================
  // CONTENT-TYPE TESTS
  // ============================================

  describe('Content-Type Validation', () => {

    test('should return JSON content type', async () => {
      const response = await request(app).get('/health');

      expect(response.headers['content-type']).toMatch(/json/);
    });

    test('should reject non-JSON content types', async () => {
      const response = await request(app)
        .post('/api/users')
        .set('Content-Type', 'text/plain')
        .send('invalid');

      expect(response.status).not.toBe(200);
    });
  });

  // ============================================
  // CORS TESTS
  // ============================================

  describe('CORS Configuration', () => {

    test('should handle preflight requests', async () => {
      const response = await request(app)
        .options('/api/users')
        .set('Origin', 'http://localhost:3000')
        .set('Access-Control-Request-Method', 'GET');

      expect([200, 204]).toContain(response.status);
    });
  });
});

// ============================================
// MANUAL SECURITY TESTS (run separately)
// ============================================

/**
 * Run these tests manually to validate security measures
 * 
 * 1. Test NoSQL Injection:
 * curl -X POST http://localhost:3000/api/users \
 *   -H "Content-Type: application/json" \
 *   -d '{"username":{"$ne":null}}'
 * 
 * 2. Test XSS Attack:
 * curl "http://localhost:3000/api/users?name=<script>alert('xss')</script>"
 * 
 * 3. Test Large Payload (DoS):
 * perl -e 'print "A" x 20000' | curl -X POST \
 *   -d @- http://localhost:3000/api/users
 * 
 * 4. Test Rate Limiting:
 * for i in {1..150}; do curl http://localhost:3000/api/users; done
 * 
 * 5. Test Invalid Pagination:
 * curl "http://localhost:3000/api/users?page=99999999&limit=999999"
 * 
 * 6. Check Security Headers:
 * curl -I http://localhost:3000/health
 */

# Side-by-Side Comparison: Original vs Improved

## File Structure
```
BEFORE:
├── app.js (simple, vulnerable)

AFTER:
├── app-improved.js (production-ready)
├── package-improved.json (with security dependencies)
├── .env.example (configuration template)
├── SECURITY_REVIEW.md (detailed analysis)
├── REVIEW_SUMMARY.md (executive summary)
└── app.test.js (comprehensive tests)
```

---

## Code Comparison

### 1. SERVER INITIALIZATION

#### ❌ BEFORE (Vulnerable)
```javascript
const express = require('express');
const app = express();

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Issues:**
- Hardcoded port
- No environment variable support
- Simple log message
- No error handling
- No graceful shutdown

#### ✅ AFTER (Improved)
```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.use(helmet());
app.use(express.json({ limit: '10kb' }));
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
}));

const server = app.listen(PORT, () => {
  console.log({ message: `Server running on port ${PORT}`, environment: NODE_ENV });
});

process.on('SIGTERM', () => {
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});
```

**Improvements:**
- ✅ Environment variables
- ✅ Security headers (helmet)
- ✅ Rate limiting
- ✅ Body size limits
- ✅ Graceful shutdown
- ✅ Structured logging

---

### 2. ROUTE HANDLING

#### ❌ BEFORE (No Validation)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Issues:**
- No input validation
- No pagination support
- Exposes all data
- No error handling
- No authentication
- No authorization

#### ✅ AFTER (Validated & Secure)
```javascript
app.get('/api/users', (req, res, next) => {
  try {
    // Input validation
    const page = validatePageNumber(req.query.page);
    const limit = validateLimit(req.query.limit);

    if (!page || !limit) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid pagination parameters',
      });
    }

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Pagination
    const startIndex = (page - 1) * limit;
    const users = allUsers.slice(startIndex, startIndex + limit);

    res.status(200).json({
      status: 'success',
      data: users,
      pagination: {
        page,
        limit,
        total: allUsers.length,
      },
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

function validatePageNumber(page) {
  const pageNum = parseInt(page, 10);
  if (!Number.isInteger(pageNum) || pageNum < 1 || pageNum > 10000) {
    return null;
  }
  return pageNum;
}

function validateLimit(limit) {
  const limitNum = parseInt(limit, 10);
  if (!Number.isInteger(limitNum) || limitNum < 1) {
    return 10; // Default
  }
  return Math.min(limitNum, 100); // Cap at 100
}
```

**Improvements:**
- ✅ Input validation with bounds
- ✅ Pagination support
- ✅ Error handling (try-catch)
- ✅ Proper HTTP status codes
- ✅ Structured response format
- ✅ Protection against abuse

