app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ============================================
// 2. REQUEST VALIDATION UTILITIES
// ============================================

/**
 * Validates and sanitizes user input
 * @param {string} input - The input to validate
 * @param {Object} options - Validation options
 * @returns {string|null} - Sanitized input or null if invalid
 */
function validateInput(input, options = {}) {
  const { 
    maxLength = 255, 
    minLength = 1,
    pattern = null,
    required = true 
  } = options;

  if (!input) {
    return required ? null : '';
  }

  if (typeof input !== 'string') {
    return null;
  }

  if (input.trim().length < minLength || input.trim().length > maxLength) {
    return null;
  }

  if (pattern && !pattern.test(input)) {
    return null;
  }

  // Remove potentially harmful characters
  return input.trim().substring(0, maxLength);
}

/**
 * Validates numeric ID parameters
 * @param {string} id - The ID to validate
 * @returns {number|null} - Valid ID or null
 */
function validateId(id) {
  const parsed = parseInt(id, 10);
  if (!Number.isInteger(parsed) || parsed < 1) {
    return null;
  }
  return parsed;
}

// ============================================
// 3. LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  const requestId = uuidv4();
  req.id = requestId;

  // Log request
  console.log(`[${new Date().toISOString()}] [${requestId}] ${req.method} ${req.path}`);

  // Log response
  res.on('finish', () => {
    console.log(`[${new Date().toISOString()}] [${requestId}] Response: ${res.statusCode}`);
  });

  next();
});

// ============================================
// 4. ROUTES WITH VALIDATION
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      requestId: req.id
    });
  } catch (error) {
    console.error(`[${req.id}] Health check error:`, error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
