      page = validateId(req.query.page);
      if (page === null) {
        return res.status(400).json({
          error: 'Invalid page parameter',
          requestId: req.id
        });
      }
    }

    if (req.query.limit) {
      limit = validateId(req.query.limit);
      if (limit === null || limit > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter (must be 1-100)',
