// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    requestId: req.id
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[${req.id}] Unhandled error:`, err);

  // Don't expose internal error details to client
