// Load environment variables from .env file (only in development/test)
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}

/**
 * Define which environment variables are required
 */
const REQUIRED_ENV_VARS = {
  development: ['PORT'],
  test: ['PORT'],
  production: ['PORT', 'DATABASE_URL', 'NODE_ENV']
};

/**
 * Optional environment variables with defaults
 */
const OPTIONAL_ENV_VARS = {
  LOG_LEVEL: 'info',
  ALLOWED_ORIGINS: 'http://localhost:3000',
  JWT_SECRET: 'dev-secret-key-change-in-production',
  SESSION_SECRET: 'dev-session-secret-change-in-production'
};

/**
 * Validate that all required environment variables are set
 * @throws {Error} If required variables are missing
 */
function validateRequiredEnvVars() {
  const nodeEnv = process.env.NODE_ENV || 'development';
  const required = REQUIRED_ENV_VARS[nodeEnv] || REQUIRED_ENV_VARS.development;

  const missing = required.filter(varName => !process.env[varName]);

  if (missing.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missing.join(', ')}\n` +
      `See .env.example for configuration template`
    );
  }
}

/**
 * Configuration object
 */
const config = {
  // Server
  port: parseInt(process.env.PORT || '3000', 10),
  nodeEnv: process.env.NODE_ENV || 'development',
  isDevelopment: (process.env.NODE_ENV || 'development') === 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isTest: process.env.NODE_ENV === 'test',

  // Logging
  logLevel: process.env.LOG_LEVEL || 'info',

  // CORS
  allowedOrigins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000')
    .split(',')
    .map(origin => origin.trim()),

  // Database
  database: {
    url: process.env.DATABASE_URL || null
  },

  // AWS
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID || null,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || null,
    region: process.env.AWS_REGION || 'us-east-1'
  },

  // APIs
  apis: {
    anthropic: {
      apiKey: process.env.ANTHROPIC_API_KEY || null
    },
    stripe: {
      secretKey: process.env.STRIPE_SECRET_KEY || null
    },
    logfire: {
      token: process.env.LOGFIRE_TOKEN || null
    }
  },

  // Security
  security: {
    jwtSecret: process.env.JWT_SECRET || 'dev-secret-key-change-in-production',
    sessionSecret: process.env.SESSION_SECRET || 'dev-session-secret-change-in-production'
  }
};

/**
 * Validate configuration on load
 */
try {
  validateRequiredEnvVars();
} catch (error) {
  console.error('Configuration validation error:', error.message);
  if (config.isProduction) {
    // Fail hard in production
    process.exit(1);
  } else {
    // Warn in development/test
    console.warn('Warning: Some environment variables are not set');
  }
}

/**
 * Warn if using default secrets in production
 */
if (config.isProduction) {
  if (config.security.jwtSecret === 'dev-secret-key-change-in-production' ||
      config.security.sessionSecret === 'dev-session-secret-change-in-production') {
    throw new Error('ERROR: Default secret keys detected in production! Set JWT_SECRET and SESSION_SECRET.');
  }
}

/**
 * Freeze config to prevent accidental modifications
 */
Object.freeze(config);

module.exports = config;

