// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security headers
app.use(helmet());

// Parse request body with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// ============================================
// INPUT VALIDATION HELPER
// ============================================

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health',
  query('verbose')
    .optional()
    .isBoolean()
    .withMessage('verbose parameter must be a boolean'),
  handleValidationErrors,
  (req, res) => {
    try {
      const healthData = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        environment: NODE_ENV
      };

      if (req.query.verbose === 'true') {
        healthData.uptime = process.uptime();
        healthData.memory = process.memoryUsage();
      }

      res.json(healthData);
    } catch (error) {
      console.error('Health check error:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error'
      });
    }
  }
);

// Get users endpoint with validation
app.get('/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be a number between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('offset must be a non-negative number'),
  handleValidationErrors,
  (req, res) => {
    try {
      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;

      // Mock data - in production, this would come from a database with proper access control
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Validate pagination
      if (offset >= users.length && users.length > 0) {
        return res.status(400).json({
          success: false,
          message: 'offset exceeds available records'
        });
      }

      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: users.length
        }
      });
    } catch (error) {
      console.error('Get users error:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error'
      });
    }
  }
);

// ============================================
// ERROR HANDLING
// ============================================

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Resource not found',
    path: req.path
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details in production
  const message = NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    success: false,
    message,
    ...(NODE_ENV !== 'production' && { error: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} environment`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

module.exports = app;

// Example tests for the improved app
const request = require('supertest');
const app = require('./app.improved.js');

describe('Security & Validation Tests', () => {

  // ============================================
  // HEALTH CHECK TESTS
  // ============================================

  describe('GET /health', () => {
    it('should return 200 with status ok', async () => {
      const res = await request(app)
        .get('/health')
        .expect(200);

      expect(res.body).toHaveProperty('status', 'ok');
      expect(res.body).toHaveProperty('timestamp');
    });

    it('should reject invalid verbose parameter', async () => {
      const res = await request(app)
        .get('/health?verbose=invalid')
        .expect(400);

      expect(res.body.success).toBe(false);
      expect(res.body.errors).toBeDefined();
    });

    it('should accept valid verbose parameter', async () => {
      const res = await request(app)
        .get('/health?verbose=true')
        .expect(200);

      expect(res.body).toHaveProperty('uptime');
    });
  });

  // ============================================
  // USERS ENDPOINT TESTS
  // ============================================

  describe('GET /users', () => {
    it('should return array of users', async () => {
      const res = await request(app)
        .get('/users')
        .expect(200);

      expect(res.body.success).toBe(true);
      expect(Array.isArray(res.body.data)).toBe(true);
      expect(res.body.pagination).toBeDefined();
    });

    it('should reject invalid limit parameter', async () => {
      const res = await request(app)
        .get('/users?limit=invalid')
        .expect(400);

      expect(res.body.success).toBe(false);
    });

    it('should reject limit > 100', async () => {
      const res = await request(app)
        .get('/users?limit=101')
        .expect(400);

      expect(res.body.success).toBe(false);
      expect(res.body.errors[0].message).toContain('between 1 and 100');
    });

    it('should reject negative offset', async () => {
      const res = await request(app)
        .get('/users?offset=-1')
        .expect(400);

      expect(res.body.success).toBe(false);
    });

    it('should apply limit correctly', async () => {
      const res = await request(app)
        .get('/users?limit=1')
        .expect(200);

      expect(res.body.data.length).toBeLessThanOrEqual(1);
      expect(res.body.pagination.limit).toBe(1);
    });

    it('should apply offset correctly', async () => {
      const res = await request(app)
        .get('/users?offset=1')
        .expect(200);

      expect(res.body.pagination.offset).toBe(1);
    });

    it('should handle out of range offset', async () => {
      const res = await request(app)
        .get('/users?offset=999')
        .expect(400);

      expect(res.body.success).toBe(false);
    });
  });

  // ============================================
  // ERROR HANDLING TESTS
  // ============================================

  describe('Error Handling', () => {
    it('should return 404 for non-existent route', async () => {
      const res = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(res.body.success).toBe(false);
      expect(res.body.message).toContain('not found');
    });

    it('should return consistent error format', async () => {
      const res = await request(app)
        .get('/users?limit=invalid')
        .expect(400);

      expect(res.body).toHaveProperty('success');
      expect(res.body).toHaveProperty('errors');
      expect(Array.isArray(res.body.errors)).toBe(true);
    });
  });

  // ============================================
  // SECURITY HEADERS TESTS
  // ============================================

  describe('Security Headers', () => {
    it('should include X-Content-Type-Options header', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.headers['x-content-type-options']).toBe('nosniff');
    });

    it('should include X-Frame-Options header', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.headers['x-frame-options']).toBeDefined();
    });

    it('should not expose X-Powered-By header', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.headers['x-powered-by']).toBeUndefined();
    });
  });

  // ============================================
  // RESPONSE FORMAT TESTS
  // ============================================

  describe('Response Format', () => {
    it('should return JSON responses', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.type).toMatch(/json/);
    });

    it('should include success flag in responses', async () => {
      const healthRes = await request(app).get('/health');
      const usersRes = await request(app).get('/users');

      expect(healthRes.body).toHaveProperty('status');
      expect(usersRes.body).toHaveProperty('success', true);
    });
  });
});

