      const offset = parseInt(req.query.offset) || 0;

      // ... implementation
    } catch (error) {
      // ... error handling
    }
  }
);
```

**Benefits:**
- Validates all query parameters
- Enforces reasonable limits
- Prevents abuse
- Clear error messages

---

## 2. ERROR HANDLING

### ❌ BEFORE (No Error Handling)
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Issues:**
- No try-catch blocks
- No global error handler
- No 404 handling
- Unhandled errors crash the server
- No graceful shutdown

### ✅ AFTER (Proper Error Handling)
```javascript
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
    };
    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Resource not found'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(err.statusCode || 500).json({
    success: false,
    message: NODE_ENV === 'production' ? 'Internal server error' : err.message
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed');
  });
});
```

**Benefits:**
- Catches all errors
- Prevents server crashes
- Handles 404s gracefully
- Doesn't expose internal details
- Clean shutdown

---

## 3. SECURITY HEADERS

### ❌ BEFORE (No Security Headers)
```javascript
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

**Issues:**
- No protection against XSS attacks
- No clickjacking protection
- No content type sniffing protection
- Exposes server information

### ✅ AFTER (Security Headers Added)
```javascript
const helmet = require('helmet');

const app = express();
app.use(helmet());

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

**Headers Added:**
```
Strict-Transport-Security: max-age=15552000; includeSubDomains
X-Frame-Options: DENY
X-Content-Type-Options: nosniff
X-XSS-Protection: 1; mode=block
Content-Security-Policy: default-src 'self'
```

**Benefits:**
- Protection against major attack vectors
- Improved security posture
- Single line of code

---

## 4. RATE LIMITING

### ❌ BEFORE (No Rate Limiting)
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Issues:**
- Vulnerable to DoS attacks
- No protection against brute force
- Unlimited requests from single IP
- No throttling mechanism

### ✅ AFTER (Rate Limiting Enabled)
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                   // 100 requests
  message: 'Too many requests...'
});

app.use(limiter);

app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Response Headers:**
```
RateLimit-Limit: 100
RateLimit-Remaining: 95
RateLimit-Reset: 1234567890
```

**Benefits:**
- Prevents DoS attacks
- Protects against brute force
- Distributes load fairly
- Returns 429 status code

---

## 5. REQUEST SIZE LIMITS

### ❌ BEFORE (No Size Limits)
```javascript
const app = express();

app.use(express.json());
app.use(express.urlencoded({ extended: false }));
```

**Issues:**
- No limit on request body size
- Vulnerable to memory exhaustion
- Potential DoS vector
- Server can consume unlimited memory

### ✅ AFTER (Size Limits Enforced)
```javascript
const app = express();

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

**Benefits:**
- Prevents memory exhaustion
- Protects against DoS attacks
- Clear expectations for clients
- Reasonable defaults

---

## 6. CONFIGURATION & SECRETS

### ❌ BEFORE (Hardcoded Values)
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Issues:**
- Hardcoded port
- Can't change without modifying code
- Secrets exposed in source
- Not containerization-friendly

### ✅ AFTER (Environment-Based)
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const API_KEY = process.env.API_KEY; // Never hardcode

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV}`);
});
```

**.env File:**
```
PORT=3000
NODE_ENV=development
API_KEY=secret_key_here
DATABASE_URL=postgres://...
```

**Benefits:**
- Easy environment switching
- Secrets not in version control
- Containerization-ready
- Following 12-factor app principles

---

## 7. RESPONSE FORMAT

### ❌ BEFORE (Inconsistent Responses)
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' }
  ]);
});
```

**Issues:**
- Inconsistent response format
- No standard error responses
- Hard to parse for clients
- No success indicators

### ✅ AFTER (Consistent Format)
```javascript
// Success response
res.json({
  success: true,
  data: [...],
  pagination: { limit: 10, offset: 0, total: 2 }
});

// Error response
