// Improved application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// Set security headers
app.use(helmet());

// Body parser with size limits to prevent abuse
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============ ROUTES ============

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

app.get('/users',
  // Validation middleware
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),

  // Request handler
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    try {
      const mockUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const { id, limit = 10 } = req.query;

      // Filter by ID if provided
      let result = mockUsers;
      if (id) {
        result = mockUsers.filter(user => user.id === parseInt(id, 10));
        if (result.length === 0) {
          return res.status(404).json({ error: 'User not found' });
        }
      }

      // Apply limit
      result = result.slice(0, parseInt(limit, 10));

      res.json({
        success: true,
        data: result,
        count: result.length
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============ 404 HANDLER ============

app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// ============ GLOBAL ERROR HANDLER ============

app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't expose internal error details to client
  const status = error.status || 500;
  const message = error.status ? error.message : 'Internal server error';

  res.status(status).json({
    error: message,
    // Only include stack trace in development
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  });
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Optionally: send alert, log to monitoring service, etc.
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Graceful shutdown
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

# Security Review & Improvement Recommendations for app.js

## Executive Summary
The current app.js is minimal but lacks essential security controls. This review identifies vulnerabilities and provides actionable improvements.

---

## 🔴 CRITICAL ISSUES

### 1. No Global Error Handling
**Problem:** Unhandled errors crash the server or leak sensitive information
```javascript
// ❌ CURRENT: No error handler
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Solution:** Implement error handling middleware
```javascript
// ✅ IMPROVED
app.use((error, req, res, next) => {
  console.error('Error:', error);
  res.status(error.status || 500).json({ 
    error: 'Internal server error' 
  });
});
```

---

### 2. No Input Validation
**Problem:** Vulnerable to injection and abuse attacks
**Attack Example:**
- `/users?id=1%20OR%201=1` (SQL injection pattern)
- `/users?limit=999999999` (DoS via memory exhaustion)

**Solution:** Use express-validator
```javascript
// ✅ IMPROVED
query('id')
  .optional()
  .isInt({ min: 1 })
  .withMessage('ID must be a positive integer'),
query('limit')
  .optional()
  .isInt({ min: 1, max: 100 })
  .withMessage('Limit must be between 1 and 100'),
```

---

### 3. No Security Headers
**Problem:** Missing HTTP security headers for common attacks
- XSS attacks
- Clickjacking
- MIME-sniffing

**Solution:** Use helmet.js
```javascript
// ✅ IMPROVED
npm install helmet
app.use(helmet());
```

---

## 🟡 HIGH PRIORITY ISSUES

### 4. No Rate Limiting
**Problem:** Application vulnerable to brute force and DoS attacks

**Solution:** Implement rate limiting
```javascript
// ✅ IMPROVED
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100 // Max 100 requests per 15 minutes
});
app.use(limiter);
```

---

### 5. No Request Size Limits
**Problem:** Large payloads could exhaust server memory
```javascript
// ✅ IMPROVED
app.use(express.json({ limit: '10mb' }));
```

---

### 6. Missing 404 Handler
**Problem:** Unhandled routes return HTML instead of JSON
```javascript
// ✅ IMPROVED
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

## 🟠 MEDIUM PRIORITY ISSUES

### 7. No Try-Catch Blocks
**Problem:** Route handlers crash on errors
```javascript
// ✅ IMPROVED
app.get('/users', (req, res) => {
  try {
    // Handler logic
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

---

### 8. Sensitive Error Information Exposure
**Problem:** Stack traces and internal errors exposed to clients
```javascript
// ❌ BAD
res.json({ error: error.toString() }); // Exposes internals

// ✅ GOOD
res.status(500).json({ error: 'Internal server error' });
```

---

### 9. No Response Validation
**Problem:** Response structure not validated
```javascript
// ✅ IMPROVED
res.json({
  success: true,
  data: result,
  count: result.length
});
```

---

## 🟢 NICE-TO-HAVE IMPROVEMENTS

### 10. Logging & Monitoring
```javascript
// Add structured logging
const logger = require('winston');
logger.error('Error:', error);
```

### 11. CORS Configuration
```javascript
// If serving multiple origins
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true
}));
```

### 12. Request ID Tracking
```javascript
// For debugging and monitoring
const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = uuidv4();
  next();
});
```

### 13. Health Check Improvements
```javascript
// ✅ IMPROVED
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV
  });
});
```

---

## 📋 Dependencies to Install

```bash
npm install express helmet express-rate-limit express-validator
npm install --save-dev winston cors uuid
```

---

## 🔐 Security Best Practices Checklist

- [x] Global error handling middleware
- [x] Input validation on all parameters
- [x] Security headers (helmet.js)
- [x] Rate limiting
- [x] Request size limits
- [x] Try-catch blocks in handlers
- [x] Proper HTTP status codes
- [x] 404 handler
- [x] No sensitive error exposure
- [x] Unhandled promise rejection handler
- [x] Uncaught exception handler
- [x] Environment-based error verbosity

