  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// ============================================
// REQUEST LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next();
});

// ============================================
// ROUTES WITH INPUT VALIDATION
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any exist
    const { limit, offset } = req.query;

    // Input validation for optional parameters
    if (limit !== undefined) {
      if (!validator.isInt(limit, { min: 1, max: 100 })) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be an integer between 1 and 100.',
        });
      }
    }

    if (offset !== undefined) {
      if (!validator.isInt(offset, { min: 0 })) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative integer.',
        });
      }
    }

    // Mock data - in production, fetch from validated database queries
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if provided
    const parsedOffset = offset ? parseInt(offset, 10) : 0;
    const parsedLimit = limit ? parseInt(limit, 10) : 10;
    const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      data: paginatedUsers,
      total: users.length,
      limit: parsedLimit,
      offset: parsedOffset,
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

// Get user by ID with validation
app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Input validation
    if (!validator.isInt(id, { min: 1 })) {
      return res.status(400).json({
        error: 'Invalid user ID. Must be a positive integer.',
      });
    }

    const userId = parseInt(id, 10);

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find((u) => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ error: 'Failed to fetch user' });
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  const timestamp = new Date().toISOString();
  console.error(`[${timestamp}] Error:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message =
    process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message;

  res.status(statusCode).json({
    error: message,
    timestamp,
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Handle unhandled rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review and Improvements for app.js

## Executive Summary
The original app.js lacks critical security features, error handling, and input validation. This review addresses the top security concerns and provides best practices recommendations.

---

## Critical Issues Found

### 1. **No Error Handling** ⚠️ HIGH
**Problem:**
- Routes have no try-catch blocks
- No global error handler middleware
- Server crashes could occur on unhandled exceptions

**Solution:**
```javascript
// Add try-catch in routes
app.get('/users', (req, res) => {
  try {
    // route logic
  } catch (error) {
    console.error('Error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Add global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});
```

---

### 2. **No Input Validation** ⚠️ CRITICAL
**Problem:**
- No validation of query parameters
- No type checking
- Vulnerable to injection attacks
- No sanitization of user input

**Solution:**
```javascript
const validator = require('validator');

app.get('/users', (req, res) => {
  const { limit, offset } = req.query;

  // Validate integer parameters
  if (limit && !validator.isInt(limit, { min: 1, max: 100 })) {
    return res.status(400).json({ error: 'Invalid limit parameter' });
  }
});
```

**Recommendations:**
- Use validation libraries: `validator`, `joi`, or `express-validator`
- Implement type checking
- Sanitize all user inputs
- Use parameterized queries for database operations

---

### 3. **Missing Security Headers** ⚠️ CRITICAL
**Problem:**
- No HSTS, X-Frame-Options, or CSP headers
- Vulnerable to XSS, clickjacking, and other attacks

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets security headers automatically
```

**Headers Added:**
- `Strict-Transport-Security` (HSTS)
- `X-Frame-Options` (prevents clickjacking)
- `X-Content-Type-Options` (prevents MIME sniffing)
- `X-XSS-Protection`
- `Content-Security-Policy` (CSP)

---

### 4. **No Rate Limiting** ⚠️ HIGH
**Problem:**
- Vulnerable to brute force attacks
- DDoS attacks possible
- No protection against abuse

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests'
});

app.use(limiter);
```

---

### 5. **Sensitive Data Exposure** ⚠️ MEDIUM
**Problem:**
- User emails exposed without access control
- No authentication/authorization
- No data protection mechanism

**Recommendations:**
```javascript
// Add authentication middleware
app.get('/users', authenticateUser, (req, res) => {
  // Only authenticated users can see users list
});

// Implement role-based access control (RBAC)
// Implement field-level encryption for sensitive data
// Log access to sensitive endpoints
```

---

### 6. **No Request/Response Logging** ⚠️ MEDIUM
**Problem:**
- Cannot audit API usage
- Difficult to debug issues
- No security event tracking

**Solution:**
```javascript
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next();
});

// Use Morgan for production logging
const morgan = require('morgan');
app.use(morgan('combined'));
```

---

### 7. **Hardcoded Configuration** ⚠️ MEDIUM
**Problem:**
- Port hardcoded to 3000
- No environment-specific settings
- Secrets potentially exposed in code

**Solution:**
```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Use environment variables for all configuration
// Never commit .env files to version control
```

---

### 8. **No Request Size Limits** ⚠️ MEDIUM
**Problem:**
- Vulnerable to large payload attacks
- Memory exhaustion possible

**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 9. **No CORS Configuration** ⚠️ MEDIUM
**Problem:**
- No cross-origin request control
- Vulnerable to unauthorized access

**Solution:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
```

---

### 10. **No Graceful Shutdown** ⚠️ LOW
**Problem:**
- Incomplete requests may be lost during shutdown
- Database connections not properly closed

**Solution:**
```javascript
process.on('SIGTERM', () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

---

## Implementation Checklist

### Required Dependencies
```json
{
  "express": "^4.18.0",
  "helmet": "^7.0.0",
  "express-rate-limit": "^6.7.0",
  "validator": "^13.9.0",
  "cors": "^2.8.5",
  "morgan": "^1.10.0"
}
```

Install with:
```bash
npm install express helmet express-rate-limit validator cors morgan
```

### Environment Variables (.env)
```env
NODE_ENV=production
PORT=3000
ALLOWED_ORIGINS=https://yourdomain.com,https://app.yourdomain.com
LOG_LEVEL=info
```

### Configuration by Environment
| Setting | Development | Production |
|---------|-------------|-----------|
| Rate Limit | 1000 requests/15min | 100 requests/15min |
| Error Details | Full stack traces | Generic messages |
| CORS | * (all) | Specific domains |
| Logging | Console | File + monitoring |
| HTTPS | Optional | Required |

---

## Additional Security Recommendations

### 1. **Authentication & Authorization**
- Implement JWT or session-based authentication
- Use OAuth2 for third-party integrations
- Implement role-based access control (RBAC)

### 2. **Data Protection**
- Use HTTPS/TLS in production
- Encrypt sensitive data at rest
- Hash passwords with bcrypt or similar
- Implement database encryption

### 3. **API Security**
- API versioning (`/api/v1/users`)
- API key management for third-party access
- OpenAPI/Swagger documentation
- Request validation with JSON Schema

### 4. **Monitoring & Alerting**
- Application Performance Monitoring (APM)
- Error tracking (e.g., Sentry)
- Security event logging
- Intrusion detection

### 5. **Database Security**
- Use parameterized queries (prevent SQL injection)
- Principle of least privilege for DB users
- Regular backups and disaster recovery
- Data anonymization for logs

### 6. **Dependencies & Updates**
- Regular security audits: `npm audit`
- Keep dependencies updated
- Use lock files (package-lock.json)
- Scan for vulnerable packages

---

## Testing Recommendations

```javascript
// Example: Input validation tests
describe('GET /users/:id', () => {
  it('should reject non-integer IDs', async () => {
    const res = await request(app).get('/users/abc');
    expect(res.status).toBe(400);
  });

  it('should reject negative IDs', async () => {
    const res = await request(app).get('/users/-1');
    expect(res.status).toBe(400);
  });

  it('should return 404 for non-existent user', async () => {
    const res = await request(app).get('/users/9999');
    expect(res.status).toBe(404);
  });
});
```

---

