// Improved application with security best practices
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const cors = require('cors');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Helmet - Adds HTTP security headers
app.use(helmet());

// 2. CORS - Configure allowed origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};
app.use(cors(corsOptions));

// 3. Body Parser with size limits
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data Sanitization against NoSQL injection
app.use(mongoSanitize({
  replaceWith: '_',
  onSanitize: ({ req, key }) => {
    console.warn(`Suspicious data detected in ${key}`);
  }
}));

// 5. Rate Limiting - Prevent brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for sensitive endpoints
  skipSuccessfulRequests: true, // Only count failed requests
});

app.use('/api/', limiter);
app.use('/api/admin/', strictLimiter);

// ============ INPUT VALIDATION MIDDLEWARE ============

// Validation utility
const validateQuery = (schema) => {
  return (req, res, next) => {
    try {
      const validated = {};
      for (const [key, rule] of Object.entries(schema)) {
        const value = req.query[key];

        if (rule.required && !value) {
          return res.status(400).json({ 
            error: `Missing required query parameter: ${key}` 
          });
        }

        if (value) {
          if (rule.type === 'number') {
            const num = parseInt(value, 10);
            if (isNaN(num) || num < (rule.min || 0) || num > (rule.max || Infinity)) {
              return res.status(400).json({ 
                error: `Invalid ${key}: must be a number between ${rule.min || 0} and ${rule.max || 'infinity'}` 
              });
            }
            validated[key] = num;
          } else if (rule.type === 'string') {
            if (value.length > (rule.maxLength || 255)) {
              return res.status(400).json({ 
                error: `${key} exceeds maximum length of ${rule.maxLength || 255}` 
              });
            }
            validated[key] = validator.trim(value);
          }
        }
      }
      req.validated = validated;
      next();
    } catch (error) {
      res.status(400).json({ error: 'Invalid query parameters' });
    }
  };
};

// ============ LOGGING MIDDLEWARE ============

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// ============ ROUTES ============

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with validation
app.get('/api/users', validateQuery({
  limit: { type: 'number', min: 1, max: 100, required: false },
  offset: { type: 'number', min: 0, required: false }
}), (req, res) => {
  try {
    const limit = req.validated.limit || 10;
    const offset = req.validated.offset || 0;

    // In production, this would query a database with proper parameterization
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination safely
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Error in /api/users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get specific user with validation
app.get('/api/users/:id', (req, res) => {
  try {
    // Validate ID is a number
    const userId = parseInt(req.params.id, 10);
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Mock user lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    console.error('Error in /api/users/:id:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============ 404 HANDLER ============

app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// ============ GLOBAL ERROR HANDLER ============

app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details to client in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const message = isDevelopment ? err.message : 'Internal server error';

  res.status(err.status || 500).json({ 
    error: message,
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

