// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================
// Security & Middleware Setup
// ============================================

// 1. Add security headers using helmet
app.use(helmet());

// 2. Request logging (consider using structured logging in production)
app.use(morgan('combined'));

// 3. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 4. Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for sensitive endpoints
  message: 'Too many login attempts, please try again later.',
});

app.use(limiter);

// ============================================
// Health Check Endpoint
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    handleError(error, res, 'Health check failed');
  }
});

// ============================================
// Users Endpoint with Validation & Auth
// ============================================

app.get('/users', 
  // Input validation middleware
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),

  // Validation error handler
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }
    next();
  },

  // Authentication middleware (example - customize as needed)
  (req, res, next) => {
    const apiKey = req.headers['x-api-key'];
    if (!apiKey || apiKey !== process.env.API_KEY) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    next();
  },

  // Main handler with error handling
  (req, res) => {
    try {
      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;

      // Mock user data (in production, fetch from secure database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const paginatedUsers = allUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: allUsers.length
        }
      });
    } catch (error) {
      handleError(error, res, 'Failed to fetch users');
    }
  }
);

// ============================================
// 404 Handler
// ============================================

app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path 
  });
});

// ============================================
// Global Error Handler
// ============================================

app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    ...(isDevelopment && { message: err.message, stack: err.stack })
  });
});

// ============================================
// Helper Functions
// ============================================

function handleError(error, res, message) {
  console.error(message, error);
  res.status(500).json({ 
    error: message,
    ...(process.env.NODE_ENV === 'development' && { details: error.message })
  });
}

// ============================================
// Server Startup
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js - Detailed Recommendations

## Executive Summary
The current app.js is a minimal Express application with significant security gaps. Below are detailed recommendations organized by severity.

---

## 🔴 CRITICAL Issues

### 1. No Input Validation
**Current State:**
```javascript
app.get('/users', (req, res) => {
  // No validation of query parameters
});
```

**Risk:** Query parameter injection, unexpected data types, resource exhaustion

**Solution:** Use `express-validator` to validate all inputs
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
