// Improved application with security best practices
// Error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ============ SECURITY MIDDLEWARE ============

// Set security HTTP headers
app.use(helmet());

// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // Stricter limit for sensitive endpoints
  message: 'Too many login attempts, please try again later',
});

// Apply rate limiting to all routes
app.use(limiter);

// CORS configuration (restrict to trusted origins)
app.use((req, res, next) => {
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  }
  next();
});

// ============ ROUTES ============

/**
 * Health check endpoint - minimal data exposure
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

/**
 * Users endpoint - with pagination and input validation
 */
app.get('/users',
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  (req, res, next) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid input parameters',
          errors: errors.array()
        });
      }

      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const skip = (page - 1) * limit;

      // Mock data (in production, query a database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      const paginatedUsers = allUsers.slice(skip, skip + limit);

      res.json({
        status: 'success',
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: allUsers.length,
          hasMore: skip + limit < allUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * Example POST endpoint with input validation
 */
app.post('/users',
  strictLimiter,
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .escape(), // Sanitize to prevent XSS
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .normalizeEmail(),
  (req, res, next) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          status: 'error',
          message: 'Validation failed',
          errors: errors.array()
        });
      }

      // In production, validate authorization and save to database
      const { name, email } = req.body;
      const newUser = {
        id: 4,
        name,
        email
      };

      res.status(201).json({
        status: 'success',
        data: newUser,
        message: 'User created successfully'
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============ ERROR HANDLING ============

/**
 * 404 - Not Found middleware
 */
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Resource not found',
    path: req.path
  });
});

/**
 * Global error handling middleware
 * Must be defined last and with 4 parameters
 */
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Default error
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal server error';

  // Don't expose sensitive error details in production
  if (process.env.NODE_ENV === 'production') {
    message = statusCode === 500 ? 'Internal server error' : message;
  }

  res.status(statusCode).json({
    status: 'error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============ SERVER START ============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Recommendations for app.js

## Executive Summary
The original app.js is a minimal application missing critical security features. This document outlines vulnerabilities and improvements.

---

## Critical Issues Found

### 1. **No Error Handling** ❌
**Problem**: Unhandled errors can crash the application or leak sensitive information.
```javascript
// ❌ BEFORE: No error handling
app.get('/users', (req, res) => {
  res.json([...]); // If this fails, no error handling
});
```

**Solution**: Implement global error handling middleware
```javascript
// ✅ AFTER: Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  res.status(500).json({ status: 'error', message: 'Internal server error' });
});
```

---

### 2. **Missing Input Validation** ❌
**Problem**: No validation of query parameters or request bodies opens the door to injection attacks.
```javascript
// ❌ BEFORE: No validation
app.get('/users', (req, res) => {
  // What if someone passes /users?page=<script>alert('xss')</script>?
  res.json([...]);
});
```

**Solution**: Use express-validator for input validation
```javascript
// ✅ AFTER: Validate and sanitize input
app.get('/users',
  query('page').optional().isInt({ min: 1 }).withMessage('Invalid page'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use validated input
  }
);
```

---

### 3. **No Security Headers** ❌
**Problem**: Missing HTTP security headers expose the application to various attacks.
- XSS attacks (no X-Frame-Options)
- Clickjacking (no X-Frame-Options)
- MIME sniffing (no X-Content-Type-Options)
- Insecure connections (no Strict-Transport-Security)

**Solution**: Use Helmet.js
```javascript
// ✅ Install and use Helmet
const helmet = require('helmet');
app.use(helmet());
```

---

### 4. **No Rate Limiting** ❌
**Problem**: Application is vulnerable to brute force and DoS attacks.
```javascript
// ❌ BEFORE: Anyone can make unlimited requests
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Solution**: Implement rate limiting
```javascript
// ✅ AFTER: Limit requests per IP
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // 100 requests per IP
});
app.use(limiter);
```

---

### 5. **No Request Size Limits** ❌
**Problem**: Attackers can send massive payloads causing memory exhaustion.
```javascript
// ❌ BEFORE: Unlimited body size
app.use(express.json());
```

**Solution**: Set size limits
```javascript
// ✅ AFTER: Limit to 10kb
app.use(express.json({ limit: '10kb' }));
```

---

### 6. **No CORS Configuration** ❌
**Problem**: Without proper CORS configuration, the API is either open to any origin or incorrectly configured.
```javascript
// ❌ BEFORE: No CORS control
// This allows any website to access your API
```

**Solution**: Implement strict CORS
```javascript
// ✅ AFTER: Only allow trusted origins
const allowedOrigins = ['https://yourdomain.com'];
if (allowedOrigins.includes(req.headers.origin)) {
  res.setHeader('Access-Control-Allow-Origin', req.headers.origin);
}
```

---

### 7. **Information Disclosure** ❌
**Problem**: Error messages and responses leak sensitive information.
```javascript
// ❌ BEFORE: Exposes full error stack
app.use((err, req, res) => {
  res.json({ error: err.stack }); // Shows internal code paths
});
```

**Solution**: Generic errors in production
```javascript
// ✅ AFTER: Hide details in production
app.use((err, req, res) => {
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;
  res.status(500).json({ error: message });
});
```

---

### 8. **No Authentication/Authorization** ❌
**Problem**: All endpoints are publicly accessible without verification.
```javascript
// ❌ BEFORE: Public endpoints
app.get('/users', (req, res) => {
  res.json([...]); // Anyone can see all users
});
```

**Solution**: Add authentication middleware
```javascript
// ✅ AFTER: Require valid token
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token || !validateToken(token)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
};
app.get('/users', authMiddleware, (req, res) => {
  res.json([...]);
});
```

---

### 9. **No Logging/Monitoring** ❌
**Problem**: Cannot detect or investigate security incidents.
```javascript
// ✅ Add comprehensive logging
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip,
    error: err.message,
    userId: req.userId // If authenticated
  });
  // Send to monitoring service
});
```

