/**
 * Improved Express application with security best practices
 * - Comprehensive error handling
 * - Input validation
 * - Security headers
 * - Rate limiting
 * - Proper logging
 */

const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const validator = require('validator');
require('dotenv').config();

const app = express();

// ============================================================================
// MIDDLEWARE SETUP
// ============================================================================

// Security: Set HTTP headers
app.use(helmet());

// CORS configuration - restrict to specific origins
const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  }
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payloads
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection and XSS
app.use(mongoSanitize());
app.use(xss());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks (optional)
    return req.path === '/health';
  },
});

app.use('/api/', limiter);

// ============================================================================
// CUSTOM MIDDLEWARE & UTILITIES
// ============================================================================

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Input validation utility
const validateEmail = (email) => {
  return validator.isEmail(email) && email.length <= 254; // RFC 5321
};

const validateUserId = (id) => {
  return Number.isInteger(parseInt(id, 10)) && parseInt(id, 10) > 0;
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Health check error:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get all users endpoint
 * GET /api/users
 */
app.get('/api/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      success: true,
      data: users,
      count: users.length,
    });
  } catch (error) {
    console.error('Get users error:', error.message);
    res.status(500).json({
      success: false,
      error: 'Failed to retrieve users',
    });
  }
});

/**
 * Get user by ID endpoint
 * GET /api/users/:id
 */
app.get('/api/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Input validation
    if (!validateUserId(id)) {
      return res.status(400).json({
        success: false,
        error: 'Invalid user ID format',
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find((u) => u.id === parseInt(id, 10));

    if (!user) {
      return res.status(404).json({
        success: false,
        error: 'User not found',
      });
    }

    res.json({
      success: true,
      data: user,
    });
  } catch (error) {
    console.error('Get user error:', error.message);
    res.status(500).json({
      success: false,
      error: 'Failed to retrieve user',
    });
  }
});

/**
 * Create user endpoint (example with validation)
 * POST /api/users
 */
app.post('/api/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    const errors = [];

    if (!name || typeof name !== 'string') {
      errors.push('Name is required and must be a string');
    } else if (name.trim().length === 0) {
      errors.push('Name cannot be empty or whitespace only');
    } else if (name.length > 100) {
      errors.push('Name must be 100 characters or less');
    }

    if (!email || typeof email !== 'string') {
      errors.push('Email is required and must be a string');
    } else if (!validateEmail(email)) {
      errors.push('Invalid email format');
    }

    if (errors.length > 0) {
      return res.status(400).json({
        success: false,
        errors: errors,
      });
    }

    // Sanitize inputs (additional layer)
    const sanitizedName = validator.trim(validator.escape(name));
    const sanitizedEmail = validator.trim(validator.normalizeEmail(email));

    // Mock user creation (in real app, save to database)
    const newUser = {
      id: Math.floor(Math.random() * 10000) + 3,
      name: sanitizedName,
      email: sanitizedEmail,
    };

    res.status(201).json({
      success: true,
      data: newUser,
      message: 'User created successfully',
    });
  } catch (error) {
    console.error('Create user error:', error.message);
    res.status(500).json({
      success: false,
      error: 'Failed to create user',
    });
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * 404 handler - must be last non-error middleware
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
    path: req.path,
  });
});

/**
 * Global error handler - must be last
 */
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Default error values
  let statusCode = err.statusCode || 500;
  let message = 'An unexpected error occurred';

  // Specific error handling
  if (err.message === 'PayloadTooLargeError') {
    statusCode = 413;
    message = 'Request body is too large';
  } else if (err instanceof SyntaxError && 'body' in err) {
    statusCode = 400;
    message = 'Invalid JSON format';
  }

  // Never expose sensitive error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    success: false,
    error: message,
    ...(isDevelopment && { details: err.message }),
  };

  res.status(statusCode).json(errorResponse);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js - Improvements & Best Practices

## Executive Summary
The original `app.js` is minimal but lacks critical security controls. This document outlines vulnerabilities and improvements implemented.

---

## Critical Issues Found

### 1. **NO ERROR HANDLING** ⚠️ CRITICAL
**Problem:**
- No try-catch blocks
- No error middleware
- Unhandled exceptions crash the server
- No logging of errors

**Risk:** Application crashes, loss of availability, poor debugging

**Solution:**
```javascript
// Add try-catch to all route handlers
app.get('/users', (req, res) => {
  try {
    // your code
  } catch (error) {
    console.error('Error:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Add global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ error: 'Internal server error' });
});
```

---

### 2. **NO INPUT VALIDATION** ⚠️ HIGH
**Problem:**
- No validation of query parameters, path parameters, or request bodies
- Vulnerable to injection attacks
- No type checking
- No length limits

**Risk:** Injection attacks, NoSQL injection, XSS attacks

**Solution:**
```javascript
const validator = require('validator');

// Validate before use
if (!Number.isInteger(parseInt(id, 10)) || parseInt(id, 10) <= 0) {
  return res.status(400).json({ error: 'Invalid ID' });
}

// Sanitize user input
const sanitized = validator.escape(input);
const normalized = validator.normalizeEmail(email);
```

---

### 3. **MISSING SECURITY HEADERS** ⚠️ HIGH
**Problem:**
- No Content Security Policy (CSP)
- No X-Frame-Options
- No X-Content-Type-Options
- No HSTS
- Vulnerable to clickjacking, MIME-type sniffing, etc.

**Risk:** XSS, clickjacking, MIME-type confusion attacks

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets ~15 security headers
```

---

### 4. **NO RATE LIMITING** ⚠️ MEDIUM
**Problem:**
- Endpoints vulnerable to brute force attacks
- No protection against DoS/DDoS
- No request throttling

**Risk:** Denial of Service, brute force attacks, resource exhaustion

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // 100 requests per IP per 15 minutes
});

app.use('/api/', limiter);
```

---

### 5. **NO REQUEST SIZE LIMITS** ⚠️ MEDIUM
**Problem:**
- Can accept arbitrarily large payloads
- Vulnerable to memory exhaustion attacks
- No limit on JSON body size

**Risk:** Memory exhaustion, DoS attacks

**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 6. **NO DATA SANITIZATION** ⚠️ HIGH
**Problem:**
- No protection against NoSQL injection
- No XSS sanitization
- Vulnerable if user input goes to database queries

**Risk:** NoSQL injection, XSS attacks

**Solution:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

app.use(mongoSanitize()); // Removes $ and . from data
app.use(xss()); // Sanitizes HTML/scripts
```

---

### 7. **MISSING CORS CONFIGURATION** ⚠️ MEDIUM
**Problem:**
- No Cross-Origin Resource Sharing policy
- Either too permissive or missing
- Vulnerable to cross-site requests

**Risk:** CSRF attacks, unauthorized data access from other origins

**Solution:**
```javascript
const allowedOrigins = ['https://example.com'];

app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  }
  next();
});
```

---

### 8. **HARDCODED CONFIGURATION** ⚠️ MEDIUM
**Problem:**
- Port hardcoded (3000)
- No environment variable support
- Difficult to deploy to different environments

**Risk:** Configuration inflexibility, potential secret exposure

**Solution:**
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

---

### 9. **VERBOSE ERROR MESSAGES** ⚠️ MEDIUM
**Problem:**
- Could expose stack traces in production
- Reveals system information to attackers

**Risk:** Information disclosure

**Solution:**
```javascript
const isDevelopment = process.env.NODE_ENV === 'development';

const errorResponse = {
  success: false,
  error: message,
  ...(isDevelopment && { details: err.message }), // Only in dev
};
```

---

### 10. **NO LOGGING** ⚠️ LOW
**Problem:**
- Difficult to debug issues
- No audit trail
- Can't monitor for suspicious activity

**Risk:** Poor observability, no security audit trail

**Solution:**
```javascript
// Add basic logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Or use winston/morgan for production-grade logging
const morgan = require('morgan');
app.use(morgan('combined'));
```

---

### 11. **NO UNHANDLED REJECTION HANDLING** ⚠️ MEDIUM
**Problem:**
- Unhandled promise rejections crash the process
- No graceful shutdown mechanism

**Risk:** Unexpected downtime, data loss

**Solution:**
```javascript
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});

process.on('SIGTERM', () => {
  console.log('Shutting down gracefully...');
  server.close(() => process.exit(0));
});
```

---

## Required Dependencies

Add these to `package.json`:

```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.7.0",
    "express-mongo-sanitize": "^2.2.0",
    "xss-clean": "^0.1.1",
    "validator": "^13.9.0",
    "dotenv": "^16.0.3"
  },
  "devDependencies": {
    "nodemon": "^2.0.22"
  }
}
```

Install with: `npm install`

---

## Environment Configuration

Create `.env` file:

```env
# Server Configuration
PORT=3000
NODE_ENV=production

# Security
ALLOWED_ORIGINS=https://example.com,https://app.example.com

# Database (when applicable)
DATABASE_URL=mongodb://localhost:27017/myapp
```

Create `.env.example` (no secrets):

```env
PORT=3000
NODE_ENV=development
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:3001
DATABASE_URL=
```

---

## Testing Recommendations

### 1. Unit Tests
```javascript
// Test input validation
describe('Input Validation', () => {
  it('should reject invalid user IDs', () => {
    // Test with: -1, 0, "abc", null, undefined
  });

  it('should reject malformed emails', () => {
    // Test with: "not-an-email", "test@", "@test.com"
  });
});
```

### 2. Security Tests
```javascript
// Test rate limiting
// Test CORS headers
// Test XSS prevention
// Test NoSQL injection prevention
```

### 3. Load Testing
```bash
# Use Apache Bench or autocannon
ab -n 1000 -c 10 http://localhost:3000/health
```

---

## Deployment Checklist

- [ ] Set `NODE_ENV=production`
- [ ] Use strong `ALLOWED_ORIGINS` (no wildcards)
- [ ] Enable HTTPS/TLS
- [ ] Set up monitoring and alerting
- [ ] Configure logging to persistent storage
- [ ] Use environment variables for all secrets
- [ ] Run security audit: `npm audit`
- [ ] Set up automated testing
- [ ] Enable helmet security headers
- [ ] Configure rate limiting for your use case
- [ ] Set up graceful shutdown handlers
- [ ] Use process manager (PM2, supervisor)
- [ ] Keep dependencies updated

---

## Additional Security Measures (Not in Code)

1. **HTTPS/TLS:** Always use HTTPS in production
2. **Database:** Use parameterized queries, prepared statements
3. **Authentication:** Implement JWT, OAuth, or similar
4. **Authorization:** Implement role-based access control (RBAC)
5. **Secrets Management:** Use vault solutions, never commit secrets
6. **Monitoring:** Implement real-time alerting for errors/attacks
7. **API Documentation:** Use OpenAPI/Swagger for clarity
8. **Dependency Management:** Keep packages updated, use `npm audit`
9. **Code Review:** Implement peer review process
10. **Security Training:** Regular training for development team

---

## Resources

- [OWASP Top 10](https://owasp.org/Top10/)
- [Node.js Security Checklist](https://blog.risingstack.com/node-js-security-checklist/)
- [Express.js Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Helmet.js Documentation](https://helmetjs.github.io/)
- [Validator.js Documentation](https://github.com/validatorjs/validator.js)

---

## Conclusion

The improved version implements industry best practices including:
✅ Comprehensive error handling  
✅ Input validation and sanitization  
✅ Security headers  
✅ Rate limiting  
✅ Proper logging  
✅ Environment configuration  
✅ Graceful shutdown  
✅ Process-level error handling  

Use `app_improved.js` as a foundation for production-grade applications.

