// Improved application with security best practices
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const { body, validationResult } = require('express-validator');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Helmet - Sets various HTTP headers for security
app.use(helmet());

// 2. Rate Limiting - Prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter limit for auth endpoints
  skipSuccessfulRequests: true,
});

app.use(limiter);

// 3. Body Parser with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payloads
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ========== VALIDATION MIDDLEWARE ==========

// Custom validation helpers
const validateUserId = (id) => {
  const parsed = parseInt(id, 10);
  if (isNaN(parsed) || parsed <= 0) {
    throw new Error('Invalid user ID');
  }
  return parsed;
};

const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new Error('Invalid email format');
  }
  return email.toLowerCase();
};

// ========== ERROR HANDLING MIDDLEWARE ==========

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ========== ROUTES ==========

// Health check endpoint
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    next(error);
  }
});

// Get all users (with authorization in real app)
app.get('/users', (req, res, next) => {
  try {
    // In a real application, validate user authorization here
    // if (!isUserAuthorized(req)) {
    //   return res.status(403).json({ error: 'Forbidden' });
    // }

    // Validate optional query parameters
    const limit = req.query.limit
      ? parseInt(req.query.limit, 10)
      : 100;
    const offset = req.query.offset
      ? parseInt(req.query.offset, 10)
      : 0;

    // Validate pagination parameters
    if (isNaN(limit) || limit < 1 || limit > 1000) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 1000.',
      });
    }

    if (isNaN(offset) || offset < 0) {
      return res.status(400).json({
        error: 'Invalid offset parameter. Must be non-negative.',
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
      },
    });
  } catch (error) {
    next(error);
  }
});

// Get a single user by ID with validation
app.get('/users/:id', 
  [
    body('id').custom(validateUserId),
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Validate user ID
      if (isNaN(userId) || userId <= 0) {
        return res.status(400).json({
          error: 'Invalid user ID. Must be a positive integer.',
        });
      }

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
        });
      }

      res.json({ data: user });
    } catch (error) {
      next(error);
    }
  }
);

// Create user endpoint with validation
app.post('/users',
  authLimiter,
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters'),
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format'),
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // Additional sanitization
      const sanitizedName = name.replace(/[<>\"']/g, '');
      const sanitizedEmail = email.toLowerCase();

      // In a real app, save to database with error handling
      const newUser = {
        id: 3, // Would be generated by database
        name: sanitizedName,
        email: sanitizedEmail,
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (error) {
      next(error);
    }
  }
);

// ========== 404 HANDLER ==========
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

// ========== GLOBAL ERROR HANDLER ==========
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Don't expose error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'development'
    ? err.message
    : 'An internal server error occurred';

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ========== SERVER STARTUP ==========
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  server.close(() => process.exit(1));
});

