// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// ===== SECURITY MIDDLEWARE =====

// Set security HTTP headers
app.use(helmet());

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb' }));

// ===== REQUEST LOGGING MIDDLEWARE =====
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ===== ROUTES =====

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Error in /health endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Users endpoint - with validation and error handling
 * NOTE: In production, add authentication middleware here
 */
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const { limit = 10, offset = 0 } = req.query;

    // Validate numeric parameters
    const limitNum = parseInt(limit, 10);
    const offsetNum = parseInt(offset, 10);

    if (isNaN(limitNum) || isNaN(offsetNum)) {
      return res.status(400).json({
        error: 'Invalid pagination parameters. Limit and offset must be numbers.',
      });
    }

    if (limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Limit must be between 1 and 100',
      });
    }

    if (offsetNum < 0) {
      return res.status(400).json({
        error: 'Offset must be non-negative',
      });
    }

    // Mock data (in production, would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(offsetNum, offsetNum + limitNum);

    res.json({
      data: users,
      pagination: {
        limit: limitNum,
        offset: offsetNum,
        total: allUsers.length,
      },
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Example of a POST endpoint with input validation
 */
app.post('/users', express.json(), (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || !email) {
      return res.status(400).json({
        error: 'Missing required fields: name and email',
      });
    }

    // Type checking
    if (typeof name !== 'string' || typeof email !== 'string') {
      return res.status(400).json({
        error: 'Name and email must be strings',
      });
    }

    // Length validation
    if (name.trim().length === 0 || name.length > 100) {
      return res.status(400).json({
        error: 'Name must be between 1 and 100 characters',
      });
    }

    // Email validation
    if (!validator.isEmail(email)) {
      return res.status(400).json({
        error: 'Invalid email format',
      });
    }

    // Sanitize inputs
    const sanitizedName = validator.trim(validator.escape(name));
    const sanitizedEmail = validator.normalizeEmail(email);

    // Process valid data (in production, save to database)
    console.log(`Creating user: ${sanitizedName} (${sanitizedEmail})`);

    res.status(201).json({
      message: 'User created successfully',
      user: {
        id: Math.floor(Math.random() * 10000),
        name: sanitizedName,
        email: sanitizedEmail,
      },
    });
  } catch (error) {
    console.error('Error in POST /users endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ===== ERROR HANDLING MIDDLEWARE =====

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Resource not found',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details to clients
  const statusCode = err.statusCode || 500;
  const message = err.statusCode ? err.message : 'Internal server error';

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { details: err.message }),
  });
});

// ===== SERVER STARTUP =====

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js - Recommendations

## Summary
The current `app.js` lacks critical security controls including input validation, error handling, rate limiting, and secure headers. This document outlines vulnerabilities and best practices.

---

## 1. SECURITY VULNERABILITIES

### 🔴 Critical Issues

| Issue | Severity | Impact |
|-------|----------|--------|
| No input validation | HIGH | Injection attacks, data corruption |
| No error handling | HIGH | Information disclosure, crashes |
| Missing security headers | HIGH | XSS, Clickjacking, MIME sniffing |
| No authentication/authorization | HIGH | Unauthorized data access |
| No rate limiting | HIGH | DOS/DDOS attacks, resource exhaustion |
| Exposed sensitive data | MEDIUM | Privacy violation (emails exposed) |
| No request size limits | MEDIUM | Memory exhaustion attacks |
| No logging/monitoring | MEDIUM | Inability to detect attacks |

---

## 2. RECOMMENDED PACKAGES

```bash
npm install helmet express-rate-limit express-mongo-sanitize validator
```

**Package purposes:**
- `helmet`: Secures Express.js by setting various HTTP headers
- `express-rate-limit`: Implements rate limiting to prevent DOS attacks
- `express-mongo-sanitize`: Removes prohibited characters from user inputs
- `validator`: Provides input validation and sanitization utilities

---

## 3. SECURITY IMPROVEMENTS IMPLEMENTED

### A. Security Headers (Helmet)
```javascript
app.use(helmet());
```
**Protects against:**
- XSS attacks (Content-Security-Policy)
- Clickjacking (X-Frame-Options)
- MIME sniffing (X-Content-Type-Options)
- DNS prefetching (X-DNS-Prefetch-Control)

### B. Rate Limiting
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);
```
**Protects against:**
- Brute force attacks
- DOS/DDOS attacks
- Resource exhaustion

### C. Input Validation
```javascript
// Type checking
if (typeof email !== 'string') {
  return res.status(400).json({ error: 'Invalid type' });
}

// Format validation
if (!validator.isEmail(email)) {
  return res.status(400).json({ error: 'Invalid email format' });
}
```
**Protects against:**
- SQL/NoSQL injection
- Invalid data processing
- Type confusion attacks

### D. Input Sanitization
```javascript
const sanitizedName = validator.escape(name);
const sanitizedEmail = validator.normalizeEmail(email);
```
**Protects against:**
- XSS attacks
- Malformed data storage
- Invalid formats

### E. Error Handling
```javascript
try {
  // endpoint logic
} catch (error) {
  console.error('Error:', error);
  res.status(500).json({ error: 'Internal server error' });
}
```
**Prevents:**
- Stack trace leakage (information disclosure)
- Unexpected crashes
- Compromised stability

### F. Request Size Limits
```javascript
app.use(express.json({ limit: '10kb' }));
```
**Protects against:**
- Memory exhaustion
- Large payload DOS attacks

### G. Data Sanitization
```javascript
app.use(mongoSanitize());
```
**Protects against:**
- NoSQL injection
- Prototype pollution

### H. Request Logging
```javascript
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});
```
**Benefits:**
- Audit trail for security incidents
- Performance monitoring
- Attack pattern detection

### I. Graceful Shutdown
```javascript
process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
});
```
**Benefits:**
- Clean connection closure
- In-flight request handling
- Database connection cleanup

---

## 4. ADDITIONAL RECOMMENDATIONS FOR PRODUCTION

### Authentication & Authorization
```javascript
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.sendStatus(401);

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
};

app.get('/users', authenticateToken, (req, res) => {
  // protected route
});
```

### HTTPS Only
```javascript
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync('path/to/key.pem'),
  cert: fs.readFileSync('path/to/cert.pem'),
};

https.createServer(options, app).listen(443);
```

### Environment Variables
```bash
# .env
PORT=3000
NODE_ENV=production
DB_URL=mongodb://...
API_KEY=...
```

**Never commit sensitive data to version control!**

### CORS Configuration
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));
```

### Request Validation Middleware
```javascript
const { body, validationResult } = require('express-validator');

app.post('/users',
  body('email').isEmail().normalizeEmail(),
  body('name').trim().escape().isLength({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // process request
  }
);
```

### Logging & Monitoring
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Use logger throughout app
logger.error('Error occurred:', error);
```

---

## 5. TESTING CHECKLIST

- [ ] Test with invalid input types (strings instead of numbers, etc.)
- [ ] Test with malicious payloads (SQL injection, XSS attempts)
- [ ] Test rate limiting (send >100 requests in 15 min window)
- [ ] Test with oversized payloads (>10kb)
- [ ] Test error handling (cause exceptions)
- [ ] Verify security headers are present (use curl -i)
- [ ] Test CORS policies
- [ ] Verify sensitive data isn't exposed in errors
- [ ] Load testing for performance under stress
- [ ] Test graceful shutdown

---

## 6. SECURITY HEADERS VERIFICATION

Test security headers:
```bash
curl -i http://localhost:3000/health
```

Expected headers:
```
X-Content-Type-Options: nosniff
X-Frame-Options: DENY
X-XSS-Protection: 0
Strict-Transport-Security: max-age=15552000; includeSubDomains
```

---

## 7. DEPLOYMENT CHECKLIST

- [ ] Set `NODE_ENV=production`
- [ ] Use HTTPS with valid certificates
- [ ] Enable rate limiting (adjust limits for production)
- [ ] Set up monitoring and alerting
- [ ] Configure environment variables securely
- [ ] Use a reverse proxy (nginx/Apache)
- [ ] Enable CORS with specific allowed origins
- [ ] Set up database authentication
- [ ] Use secrets management (AWS Secrets Manager, HashiCorp Vault)
- [ ] Implement audit logging
- [ ] Set up intrusion detection
- [ ] Regular security updates

---

## References

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express.js Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Node.js Security Best Practices](https://nodejs.org/en/docs/guides/security/)
- [CWE Top 25](https://cwe.mitre.org/top25/)

