app.get('/api/users', (req, res) => {
  try {
    // Validate query parameters
    const { limit = 10, offset = 0 } = req.query;

    // Input validation
    if (!Number.isInteger(parseInt(limit)) || parseInt(limit) < 1 || parseInt(limit) > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        details: 'Limit must be an integer between 1 and 100',
      });
    }

    if (!Number.isInteger(parseInt(offset)) || parseInt(offset) < 0) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        details: 'Offset must be a non-negative integer',
      });
    }

    const parsedLimit = parseInt(limit);
    const parsedOffset = parseInt(offset);

    // Mock data (in production, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    // Don't expose sensitive data unnecessarily
    const sanitizedUsers = users.map(user => ({
