      name: validator.escape(user.name), // Prevent XSS
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: allUsers.length,
      },
    });
  } catch (error) {
    handleError(res, error, 'Failed to fetch users', 500);
  }
});

// Get specific user by ID with validation
