// Enhanced application with security best practices
// Implements proper error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const validator = require('validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// CORS configuration
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body size limit to prevent denial of service
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

/**
 * Validates user ID format
 * @param {*} id - The ID to validate
 * @returns {boolean} True if valid
 */
function isValidId(id) {
  return Number.isInteger(parseInt(id)) && parseInt(id) > 0;
}

/**
 * Sanitizes string input
 * @param {string} input - The input to sanitize
 * @returns {string} Sanitized string
 */
function sanitizeString(input) {
  if (typeof input !== 'string') return '';
  return input.trim().substring(0, 255);
}

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error'
    });
  }
});

/**
 * Get all users
 * Supports optional filtering by name
 */
app.get('/users', (req, res) => {
  try {
    // Mock user database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Validate and sanitize query parameters
    const nameFilter = req.query.name ? sanitizeString(req.query.name) : null;

    // Input validation
    if (nameFilter && nameFilter.length > 100) {
      return res.status(400).json({
        status: 'error',
        message: 'Name filter is too long'
      });
    }

    // Filter users by name if provided
    let users = allUsers;
    if (nameFilter) {
      users = allUsers.filter(user =>
        user.name.toLowerCase().includes(nameFilter.toLowerCase())
      );
    }

    res.json({
      status: 'success',
      count: users.length,
      data: users
    });
  } catch (error) {
    console.error('Get users error:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve users'
    });
  }
});

/**
 * Get a specific user by ID
 */
app.get('/users/:id', (req, res) => {
  try {
    // Validate ID format
    if (!isValidId(req.params.id)) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid user ID format'
      });
    }

    const userId = parseInt(req.params.id, 10);

    // Mock user database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = allUsers.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found'
      });
    }

    res.json({
      status: 'success',
      data: user
    });
  } catch (error) {
    console.error('Get user error:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve user'
    });
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found'
  });
});

/**
 * Global error handling middleware
 * Must be defined last
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    method: req.method,
    path: req.path
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Don't expose internal error details to clients
  const isDevelopment = process.env.NODE_ENV === 'development';
  const clientMessage = isDevelopment ? err.message : 'Internal server error';

  res.status(statusCode).json({
    status: 'error',
    message: clientMessage
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  process.exit(1);
});

module.exports = app;

