// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// Trust proxy (if behind reverse proxy)
app.set('trust proxy', 1);

// Middleware - Security Headers
app.use(helmet());

// Middleware - Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Middleware - Data sanitization
app.use(mongoSanitize()); // Prevents NoSQL injection

// Middleware - Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Strict limit for sensitive endpoints
  skipSuccessfulRequests: true, // Only count failed requests
});

app.use(limiter);

// Middleware - Request logging (security audit trail)
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

/**
 * Health check endpoint
 * No authentication required, minimal data exposure
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error.message);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

/**
 * Get users endpoint with query parameter validation
 * Query params: limit (1-100), sortBy (name|id)
 */
app.get('/users', strictLimiter, (req, res) => {
  try {
    // Input validation
    const { limit = '10', sortBy = 'id' } = req.query;

    // Validate limit parameter
    if (!validator.isInt(limit, { min: 1, max: 100 })) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid limit parameter. Must be an integer between 1 and 100.'
      });
    }

    // Validate sortBy parameter (whitelist approach)
    const allowedSortFields = ['id', 'name'];
    if (!allowedSortFields.includes(sortBy)) {
      return res.status(400).json({
        status: 'error',
        message: `Invalid sortBy parameter. Allowed values: ${allowedSortFields.join(', ')}`
      });
    }

    // Mock data - in production, this would come from a database
    let users = [
      { id: 1, name: 'Alice' }, // Removed email to reduce data exposure
      { id: 2, name: 'Bob' },
    ];

    // Sort users
    users.sort((a, b) => {
      if (sortBy === 'name') {
        return a.name.localeCompare(b.name);
      }
      return a.id - b.id;
    });

    // Limit results
    users = users.slice(0, parseInt(limit, 10));

    res.json({
      status: 'success',
      data: users,
      count: users.length
    });
  } catch (error) {
    console.error('Users endpoint error:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error'
    });
  }
});

// 404 Handler - for undefined routes
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found'
  });
});

// Global Error Handler - should be last
app.use((err, req, res, next) => {
  console.error('Global error handler:', {
    message: err.message,
    status: err.status || 500,
    path: req.path,
    method: req.method
  });

  const statusCode = err.status || 500;
  const message = statusCode === 500 ? 'Internal server error' : err.message;

  res.status(statusCode).json({
    status: 'error',
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Server startup with error handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

module.exports = app;

# Security Review: app.js - Recommendations & Best Practices

## Executive Summary
The current `app.js` implementation lacks critical security controls including error handling, input validation, security headers, and rate limiting. The recommendations below address OWASP Top 10 vulnerabilities.

---

## 🔴 Critical Issues Found

### 1. **No Error Handling**
**Risk**: Application crashes could expose sensitive information or cause DoS

**Current State**:
- No global error handler
- No try-catch blocks
- No 404 handler

**Recommendations**:
```javascript
// ✅ Add global error handler
app.use((err, req, res, next) => {
  const statusCode = err.status || 500;
  const message = statusCode === 500 ? 'Internal server error' : err.message;

  res.status(statusCode).json({ status: 'error', message });
});

// ✅ Add 404 handler
app.use((req, res) => {
  res.status(404).json({ status: 'error', message: 'Route not found' });
});

// ✅ Wrap endpoints in try-catch
app.get('/endpoint', (req, res) => {
  try {
    // logic
  } catch (error) {
    console.error('Error:', error.message);
    res.status(500).json({ status: 'error', message: 'Internal error' });
  }
});
```

---

### 2. **No Input Validation**
**Risk**: Injection attacks, XSS, parameter pollution (OWASP A03:2021)

**Current State**:
- Query parameters not validated
- No parameter type checking
- No whitelisting

**Recommendations**:
```javascript
// ✅ Use validator library
const validator = require('validator');

app.get('/users', (req, res) => {
  const { limit = '10', sortBy = 'id' } = req.query;

  // Validate limit
  if (!validator.isInt(limit, { min: 1, max: 100 })) {
    return res.status(400).json({ 
      status: 'error', 
      message: 'Invalid limit parameter' 
    });
  }

  // Whitelist allowed fields
  const allowedSortFields = ['id', 'name'];
  if (!allowedSortFields.includes(sortBy)) {
    return res.status(400).json({ 
      status: 'error', 
      message: 'Invalid sortBy parameter' 
    });
  }
});
```

---

### 3. **No Security Headers**
**Risk**: XSS, Clickjacking, MIME type sniffing (OWASP A04:2021)

**Current State**:
- Missing Content Security Policy (CSP)
- Missing X-Frame-Options
- Missing Strict-Transport-Security

**Recommendations**:
```javascript
// ✅ Use Helmet.js for security headers
const helmet = require('helmet');
app.use(helmet());

// Helmet includes:
// - Content-Security-Policy
// - X-Frame-Options: DENY
// - X-Content-Type-Options: nosniff
// - Strict-Transport-Security (HSTS)
// - X-XSS-Protection
```

---

### 4. **No Rate Limiting**
**Risk**: Brute force attacks, DoS (OWASP A06:2021)

**Current State**:
- No protection against abuse
- No request throttling

**Recommendations**:
```javascript
// ✅ Implement rate limiting
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // requests per window
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter for sensitive endpoints
  skipSuccessfulRequests: true,
});

app.use(limiter); // Global limiter
app.get('/users', strictLimiter, handler); // Endpoint-specific
```

---

### 5. **Data Exposure**
**Risk**: Sensitive data disclosure (OWASP A01:2021)

**Current State**:
```javascript
{ id: 1, name: 'Alice', email: 'alice@example.com' }
```
Email addresses exposed unnecessarily.

**Recommendations**:
```javascript
// ✅ Minimize data exposure
{ id: 1, name: 'Alice' } // Only necessary fields

// ✅ Add authentication/authorization for sensitive endpoints
app.get('/users/:id/email', authenticateUser, (req, res) => {
  // Only authenticated users can access sensitive data
});
```

---

### 6. **No NoSQL Injection Protection**
**Risk**: Database injection attacks (OWASP A03:2021)

**Current State**:
- No input sanitization
- Vulnerable if connected to MongoDB

**Recommendations**:
```javascript
// ✅ Use express-mongo-sanitize
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize()); // Removes $ and . from input
```

---

## 🟡 Important Issues

### 7. **Missing Request Logging**
**Recommendations**:
```javascript
// ✅ Log requests for security audit trail
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});
```

---

### 8. **No Body Size Limits**
**Risk**: Memory exhaustion, file upload attacks

**Recommendations**:
```javascript
// ✅ Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 9. **No Unhandled Rejection Handling**
**Recommendations**:
```javascript
// ✅ Handle process-level errors
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  server.close(() => process.exit(1));
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});
```

---

## 📋 Implementation Checklist

- [ ] Add `helmet` middleware for security headers
- [ ] Add `express-rate-limit` for rate limiting
- [ ] Add `express-mongo-sanitize` for NoSQL injection protection
- [ ] Add `validator` for input validation
- [ ] Implement try-catch blocks around route handlers
- [ ] Add global error handler
- [ ] Add 404 handler
- [ ] Implement request logging
- [ ] Add body size limits
- [ ] Add unhandled rejection handlers
- [ ] Remove unnecessary data exposure (emails)
