const validator = require('validator');

const app = express();

// ============== SECURITY MIDDLEWARE ==============

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Prevent parameter pollution
app.use((req, res, next) => {
  // Remove duplicate query parameters
  Object.keys(req.query).forEach(key => {
    if (Array.isArray(req.query[key])) {
      req.query[key] = req.query[key][req.query[key].length - 1];
    }
  });
  next();
});

// ============== ROUTE HANDLERS ==============

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get users with optional filtering
app.get('/users', (req, res) => {
  try {
    // Input validation
    const { role, limit = 10, offset = 0 } = req.query;

    // Validate pagination parameters
    const parsedLimit = parseInt(limit, 10);
    const parsedOffset = parseInt(offset, 10);

    if (isNaN(parsedLimit) || isNaN(parsedOffset)) {
      return res.status(400).json({
        error: 'Invalid pagination parameters. Limit and offset must be numbers.',
      });
    }

    if (parsedLimit < 1 || parsedLimit > 100) {
      return res.status(400).json({
        error: 'Limit must be between 1 and 100.',
      });
    }

    if (parsedOffset < 0) {
      return res.status(400).json({
        error: 'Offset must be a non-negative number.',
      });
    }

    // Validate role parameter if provided
    if (role && !validator.isAlpha(role)) {
      return res.status(400).json({
        error: 'Invalid role parameter. Only alphabetic characters allowed.',
      });
    }

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by role if provided
    let filteredUsers = allUsers;
    if (role) {
      filteredUsers = allUsers.filter(
        user => user.role && user.role.toLowerCase() === role.toLowerCase()
      );
    }

    // Apply pagination
    const users = filteredUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      data: users,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: filteredUsers.length,
      },
    });
  } catch (error) {
    console.error('Error in /users route:', error);
    res.status(500).json({
      error: 'Internal server error',
      // Don't expose error details in production
      ...(process.env.NODE_ENV === 'development' && {
        details: error.message,
      }),
    });
  }
});

// ============== ERROR HANDLING MIDDLEWARE ==============

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  console.error('Unhandled error:', {
    statusCode,
    message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
  });

  res.status(statusCode).json({
    error: message,
    // Only expose stack trace in development
    ...(process.env.NODE_ENV === 'development' && {
      stack: err.stack,
    }),
  });
});

// ============== SERVER STARTUP ==============

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

