// Simple application with security best practices implemented
// Enhanced error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const app = express();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================
// MIDDLEWARE - Security & Logging
// ============================================

// 1. Security Headers
app.use(helmet());

// 2. CORS Configuration (restrictive by default)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['localhost:3000'],
  methods: ['GET', 'POST', 'OPTIONS'],
  credentials: true,
  optionsSuccessStatus: 200
};
const cors = require('cors');
app.use(cors(corsOptions));

// 3. Request Logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// 4. Body Parser with Size Limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: true }));

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks in production
    return NODE_ENV === 'production' && req.path === '/health';
  }
});
app.use(limiter);

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

/**
 * Validates that a value is a positive integer
 */
function isValidPositiveInt(value) {
  const num = Number(value);
  return Number.isInteger(num) && num > 0;
}

/**
 * Sanitizes user input to prevent XSS
 */
function sanitizeInput(input) {
  if (typeof input !== 'string') return input;
  return input
    .replace(/[<>]/g, '') // Remove < >
    .trim();
}

// ============================================
// ROUTES - with Error Handling & Validation
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    handleError(res, error, 'Health check failed');
  }
});

/**
 * Get all users
 */
app.get('/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  } catch (error) {
    handleError(res, error, 'Failed to retrieve users');
  }
});

/**
 * Get user by ID with validation
 */
app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Input validation
    if (!isValidPositiveInt(id)) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: 'User ID must be a positive integer'
      });
    }

    const userId = parseInt(id, 10);
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        userId: userId
      });
    }

    res.json(user);
  } catch (error) {
    handleError(res, error, 'Failed to retrieve user');
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * Central error handling helper
 */
function handleError(res, error, message = 'An error occurred') {
  const statusCode = error.status || 500;
  const isDevelopment = NODE_ENV === 'development';

  console.error(`[${new Date().toISOString()}] ${message}:`, error);

  res.status(statusCode).json({
    error: message,
    ...(isDevelopment && { details: error.message, stack: error.stack })
  });
}

/**
 * 404 handler - must be after all routes
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

/**
 * Global error handling middleware - must be last
 */
app.use((err, req, res, next) => {
  const statusCode = err.status || err.statusCode || 500;
  const isDevelopment = NODE_ENV === 'development';

  console.error(`[${new Date().toISOString()}] Unhandled Error:`, err);

  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// ============================================
// GRACEFUL SHUTDOWN
// ============================================

process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

