// Improved Express application with security best practices
// Implements error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ========== SECURITY MIDDLEWARE ==========

// Set security HTTP headers using helmet
app.use(helmet());

// Parse JSON bodies with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Configure CORS
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGIN || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Rate limiting - adjust based on your needs
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Stricter limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many attempts, please try again later.',
});

// ========== ROUTES ==========

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    errorHandler(error, req, res);
  }
});

/**
 * Get users endpoint with optional filtering
 * GET /users?page=1&limit=10
 */
app.get(
  '/users',
  // Input validation
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('Page must be a number between 1 and 1000'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be a number between 1 and 100'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }

    try {
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;

      // Mock database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Pagination
      const startIndex = (page - 1) * limit;
      const users = allUsers.slice(startIndex, startIndex + limit);

      // Return safe data (exclude sensitive fields if needed)
      res.json({
        page,
        limit,
        total: allUsers.length,
        data: users.map((user) => ({
          id: user.id,
          name: sanitizeString(user.name),
          // Note: Email exposure should be reviewed based on business requirements
        })),
      });
    } catch (error) {
      errorHandler(error, req, res);
    }
  }
);

/**
 * Example POST endpoint with strict validation
 * POST /users
 */
app.post(
  '/users',
  strictLimiter, // Stricter rate limit for POST
  // Input validation
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ max: 100 })
    .withMessage('Name must be less than 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .normalizeEmail(),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }

    try {
      const { name, email } = req.body;

      // Mock user creation
      const newUser = {
        id: 3,
        name: sanitizeString(name),
        email: sanitizeString(email),
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (error) {
      errorHandler(error, req, res);
    }
  }
);

// ========== ERROR HANDLING ==========

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested route ${req.method} ${req.path} does not exist`,
  });
});

/**
 * Global error handler middleware
 */
app.use((err, req, res, next) => {
  errorHandler(err, req, res);
});

/**
 * Centralized error handler function
 */
function errorHandler(error, req, res) {
  const status = error.status || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  console.error(`[${new Date().toISOString()}] Error:`, {
    status,
    message: error.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't expose stack traces in production
  const response = {
    error: 'Internal Server Error',
    message: isDevelopment ? error.message : 'An error occurred processing your request',
  };

  if (isDevelopment) {
    response.stack = error.stack;
  }

  res.status(status).json(response);
}

/**
 * Utility function to sanitize strings
 */
function sanitizeString(str) {
  if (typeof str !== 'string') return '';
  return str.replace(/[<>\"'&]/g, (char) => {
    const escapeMap = {
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#x27;',
      '&': '&amp;',
    };
    return escapeMap[char];
  });
}

// ========== SERVER STARTUP ==========

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Recommendations for app.js

## Executive Summary
The current app.js has minimal security controls and is vulnerable to common attacks. This document outlines critical issues and provides an improved implementation.

---

## Critical Issues Found

### 1. **No Input Validation** ⚠️ HIGH
**Severity**: High  
**Issue**: Endpoints accept parameters without any validation
```javascript
// VULNERABLE
app.get('/users', (req, res) => {
  // No validation of req.query parameters
});
```
**Attack Vector**: Query parameter injection, NoSQL injection, DoS
**Fix**: Use `express-validator` to validate and sanitize all inputs
```javascript
query('page')
  .optional()
  .isInt({ min: 1, max: 1000 })
  .withMessage('Page must be a number between 1 and 1000')
```

---

### 2. **No Error Handling** ⚠️ HIGH
**Severity**: High  
**Issue**: No try-catch blocks or error middleware
```javascript
// VULNERABLE - Any error crashes the server
app.get('/users', (req, res) => {
  res.json([...]); // No error handling
});
```
**Attack Vector**: Unhandled exceptions, stack trace leaks, information disclosure
**Fix**: Implement global error handler middleware
```javascript
app.use((err, req, res, next) => {
  // Sanitize error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error'
  });
});
```

---

### 3. **Missing Security Headers** ⚠️ MEDIUM
**Severity**: Medium  
**Issue**: No security headers configured
**Attack Vector**: XSS, Clickjacking, MIME type sniffing
**Fix**: Use Helmet middleware
```bash
npm install helmet
```
```javascript
const helmet = require('helmet');
app.use(helmet()); // Enables: CSP, HSTS, X-Frame-Options, etc.
```

---

### 4. **No Rate Limiting** ⚠️ MEDIUM
**Severity**: Medium  
**Issue**: Endpoints can be called unlimited times
```javascript
// VULNERABLE - No protection against brute force or DoS
app.get('/users', (req, res) => { ... });
```
**Attack Vector**: DoS attacks, brute force attacks
**Fix**: Implement rate limiting
```bash
npm install express-rate-limit
```
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);
```

---

### 5. **No CORS Configuration** ⚠️ MEDIUM
**Severity**: Medium  
**Issue**: CORS headers not explicitly configured
**Attack Vector**: Uncontrolled cross-origin access
**Fix**: Configure CORS explicitly
```javascript
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGIN || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  // ... other headers
  next();
});
```

---

### 6. **Sensitive Data Exposure** ⚠️ LOW
**Severity**: Low (context-dependent)  
**Issue**: User emails exposed directly without access control
```javascript
// POTENTIALLY VULNERABLE
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' }, // Email exposed
  ]);
});
```
**Recommendation**: 
- Implement authorization checks
- Filter sensitive fields based on user role
- Consider pagination for large datasets

---

### 7. **No Payload Size Limits** ⚠️ MEDIUM
**Severity**: Medium  
**Issue**: No limits on request body size
**Attack Vector**: Memory exhaustion, DoS
**Fix**: Set payload limits
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 8. **Missing Logging & Monitoring** ⚠️ MEDIUM
**Severity**: Medium  
**Issue**: No error logging or request tracking
**Fix**: Implement structured logging
```javascript
console.error(`[${new Date().toISOString()}] Error:`, {
  status,
  message: error.message,
  path: req.path,
  ip: req.ip,
});
```

---

### 9. **No Graceful Shutdown** ⚠️ LOW
**Severity**: Low  
**Issue**: Server doesn't handle termination signals
**Fix**: Add signal handlers
```javascript
process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed gracefully');
    process.exit(0);
  });
});
```

