// Enhanced Express application with environment validation
// and comprehensive security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

// ========== ENVIRONMENT VALIDATION ==========

/**
 * Validates that all required environment variables are set
 */
function validateEnvironment() {
  const requiredEnvVars = [
    'NODE_ENV', // Can be 'development', 'test', or 'production'
    'PORT',     // Server port
  ];

  const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missingVars.join(', ')}\n` +
      `Please check your .env file or set these variables.`
    );
  }

  // Validate NODE_ENV is one of the allowed values
  const validNodeEnv = ['development', 'test', 'production'];
  if (!validNodeEnv.includes(process.env.NODE_ENV)) {
    throw new Error(
      `Invalid NODE_ENV: "${process.env.NODE_ENV}". ` +
      `Must be one of: ${validNodeEnv.join(', ')}`
    );
  }

  // Validate PORT is a valid number
  const port = parseInt(process.env.PORT, 10);
  if (isNaN(port) || port < 1 || port > 65535) {
    throw new Error(
      `Invalid PORT: "${process.env.PORT}". ` +
      `Must be a number between 1 and 65535`
    );
  }

  // Warn if ALLOWED_ORIGIN not set
  if (!process.env.ALLOWED_ORIGIN && process.env.NODE_ENV === 'production') {
    console.warn('⚠️  WARNING: ALLOWED_ORIGIN not set for production environment');
  }

  console.log('✅ Environment validation passed');
}

// Validate environment at startup
try {
  validateEnvironment();
} catch (error) {
  console.error('❌ Environment validation failed:');
  console.error(error.message);
  process.exit(1);
}

// ========== CONFIGURATION ==========

const config = {
  env: process.env.NODE_ENV || 'development',
  port: parseInt(process.env.PORT, 10) || 3000,
  allowedOrigin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  isDevelopment: process.env.NODE_ENV === 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isTest: process.env.NODE_ENV === 'test',
  logLevel: process.env.LOG_LEVEL || (process.env.NODE_ENV === 'production' ? 'warn' : 'info'),
};

// ========== LOGGER UTILITY ==========

const logger = {
  error: (msg, context = {}) => {
    console.error(`[ERROR] ${new Date().toISOString()}:`, msg, context);
  },
  warn: (msg, context = {}) => {
    if (config.logLevel === 'info' || config.logLevel === 'debug') {
      console.warn(`[WARN] ${new Date().toISOString()}:`, msg, context);
    }
  },
  info: (msg, context = {}) => {
    if (config.logLevel === 'info' || config.logLevel === 'debug') {
      console.info(`[INFO] ${new Date().toISOString()}:`, msg, context);
    }
  },
  debug: (msg, context = {}) => {
    if (config.logLevel === 'debug') {
      console.debug(`[DEBUG] ${new Date().toISOString()}:`, msg, context);
    }
  },
};

// ========== EXPRESS APP INITIALIZATION ==========

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// Set security HTTP headers using helmet
app.use(helmet({
  contentSecurityPolicy: !config.isProduction ? false : {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
}));

// Parse JSON bodies with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Trust proxy headers in production
if (config.isProduction) {
  app.set('trust proxy', 1);
}

// Configure CORS
app.use((req, res, next) => {
  const allowedOrigins = config.allowedOrigin.split(',').map(origin => origin.trim());
  const requestOrigin = req.headers.origin;

  if (allowedOrigins.includes(requestOrigin) || allowedOrigins.includes('*')) {
    res.header('Access-Control-Allow-Origin', requestOrigin || config.allowedOrigin);
  }

  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.header('Access-Control-Max-Age', '3600');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }

  next();
});

// Rate limiting configuration
const rateLimitConfig = {
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000,
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req, res) => {
    // Skip rate limiting for health checks in production
    return config.isProduction && req.path === '/health';
  },
};

// Rate limiter - standard
const limiter = rateLimit(rateLimitConfig);
app.use(limiter);

// Stricter limiter for sensitive endpoints
const strictLimiter = rateLimit({
  ...rateLimitConfig,
  max: Math.floor(rateLimitConfig.max / 10), // 10x stricter
});

// Request logging middleware (only in development)
if (config.isDevelopment) {
  app.use((req, res, next) => {
    const start = Date.now();
    res.on('finish', () => {
      const duration = Date.now() - start;
      logger.debug(`${req.method} ${req.path} - ${res.statusCode} (${duration}ms)`);
    });
    next();
  });
}

// ========== ROUTES ==========

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: config.env,
    });
  } catch (error) {
    errorHandler(error, req, res);
  }
});

/**
 * Get users endpoint with optional filtering
 * GET /users?page=1&limit=10
 */
app.get(
  '/users',
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('Page must be a number between 1 and 1000'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be a number between 1 and 100'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Validation error on /users', { errors: errors.array() });
      return res.status(400).json({
        error: 'Validation failed',
        details: config.isDevelopment ? errors.array() : 'Invalid request parameters',
      });
    }

    try {
      const page = parseInt(req.query.page, 10) || 1;
      const limit = parseInt(req.query.limit, 10) || 10;

      // Mock database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Pagination
      const startIndex = (page - 1) * limit;
      const users = allUsers.slice(startIndex, startIndex + limit);

      // Return safe data
      res.json({
        page,
        limit,
        total: allUsers.length,
        data: users.map((user) => ({
          id: user.id,
          name: sanitizeString(user.name),
        })),
      });
    } catch (error) {
      errorHandler(error, req, res);
    }
  }
);

/**
 * POST /users - Create a new user
 */
app.post(
  '/users',
  strictLimiter,
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .isLength({ max: 255 })
    .withMessage('Email must be less than 255 characters')
    .normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Validation error on POST /users', { errors: errors.array() });
      return res.status(400).json({
        error: 'Validation failed',
        details: config.isDevelopment ? errors.array() : 'Invalid input',
      });
    }

    try {
      const { name, email } = req.body;

      // Mock user creation
      const newUser = {
        id: 3,
        name: sanitizeString(name),
        email: sanitizeString(email),
        createdAt: new Date().toISOString(),
      };

      logger.info('User created', { userId: newUser.id });

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (error) {
      errorHandler(error, req, res);
    }
  }
);

// ========== ERROR HANDLING ==========

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested endpoint does not exist`,
  });
});

/**
 * Global error handler middleware (must be last)
 */
app.use((err, req, res, next) => {
  errorHandler(err, req, res);
});

/**
 * Centralized error handler function
 */
function errorHandler(error, req, res) {
  const status = error.status || error.statusCode || 500;

  logger.error('Request error', {
    status,
    message: error.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });

  // In production, don't expose error details
  const response = {
    error: 'Internal Server Error',
  };

  if (status < 500) {
    // Client errors - safe to expose
    response.error = error.message || 'Bad Request';
  } else if (config.isDevelopment) {
    // Development - expose full error details
    response.message = error.message;
    response.stack = error.stack;
  } else {
    // Production - generic error message
    response.message = 'An unexpected error occurred. Please try again later.';
  }

  res.status(status).json(response);
}

/**
 * Utility function to sanitize strings (XSS prevention)
 */
function sanitizeString(str) {
  if (typeof str !== 'string') return '';

  const escapeMap = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#x27;',
    '/': '&#x2F;',
  };

  return str.replace(/[&<>"'\/]/g, (char) => escapeMap[char]);
}

// ========== SERVER STARTUP ==========

let server;

function startServer() {
  server = app.listen(config.port, () => {
    const startMessage = [
      '',
      '╔════════════════════════════════════════════════════╗',
      `║ Server running on port ${config.port}${' '.repeat(26 - config.port.toString().length)}║`,
      `║ Environment: ${config.env}${' '.repeat(39 - config.env.length)}║`,
      `║ Log Level: ${config.logLevel}${' '.repeat(38 - config.logLevel.length)}║`,
      '╚════════════════════════════════════════════════════╝',
      '',
    ].join('\n');

    logger.info(startMessage);

    if (config.isDevelopment) {
      logger.info('ℹ️  Running in development mode. Set NODE_ENV=production for production.');
    }
  });

  // Graceful shutdown
  const gracefulShutdown = (signal) => {
    logger.info(`${signal} received, shutting down gracefully...`);

    server.close(() => {
      logger.info('Server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      logger.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (error) => {
    logger.error('Uncaught Exception', {
      message: error.message,
      stack: error.stack,
    });
    process.exit(1);
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    logger.error('Unhandled Rejection', {
      reason: reason instanceof Error ? reason.message : String(reason),
      promise: String(promise),
    });
  });
}

// Start the server
if (require.main === module) {
  startServer();
}

module.exports = app;

