// Enhanced application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const cors = require('cors');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// Set security HTTP headers
app.use(helmet());

// Configure CORS - restrict to known origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'HEAD'],
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for /users endpoint
const usersLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 50,
});

// Body parser with size limit to prevent large payloads
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ===== MIDDLEWARE: Validation Error Handler =====
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ===== ROUTES =====

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
    });
  }
});

/**
 * Get users endpoint
 * Input validation: Query parameters for filtering/pagination
 */
app.get(
  '/users',
  usersLimiter,
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  handleValidationErrors,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Extract and validate query parameters
      const { id, limit = 10, offset = 0 } = req.query;

      // Filter by ID if provided
      let result = users;
      if (id) {
        result = users.filter(user => user.id === parseInt(id, 10));
        if (result.length === 0) {
          return res.status(404).json({
            error: 'User not found',
          });
        }
      }

      // Apply pagination
      const paginatedResult = result.slice(
        parseInt(offset, 10),
        parseInt(offset, 10) + parseInt(limit, 10)
      );

      res.json({
        data: paginatedResult,
        total: result.length,
        limit: parseInt(limit, 10),
        offset: parseInt(offset, 10),
      });
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({
        error: 'Internal server error',
      });
    }
  }
);

// ===== ERROR HANDLING =====

/**
 * 404 Handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
  });
});

/**
 * Global Error Handler
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    status: err.status || 500,
    path: req.path,
    method: req.method,
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message,
  });
});

// ===== SERVER START =====

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

