// Improved Express application with security best practices
// Error handling, input validation, and security headers included

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;

// ============= MIDDLEWARE SETUP =============

// Security headers
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// JSON parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Request logging (for security auditing)
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============= ROUTES =============

/**
 * Health check endpoint
 * No parameters, low security risk
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

/**
 * Users endpoint with optional filtering
 * Includes input validation and error handling
 */
app.get('/users', 
  // Input validation middleware
  query('id').optional().isInt().withMessage('ID must be an integer'),
  query('name').optional().trim().isLength({ max: 100 }).withMessage('Name must be max 100 characters'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be non-negative'),

  // Handler with validation checks
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          status: 'error',
          message: 'Validation failed',
          errors: errors.array() 
        });
      }

      // Mock database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Extract and sanitize query parameters
      const { id, name, limit = 10, offset = 0 } = req.query;

      // Filter users based on parameters
      let filteredUsers = users;

      if (id) {
        filteredUsers = filteredUsers.filter(u => u.id === parseInt(id, 10));
      }

      if (name) {
        // Case-insensitive, safe comparison
        filteredUsers = filteredUsers.filter(u => 
          u.name.toLowerCase().includes(name.toLowerCase())
        );
      }

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + parseInt(limit, 10));

      res.json({
        status: 'success',
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit: parseInt(limit, 10),
          offset: parseInt(offset, 10)
        }
      });

    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        status: 'error', 
        message: 'Internal server error' 
      });
    }
  }
);

/**
 * Create user endpoint with POST validation
 */
app.post('/users',
  // Input validation for POST data
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),

  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          status: 'error',
          message: 'Validation failed',
          errors: errors.array() 
        });
      }

      // Mock creating user
      const newUser = {
        id: 3,
        name: req.body.name,
        email: req.body.email
      };

      res.status(201).json({
        status: 'success',
        message: 'User created successfully',
        data: newUser
      });

    } catch (error) {
      console.error('Error in POST /users:', error);
      res.status(500).json({ 
        status: 'error', 
        message: 'Internal server error' 
      });
    }
  }
);

// ============= 404 HANDLER =============
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Not found'
  });
});

// ============= GLOBAL ERROR HANDLER =============
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details to client
  res.status(err.status || 500).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});

// ============= SERVER STARTUP =============
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  });
}

module.exports = app;

