# Security Review: app.js

## Current Issues & Recommendations

### 1. **Missing Error Handling**
**Issue:** No error handling middleware or try-catch blocks
- Routes don't handle potential errors
- Server doesn't gracefully handle crashes
- No error logging mechanism

**Recommendation:**
```javascript
// Add error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ 
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// Add 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

### 2. **No Input Validation**
**Issue:** Route handlers don't validate or sanitize inputs
- Query parameters are not checked
- No schema validation
- Vulnerable to injection attacks

**Recommendation:**
- Use middleware like `express-validator` or `joi`
- Validate query parameters, request bodies, and URL parameters
- Sanitize inputs before processing

---

### 3. **Missing Security Headers**
**Issue:** No CORS, HSTS, or other security headers configured
- Vulnerable to cross-site attacks
- Missing Content Security Policy (CSP)
- No rate limiting

**Recommendation:**
```javascript
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

app.use(helmet()); // Adds security headers
app.use(cors({ origin: process.env.ALLOWED_ORIGINS }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);
```

---

### 4. **No Logging or Monitoring**
**Issue:** Single console.log for startup; no request logging
- Difficult to debug issues
- No audit trail for security events
- No performance monitoring

**Recommendation:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

app.use(morgan('combined', { stream: ... }));
```

---

### 5. **Sensitive Data Exposure**
**Issue:** `/users` endpoint returns email addresses without authorization checks
- No authentication mechanism
- No authorization checks
- PII exposed to any caller

**Recommendation:**
```javascript
app.get('/users', authenticateToken, (req, res) => {
  // Only return data to authenticated users
  // Filter sensitive fields
  res.json([
    { id: 1, name: 'Alice' }, // Remove email
    { id: 2, name: 'Bob' }
  ]);
});
```

---

### 6. **No Environment Configuration**
**Issue:** Hard-coded port and no environment-based configuration
- Secrets might be exposed
- No dev/prod separation
- Not following 12-factor app principles

**Recommendation:**
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

---

### 7. **Missing Validation for Health Check**
**Issue:** `/health` endpoint doesn't validate request legitimacy
- Could be abused for reconnaissance
- No request logging

**Recommendation:**
```javascript
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});
```

---

### 8. **No Request Timeout**
**Issue:** No timeout configured for requests
- Vulnerable to slowloris attacks
- Resource exhaustion

**Recommendation:**
```javascript
const timeout = require('connect-timeout');
app.use(timeout('5s')); // 5 second timeout
```

---

## Summary of Recommendations

| Priority | Issue | Solution |
|----------|-------|----------|
| **HIGH** | No input validation | Implement express-validator/joi |
| **HIGH** | Sensitive data exposure | Add authentication & authorization |
| **HIGH** | Missing error handling | Add try-catch and error middleware |
| **MEDIUM** | No security headers | Use helmet.js |
| **MEDIUM** | No rate limiting | Implement express-rate-limit |
| **MEDIUM** | No logging | Add winston/morgan logging |
| **MEDIUM** | No environment config | Use dotenv |
| **LOW** | No request timeout | Add timeout middleware |

---

## Dependencies to Add

```json
{
  "helmet": "^7.1.0",
  "cors": "^2.8.5",
  "express-validator": "^7.0.0",
  "express-rate-limit": "^7.1.5",
  "dotenv": "^16.3.1",
  "morgan": "^1.10.0",
  "winston": "^3.11.0",
  "connect-timeout": "^1.9.2"
}
```

// Improved Express application with security best practices
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');
const timeout = require('connect-timeout');
const winston = require('winston');

// Logger setup
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Add console logging in development
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

const app = express();

// Security Middleware
app.use(helmet()); // Adds various HTTP headers for security
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false // Disable `X-RateLimit-*` headers
});
app.use(limiter);

// Request timeout
app.use(timeout('5s'));

// Logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  },
  skip: (req, res) => res.statusCode < 400
}));

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Middleware for handling validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation error', { errors: errors.array(), ip: req.ip });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    logger.error('Health check error', { error: error.message });
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users endpoint with authentication check and input validation
app.get('/users',
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  handleValidationErrors,
  (req, res, next) => {
    try {
      // Authentication check (example - implement based on your auth strategy)
      const token = req.headers.authorization?.split(' ')[1];
      if (!token) {
        logger.warn('Unauthorized access attempt to /users', { ip: req.ip });
        return res.status(401).json({ error: 'Unauthorized' });
      }

      // In production, validate the token here
      // const user = validateToken(token);

      // Pagination parameters with defaults
      const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);
      const offset = parseInt(req.query.offset, 10) || 0;

      // Mock data (remove email for security)
      const users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' }
      ];

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: users.length
        }
      });

      logger.info('Users retrieved', { offset, limit, ip: req.ip });
    } catch (error) {
      next(error);
    }
  }
);

// 404 handler
app.use((req, res) => {
  logger.warn('404 Not Found', { path: req.path, method: req.method, ip: req.ip });
  res.status(404).json({
    error: 'Not Found',
    path: req.path
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(err.status || 500).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', { promise, reason });
});

process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', { error: error.message, stack: error.stack });
  process.exit(1);
});

// Start server
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

