// Improved application with security best practices
// Focus on error handling, input validation, and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const validator = require('validator');

const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE - Setup First
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// ============================================
// 2. REQUEST PARSING & VALIDATION
// ============================================

// Limit request payload size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization - remove data query injection
app.use(mongoSanitize());

// ============================================
// 3. CUSTOM MIDDLEWARE FOR INPUT VALIDATION
// ============================================

/**
 * Validate query parameters
 * @param {Object} schema - Object with validation rules
 */
const validateQuery = (schema) => {
  return (req, res, next) => {
    try {
      for (const [key, rules] of Object.entries(schema)) {
        const value = req.query[key];

        if (rules.required && !value) {
          return res.status(400).json({
            success: false,
            message: `Missing required parameter: ${key}`,
          });
        }

        if (value) {
          // Type validation
          if (rules.type === 'number' && isNaN(value)) {
            return res.status(400).json({
              success: false,
              message: `Invalid type for ${key}: expected number`,
            });
          }

          if (rules.type === 'email' && !validator.isEmail(value)) {
            return res.status(400).json({
              success: false,
              message: `Invalid email format for ${key}`,
            });
          }

          // Length validation
          if (rules.maxLength && value.length > rules.maxLength) {
            return res.status(400).json({
              success: false,
              message: `${key} exceeds maximum length of ${rules.maxLength}`,
            });
          }

          // Pattern validation
          if (rules.pattern && !rules.pattern.test(value)) {
            return res.status(400).json({
              success: false,
              message: `Invalid format for ${key}`,
            });
          }
        }
      }
      next();
    } catch (error) {
      return res.status(400).json({
        success: false,
        message: 'Invalid request parameters',
      });
    }
  };
};

// ============================================
// 4. ROUTES WITH PROPER ERROR HANDLING
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      message: 'Health check failed',
    });
  }
});

/**
 * Get users endpoint
 * Security improvements:
 * - Input validation for optional query parameters
 * - No sensitive data exposure
 * - Proper error handling
 */
app.get(
  '/users',
  validateQuery({
    id: { type: 'number', required: false },
    limit: { type: 'number', required: false },
  }),
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Optional filtering by ID
      if (req.query.id) {
        const userId = parseInt(req.query.id, 10);
        const user = users.find((u) => u.id === userId);

        if (!user) {
          return res.status(404).json({
            success: false,
            message: `User with id ${userId} not found`,
          });
        }

        return res.json({
          success: true,
          data: user,
        });
      }

      // Optional limit parameter
      let result = users;
      if (req.query.limit) {
        const limit = Math.min(parseInt(req.query.limit, 10), users.length);
        result = users.slice(0, limit);
      }

      res.json({
        success: true,
        data: result,
      });
    } catch (error) {
      console.error('Error fetching users:', error.message);
      res.status(500).json({
        success: false,
        message: 'Failed to retrieve users',
      });
    }
  }
);

// ============================================
// 5. 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Endpoint not found',
  });
});

// ============================================
// 6. GLOBAL ERROR HANDLER MIDDLEWARE
// ============================================

/**
 * Global error handling middleware
 * Must be defined last!
 */
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Default error response
  const statusCode = err.statusCode || 500;
  const message =
    process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message;

  res.status(statusCode).json({
    success: false,
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============================================
// 7. SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

