/**
 * Security Test Suite for Improved app.js
 * Tests input validation, error handling, and security controls
 */

const request = require('supertest');
const app = require('./app_improved');

describe('Security & Input Validation Tests', () => {
  // ============================================
  // INPUT VALIDATION TESTS
  // ============================================

  describe('Input Validation', () => {
    test('Should accept valid numeric ID parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ id: 1 });

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
      expect(response.body.data).toHaveProperty('id');
    });

    test('Should reject non-numeric ID parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ id: 'invalid' });

      expect(response.status).toBe(400);
      expect(response.body.success).toBe(false);
      expect(response.body.message).toContain('Invalid type');
    });

    test('Should reject oversized query parameter', async () => {
      const largeString = 'x'.repeat(1000);
      const response = await request(app)
        .get('/users')
        .query({ search: largeString });

      expect(response.status).toBe(400);
    });

    test('Should return 404 for non-existent user ID', async () => {
      const response = await request(app)
        .get('/users')
        .query({ id: 99999 });

      expect(response.status).toBe(404);
      expect(response.body.success).toBe(false);
    });

    test('Should enforce limit parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 1 });

      expect(response.status).toBe(200);
      expect(response.body.data.length).toBeLessThanOrEqual(1);
    });
  });

  // ============================================
  // ERROR HANDLING TESTS
  // ============================================

  describe('Error Handling', () => {
    test('Should return JSON error for 404', async () => {
      const response = await request(app).get('/nonexistent');

      expect(response.status).toBe(404);
      expect(response.body).toHaveProperty('success', false);
      expect(response.body).toHaveProperty('message');
    });

    test('Should not expose stack traces in production', async () => {
      // Set environment to production
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app).get('/nonexistent');

      expect(response.body).not.toHaveProperty('stack');

      // Restore environment
      process.env.NODE_ENV = originalEnv;
    });

    test('Health check should not throw errors', async () => {
      const response = await request(app).get('/health');

      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status', 'ok');
    });
  });

  // ============================================
  // SECURITY HEADERS TESTS
  // ============================================

  describe('Security Headers', () => {
    test('Should include X-Content-Type-Options header', async () => {
      const response = await request(app).get('/health');

      expect(response.headers).toHaveProperty('x-content-type-options');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    test('Should include X-Frame-Options header', async () => {
      const response = await request(app).get('/health');

      expect(response.headers).toHaveProperty('x-frame-options');
    });

    test('Should include X-XSS-Protection header', async () => {
      const response = await request(app).get('/health');

      expect(response.headers).toHaveProperty('x-xss-protection');
    });

    test('Should include Content-Security-Policy header', async () => {
      const response = await request(app).get('/health');

      expect(response.headers).toHaveProperty('content-security-policy');
    });
  });

  // ============================================
  // REQUEST SIZE LIMIT TESTS
  // ============================================

  describe('Request Size Limits', () => {
    test('Should reject oversized JSON payload', async () => {
      // Create 15KB of data (exceeds 10KB limit)
      const largePayload = {
        data: 'x'.repeat(15 * 1024)
      };

      const response = await request(app)
        .post('/users')
        .send(largePayload);

      expect(response.status).toBe(413); // Payload Too Large
    });

    test('Should accept payload within limits', async () => {
      // Create 5KB of data (within 10KB limit)
      const payload = {
        data: 'x'.repeat(5 * 1024)
      };

      // This will fail on POST (not implemented) but shouldn't be 413
      const response = await request(app)
        .get('/health')
        .send(payload);

      expect(response.status).not.toBe(413);
    });
  });

  // ============================================
  // RATE LIMITING TESTS
  // ============================================

  describe('Rate Limiting', () => {
    test('Should include rate limit headers', async () => {
      const response = await request(app).get('/health');

      expect(response.headers).toHaveProperty('ratelimit-limit');
      expect(response.headers).toHaveProperty('ratelimit-remaining');
      expect(response.headers).toHaveProperty('ratelimit-reset');
    });

    test('Rate limit should decrease with each request', async () => {
      const response1 = await request(app).get('/health');
      const remaining1 = parseInt(response1.headers['ratelimit-remaining']);

      const response2 = await request(app).get('/health');
      const remaining2 = parseInt(response2.headers['ratelimit-remaining']);

      expect(remaining2).toBeLessThan(remaining1);
    });
  });

  // ============================================
  // DATA SANITIZATION TESTS
  // ============================================

  describe('Input Sanitization', () => {
    test('Should handle NoSQL injection attempts safely', async () => {
      const response = await request(app)
        .get('/users')
        .query({ id: '{"$ne": null}' });

      // Should either reject or handle safely
      expect(response.status).toBeOneOf([400, 404]);
    });

    test('Should not execute script injections', async () => {
      const response = await request(app)
        .get('/users')
        .query({ search: '<script>alert("xss")</script>' });

      expect(response.status).toBe(400);
      // Response should not contain unescaped script
    });
  });

  // ============================================
  // ENDPOINT TESTS
  // ============================================

  describe('Endpoints', () => {
    test('GET /health should return 200', async () => {
      const response = await request(app).get('/health');

      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status');
      expect(response.body).toHaveProperty('timestamp');
    });

    test('GET /users should return 200 with user list', async () => {
      const response = await request(app).get('/users');

      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('success', true);
      expect(Array.isArray(response.body.data)).toBe(true);
    });

    test('GET /users should return structured response', async () => {
      const response = await request(app).get('/users');

      expect(response.body).toHaveProperty('success');
      expect(response.body).toHaveProperty('data');
    });
  });

  // ============================================
  // RESPONSE FORMAT TESTS
  // ============================================

  describe('Response Format', () => {
    test('Success response should have consistent format', async () => {
      const response = await request(app).get('/users');

      expect(response.body).toHaveProperty('success', true);
      expect(response.body).toHaveProperty('data');
    });

    test('Error response should have consistent format', async () => {
      const response = await request(app).get('/nonexistent');

      expect(response.body).toHaveProperty('success', false);
      expect(response.body).toHaveProperty('message');
    });

    test('All responses should be valid JSON', async () => {
      const response = await request(app).get('/health');

      expect(response.type).toMatch(/json/);
    });
  });
});

// Helper function for toBeOneOf matcher
expect.extend({
  toBeOneOf(received, options) {
    const pass = options.includes(received);
    return {
      pass,
      message: () =>
        `expected ${received} to be one of [${options.join(', ')}]`
    };
  }
});

module.exports = { app };

