const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const logger = require('morgan');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Add security headers
app.use(helmet());

// Enable CORS with options
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// ============================================
// BODY PARSING & LOGGING
// ============================================

// Limit request size to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// HTTP request logging
app.use(logger('combined'));

// ============================================
// CUSTOM ERROR HANDLING MIDDLEWARE
// ============================================

// Custom logger for errors
const errorLogger = (err, level = 'error') => {
  console.error(`[${level.toUpperCase()}] ${new Date().toISOString()}: ${err.message}`);
  if (process.env.NODE_ENV === 'development') {
    console.error(err.stack);
  }
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    errorLogger(error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error'
    });
  }
});

/**
 * Get all users
 * GET /users
 * Optional query parameters:
 *   - limit: number (1-100, default 100)
 *   - offset: number (default 0)
 */
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const limit = validateLimit(req.query.limit);
    const offset = validateOffset(req.query.offset);

    if (limit instanceof Error || offset instanceof Error) {
      return res.status(400).json({
        status: 'error',
        message: limit instanceof Error ? limit.message : offset.message
      });
    }

    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = mockUsers.slice(offset, offset + limit);

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: mockUsers.length
      }
    });
  } catch (error) {
    errorLogger(error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error'
    });
  }
});

// ============================================
// INPUT VALIDATION FUNCTIONS
// ============================================

/**
 * Validate limit parameter
 * @param {any} limit - The limit value from query
 * @returns {number|Error} - Validated limit or Error object
 */
function validateLimit(limit) {
  const defaultLimit = 100;
  const maxLimit = 100;

  if (limit === undefined || limit === null || limit === '') {
    return defaultLimit;
  }

  const parsed = parseInt(limit, 10);

  if (isNaN(parsed)) {
    return new Error('Limit must be a valid number');
  }

  if (parsed < 1) {
    return new Error('Limit must be greater than 0');
  }

  if (parsed > maxLimit) {
    return new Error(`Limit cannot exceed ${maxLimit}`);
  }

  return parsed;
}

/**
 * Validate offset parameter
 * @param {any} offset - The offset value from query
 * @returns {number|Error} - Validated offset or Error object
 */
function validateOffset(offset) {
  const defaultOffset = 0;

  if (offset === undefined || offset === null || offset === '') {
    return defaultOffset;
  }

  const parsed = parseInt(offset, 10);

  if (isNaN(parsed)) {
    return new Error('Offset must be a valid number');
  }

  if (parsed < 0) {
    return new Error('Offset cannot be negative');
  }

  return parsed;
}

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    path: req.path,
    method: req.method
  });
});

// ============================================
// GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  errorLogger(err);

  // Determine status code
  const status = err.status || err.statusCode || 500;

  // Don't expose internal error details in production
  const message = process.env.NODE_ENV === 'development'
    ? err.message
    : 'Internal server error';

  res.status(status).json({
    status: 'error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

