// Improved application with security best practices
// Enhanced error handling, input validation, and security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use('/api/', limiter);

// ============================================
// ERROR HANDLING UTILITIES
// ============================================

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================
// INPUT VALIDATION UTILITIES
// ============================================

const validateQueryParams = (params) => {
  const errors = [];

  // Example: validate common query parameters
  if (params.limit) {
    if (!validator.isInt(params.limit, { min: 1, max: 1000 })) {
      errors.push('Limit must be an integer between 1 and 1000');
    }
  }

  if (params.offset) {
    if (!validator.isInt(params.offset, { min: 0 })) {
      errors.push('Offset must be a non-negative integer');
    }
  }

  if (params.email) {
    if (!validator.isEmail(params.email)) {
      errors.push('Invalid email format');
    }
  }

  return errors;
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint - no auth required
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

// Get users with input validation
app.get('/api/users', asyncHandler(async (req, res, next) => {
  // Validate query parameters
  const validationErrors = validateQueryParams(req.query);
  if (validationErrors.length > 0) {
    return next(new AppError(
      `Validation error: ${validationErrors.join(', ')}`,
      400
    ));
  }

  // Parse and sanitize query params
  const limit = req.query.limit ? Math.min(parseInt(req.query.limit, 10), 100) : 10;
  const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

  try {
    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.status(200).json({
      success: true,
      data: paginatedUsers,
      pagination: {
        offset,
        limit,
        total: users.length,
      },
    });
  } catch (error) {
    next(new AppError('Failed to retrieve users', 500));
  }
}));

// ============================================
// ERROR HANDLING MIDDLEWARE (must be last)
// ============================================

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    message: `Route ${req.originalUrl} not found`,
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Development error response
  if (process.env.NODE_ENV === 'development') {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message,
      error: err,
      stack: err.stack,
    });
  }
  // Production error response - don't leak details
  else {
    // Operational, trusted error: send message to client
    if (err instanceof AppError) {
      res.status(err.statusCode).json({
        status: err.status,
        message: err.message,
      });
    }
    // Programming or unknown error: don't leak details
    else {
      console.error('ERROR 💥', err);
      res.status(500).json({
        status: 'error',
        message: 'Something went wrong. Please try again later.',
      });
    }
  }
});

// Unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to log this and restart the server
});

// ============================================
// SERVER INITIALIZATION
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

