class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
    this.statusCode = 404;
  }
}

// ============================================
// INPUT VALIDATION FUNCTIONS
// ============================================

const validateQueryParams = (query) => {
  const errors = [];

  // Example: validate 'id' if provided
  if (query.id && !Number.isInteger(Number(query.id))) {
    errors.push('Invalid id: must be an integer');
  }

  // Example: validate 'limit' if provided
  if (query.limit) {
    const limit = Number(query.limit);
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      errors.push('Invalid limit: must be an integer between 1 and 100');
    }
  }

  // Example: validate 'search' if provided
  if (query.search && typeof query.search !== 'string') {
    errors.push('Invalid search: must be a string');
  }

  // Prevent XSS by escaping HTML
  if (query.search && query.search.length > 200) {
    errors.push('Search term too long: maximum 200 characters');
  }

  if (errors.length > 0) {
    throw new ValidationError(errors.join('; '));
  }

  return query;
};

