# Security Best Practices - Code Examples

## 1. INPUT VALIDATION PATTERNS

### ✅ Good: Type and Range Validation
```javascript
app.get('/items/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    // Validate type
    if (!Number.isInteger(id)) {
      throw new ValidationError('ID must be an integer');
    }

    // Validate range
    if (id < 1 || id > 999999) {
      throw new ValidationError('ID must be between 1 and 999999');
    }

    // Fetch item with validated ID
    const item = getItem(id);
    res.json(item);
  } catch (error) {
    next(error);
  }
});
```

### ❌ Bad: No Validation
```javascript
app.get('/items/:id', (req, res) => {
  // id can be anything - vulnerable!
  const item = getItem(req.params.id);
  res.json(item);
});
```

---

## 2. QUERY PARAMETER VALIDATION

### ✅ Good: Whitelist & Validate
```javascript
const validateFilters = (query) => {
  const errors = [];
  const validated = {};

  // Whitelist allowed parameters
  const allowedParams = ['search', 'sort', 'limit', 'page'];

  for (const key of Object.keys(query)) {
    if (!allowedParams.includes(key)) {
      errors.push(`Unknown parameter: ${key}`);
    }
  }

  // Validate search
  if (query.search) {
    if (typeof query.search !== 'string') {
      errors.push('search must be a string');
    }
    if (query.search.length > 100) {
      errors.push('search too long (max 100 chars)');
    }
    validated.search = validator.escape(query.search);
  }

  // Validate sort
  if (query.sort) {
    const validSortFields = ['name', 'date', 'price'];
    if (!validSortFields.includes(query.sort)) {
      errors.push('Invalid sort field');
    }
    validated.sort = query.sort;
  }

  // Validate limit
  if (query.limit) {
    const limit = Number(query.limit);
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      errors.push('limit must be 1-100');
    }
    validated.limit = Math.min(limit, 100);
  }

  if (errors.length > 0) {
    throw new ValidationError(errors.join('; '));
  }

  return validated;
};
```

### ❌ Bad: No Validation
```javascript
app.get('/items', (req, res) => {
  // All query params used directly - vulnerability!
  const items = database.query(`SELECT * FROM items WHERE ${req.query.where}`);
  res.json(items);
});
```

---

## 3. ERROR HANDLING

### ✅ Good: Safe Error Response
```javascript
app.use((error, req, res, next) => {
  console.error(`[ERROR] ${error.name}: ${error.message}`);

  // Determine status
  const statusCode = error.statusCode || 500;

  // Safe message (no details in production)
  let message = 'Internal server error';
  if (error.name === 'ValidationError') {
    message = error.message;
  }

  // Send response
  res.status(statusCode).json({
    success: false,
    error: message,
    timestamp: new Date().toISOString(),
  });
});
```

### ❌ Bad: Exposing Sensitive Info
```javascript
app.use((error, req, res, next) => {
  // Exposes stack trace to attackers!
  res.status(500).json({
    error: error.message,
    stack: error.stack,
    details: error,
  });
});
```

---

## 4. XSS PREVENTION

### ✅ Good: Escaping HTML
```javascript
const validator = require('validator');

app.post('/comments', (req, res, next) => {
  try {
    // Escape HTML to prevent XSS
    const comment = validator.escape(req.body.comment);
    const sanitized = validator.trim(comment);

    // Validate length
    if (sanitized.length === 0 || sanitized.length > 5000) {
      throw new ValidationError('Comment must be 1-5000 characters');
    }

    // Store safely
    saveComment(sanitized);
    res.json({ success: true });
  } catch (error) {
    next(error);
  }
});
```

### ❌ Bad: Direct HTML Insertion
```javascript
app.post('/comments', (req, res) => {
  // XSS vulnerability - user input stored directly!
  saveComment(req.body.comment);
  res.json({ success: true });
});
```

---

## 5. SQL INJECTION PREVENTION

### ✅ Good: Parameterized Queries
```javascript
const pool = require('./database');

app.get('/users/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id)) {
      throw new ValidationError('Invalid ID');
    }

    // Use parameterized query
    pool.query(
      'SELECT id, name, email FROM users WHERE id = $1',
      [id], // Parameters passed separately
      (error, results) => {
        if (error) throw error;
        res.json(results.rows[0]);
      }
    );
  } catch (error) {
    next(error);
  }
});
```

### ❌ Bad: String Concatenation
```javascript
app.get('/users/:id', (req, res) => {
  // SQL Injection vulnerability!
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  database.query(query, (err, result) => {
    res.json(result);
  });
});
```

---

## 6. AUTHENTICATION

### ✅ Good: JWT Validation
```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (error, user) => {
    if (error) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

app.get('/protected', authenticateToken, (req, res) => {
  res.json({ user: req.user });
});
```

### ❌ Bad: No Authentication
```javascript
app.get('/protected', (req, res) => {
  // No authentication - anyone can access!
  res.json({ secretData: 'exposed' });
});
```

---

## 7. RATE LIMITING

### ✅ Good: Per-User Rate Limiting
```javascript
const redis = require('redis');
const client = redis.createClient();

const rateLimitByUser = async (req, res, next) => {
  const userId = req.user?.id || req.ip;
  const key = `rate:${userId}`;
  const limit = 100;
  const window = 3600; // 1 hour

  const count = await client.incr(key);

  if (count === 1) {
    await client.expire(key, window);
  }

  res.set('X-RateLimit-Limit', limit);
  res.set('X-RateLimit-Remaining', Math.max(0, limit - count));

  if (count > limit) {
    return res.status(429).json({
      error: 'Too many requests',
      retryAfter: window,
    });
  }

  next();
};

app.get('/api/data', rateLimitByUser, (req, res) => {
  res.json({ data: 'protected' });
});
```

### ❌ Bad: No Rate Limiting
```javascript
app.post('/login', (req, res) => {
  // No rate limiting - brute force attack possible!
  const user = authenticate(req.body.email, req.body.password);
  res.json({ token: user.token });
});
```

---

## 8. SECURE PASSWORD HANDLING

### ✅ Good: Bcrypt Hashing
```javascript
const bcrypt = require('bcrypt');

app.post('/register', async (req, res, next) => {
  try {
    // Validate input
    if (!validator.isEmail(req.body.email)) {
      throw new ValidationError('Invalid email');
    }

    if (req.body.password.length < 12) {
      throw new ValidationError('Password must be 12+ characters');
    }

    // Hash password
    const hashedPassword = await bcrypt.hash(req.body.password, 10);

    // Store hashed password only
    await createUser(req.body.email, hashedPassword);

    res.json({ success: true });
  } catch (error) {
    next(error);
  }
});

// Login
app.post('/login', async (req, res, next) => {
  try {
    const user = await getUser(req.body.email);
    if (!user) {
      throw new Error('Invalid credentials');
    }

    // Compare password
    const match = await bcrypt.compare(req.body.password, user.passwordHash);
    if (!match) {
      throw new Error('Invalid credentials');
    }

    const token = jwt.sign({ id: user.id }, process.env.JWT_SECRET);
    res.json({ token });
  } catch (error) {
    next(error);
  }
});
```

### ❌ Bad: Plain Text Passwords
```javascript
app.post('/register', (req, res) => {
  // Storing plain text password - huge security risk!
  saveUser(req.body.email, req.body.password);
  res.json({ success: true });
});
```

---

## 9. CORS CONFIGURATION

### ✅ Good: Whitelist Approach
```javascript
const cors = require('cors');

const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = [
      'https://example.com',
      'https://app.example.com',
    ];

    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};

app.use(cors(corsOptions));
```

### ❌ Bad: Allow All
```javascript
app.use(cors()); // Allows ANY origin - vulnerability!
```

---

## 10. LOGGING WITHOUT SENSITIVE DATA

### ✅ Good: Safe Logging
```javascript
const logger = (req, res, next) => {
  res.on('finish', () => {
    // Log safely
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      ip: req.ip,
      userId: req.user?.id, // OK - just ID
      duration: res.get('X-Response-Time'),
      // DON'T log passwords, tokens, emails, etc.
    });
  });
  next();
};
```

### ❌ Bad: Logging Everything
```javascript
console.log({
  request: req,           // Logs all headers including tokens!
  body: req.body,         // Logs passwords!
  password: req.body.password, // NEVER!
  token: req.headers.authorization, // NEVER!
});
```

