// Improved application with error handling and security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS attacks
app.use(xss());

// Prevent parameter pollution
app.use(hpp());

// CORS configuration
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.header('Access-Control-Max-Age', '86400');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Request logging middleware
const requestLogger = (req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
};
app.use(requestLogger);

// ============================================
// INPUT VALIDATION UTILITY
// ============================================

const validateQueryParams = (schema) => {
  return (req, res, next) => {
    try {
      // Validate query parameters
      const errors = [];

      for (const [key, rules] of Object.entries(schema)) {
        const value = req.query[key];

        if (rules.required && !value) {
          errors.push(`${key} is required`);
          continue;
        }

        if (value && rules.type === 'number') {
          if (isNaN(value)) {
            errors.push(`${key} must be a number`);
          }
        }

        if (value && rules.maxLength && value.length > rules.maxLength) {
          errors.push(`${key} must not exceed ${rules.maxLength} characters`);
        }

        if (value && rules.pattern && !rules.pattern.test(value)) {
          errors.push(`${key} has invalid format`);
        }
      }

      if (errors.length > 0) {
        return res.status(400).json({
          status: 'fail',
          message: 'Invalid input',
          errors,
        });
      }

      next();
    } catch (error) {
      return res.status(400).json({
        status: 'error',
        message: 'Validation error',
      });
    }
  };
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development',
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

// Users endpoint with validation and authentication
app.get(
  '/api/users',
  validateQueryParams({
    limit: { type: 'number', maxLength: 3 },
    offset: { type: 'number', maxLength: 5 },
  }),
  (req, res) => {
    try {
      // Authorization check (example)
      const authHeader = req.headers.authorization;
      if (!authHeader) {
        return res.status(401).json({
          status: 'fail',
          message: 'Unauthorized - Authorization header required',
        });
      }

      // Parse and validate pagination parameters
      const limit = Math.min(parseInt(req.query.limit) || 10, 100); // Cap at 100
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      // Mock user data - in production, fetch from database
      const mockUsers = [
        { id: 1, name: 'Alice', role: 'admin' },
        { id: 2, name: 'Bob', role: 'user' },
      ];

      // Apply pagination
      const paginatedUsers = mockUsers.slice(offset, offset + limit);

      res.status(200).json({
        status: 'success',
        data: {
          users: paginatedUsers,
          pagination: {
            limit,
            offset,
            total: mockUsers.length,
          },
        },
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        status: 'error',
        message: 'Failed to fetch users',
      });
    }
  }
);

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'fail',
    message: `Cannot find ${req.originalUrl} on this server`,
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  error.statusCode = error.statusCode || 500;
  error.status = error.status || 'error';

  // Log error (in production, use proper logging service)
  console.error('Global error handler:', {
    message: error.message,
    status: error.statusCode,
    path: req.path,
  });

  // Send error response
  res.status(error.statusCode).json({
    status: error.status,
    message: error.message,
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (error) => {
  console.error('Unhandled Rejection:', error);
  // Close server gracefully
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

module.exports = app;

