// Improved application with security best practices
// Error handling, input validation, and secure defaults

const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ============================================
// REQUEST LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============================================
// INPUT VALIDATION UTILITIES
// ============================================

const validatePageNumber = (page) => {
  if (!page) return 1; // Default to page 1
  const parsed = parseInt(page, 10);
  if (isNaN(parsed) || parsed < 1) {
    throw new Error('Page must be a positive integer');
  }
  return parsed;
};

const validateLimit = (limit) => {
  if (!limit) return 10; // Default limit
  const parsed = parseInt(limit, 10);
  if (isNaN(parsed) || parsed < 1 || parsed > 100) {
    throw new Error('Limit must be between 1 and 100');
  }
  return parsed;
};

const validateEmail = (email) => {
  if (!validator.isEmail(email)) {
    throw new Error('Invalid email format');
  }
  return email;
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res, next) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users with pagination
 * GET /users?page=1&limit=10
 */
app.get('/users', (req, res, next) => {
  try {
    // Validate input
    const page = validatePageNumber(req.query.page);
    const limit = validateLimit(req.query.limit);

    // Mock data - In production, this would query a database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Implement pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = allUsers.slice(startIndex, endIndex);

    // Return paginated response
    res.status(200).json({
      success: true,
      page,
      limit,
      total: allUsers.length,
      data: paginatedUsers,
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get user by ID
 * GET /users/:id
 */
app.get('/users/:id', (req, res, next) => {
  try {
    // Validate ID is a number
    const id = parseInt(req.params.id, 10);
    if (isNaN(id) || id < 1) {
      return res.status(400).json({
        success: false,
        error: 'Invalid user ID format',
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find((u) => u.id === id);
    if (!user) {
      return res.status(404).json({
        success: false,
        error: 'User not found',
      });
    }

    res.status(200).json({
      success: true,
      data: user,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
  });
});

// Global error handler (MUST be last)
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${err.message}`, err.stack);

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const response = {
    success: false,
    error: err.message || 'Internal server error',
  };

  if (isDevelopment) {
    response.stack = err.stack;
  }

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json(response);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION:', err);
  // Close server gracefully
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION:', err);
  process.exit(1);
});

module.exports = app;

# Security Review: app.js - Detailed Recommendations

## Executive Summary
The current app.js is a basic Express application with significant security gaps. This document outlines critical issues and provides implementation guidelines.

---

## 🔴 CRITICAL ISSUES

### 1. No Error Handling
**Risk Level:** HIGH
**Issue:** Unhandled errors will crash the server, causing denial of service.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Improvement:**
```javascript
app.get('/users', (req, res, next) => {
  try {
    // ... code ...
    res.status(200).json({...});
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});
```

### 2. No Input Validation
**Risk Level:** HIGH
**Issue:** Any query parameters accepted without validation - opens door to injection attacks.

**Vulnerable Code:**
```javascript
app.get('/users', (req, res) => {
  // req.query.filter or req.query.sort could be malicious
});
```

**Fix:** Validate all inputs
```javascript
const validatePageNumber = (page) => {
  const parsed = parseInt(page, 10);
  if (isNaN(parsed) || parsed < 1) {
    throw new Error('Invalid page number');
  }
  return parsed;
};

app.get('/users', (req, res, next) => {
  try {
    const page = validatePageNumber(req.query.page);
    // Use validated input safely
  } catch (error) {
    next(error);
  }
});
```

### 3. Missing Security Headers
**Risk Level:** MEDIUM
**Issue:** No CORS protection, no CSP, vulnerable to clickjacking.

**Solution:** Use `helmet.js`
```javascript
const helmet = require('helmet');
app.use(helmet());
```

This provides:
- X-Frame-Options (clickjacking protection)
- X-Content-Type-Options (MIME sniffing prevention)
- X-XSS-Protection (XSS filters)
- Content-Security-Policy (CSP)
- Strict-Transport-Security (HSTS)

### 4. No Rate Limiting
**Risk Level:** MEDIUM
**Issue:** Vulnerable to brute force and DoS attacks.

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
});

app.use(limiter);
```

### 5. No Request Size Limits
**Risk Level:** MEDIUM
**Issue:** Attacker could send massive payloads causing memory exhaustion.

**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

### 6. No SQL/NoSQL Injection Prevention
**Risk Level:** MEDIUM
**Issue:** Data from user input should be sanitized.

**Solution:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize()); // Prevents $ and . in object keys
```

### 7. Exposing Sensitive Data
**Risk Level:** MEDIUM
**Issue:** Email addresses returned without authorization check.

**Improvements:**
- Implement authentication/authorization
- Only return authorized user data
- Use field masking for sensitive data
- Implement proper access control

---

## 🟡 IMPORTANT IMPROVEMENTS

### 8. No Request Logging
**Issue:** Cannot audit or track security events.

**Solution:**
```javascript
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Consider using Morgan or Winston for production
const morgan = require('morgan');
app.use(morgan('combined'));
```

### 9. No Unhandled Rejection Handling
**Issue:** Async errors crash the process.

**Solution:**
```javascript
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  server.close(() => process.exit(1));
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});
```

### 10. Hardcoded Port
**Issue:** No environment flexibility.

**Solution:**
```javascript
const PORT = process.env.PORT || 3000;
```

