    test('Should handle 404 errors gracefully', async () => {
      const response = await request(app)
        .get('/nonexistent-endpoint');

      expect(response.status).toBe(404);
      expect(response.body).toEqual({
        success: false,
        error: 'Endpoint not found'
      });
    });

    test('Should not expose stack traces in production', async () => {
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/users')
        .query({ page: 'invalid' });

      expect(response.status).toBe(400);
      expect(response.body.stack).toBeUndefined();

      process.env.NODE_ENV = 'test';
    });

    test('Should handle server errors gracefully', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 999999 });

      expect(response.status).toBe(400);
      expect(response.body.success).toBe(false);
      expect(response.body.error).toBeDefined();
    });
  });

  // ============================================
  // INPUT VALIDATION TESTS
  // ============================================

  describe('Input Validation - /users endpoint', () => {

    test('Should accept valid pagination parameters', async () => {
      const response = await request(app)
        .get('/users')
        .query({ page: 1, limit: 10 });

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
      expect(response.body.page).toBe(1);
      expect(response.body.limit).toBe(10);
    });

    test('Should reject negative page numbers', async () => {
      const response = await request(app)
        .get('/users')
        .query({ page: -1 });

      expect(response.status).toBe(400);
      expect(response.body.success).toBe(false);
    });

    test('Should reject non-numeric page parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ page: 'invalid' });

      expect(response.status).toBe(400);
      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('positive integer');
    });

    test('Should reject limit > 100', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 101 });

      expect(response.status).toBe(400);
      expect(response.body.success).toBe(false);
    });

    test('Should reject zero limit', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 0 });

      expect(response.status).toBe(400);
      expect(response.body.success).toBe(false);
    });

    test('Should use default pagination when not provided', async () => {
      const response = await request(app)
        .get('/users');

      expect(response.status).toBe(200);
      expect(response.body.page).toBe(1);
      expect(response.body.limit).toBe(10);
    });

    test('Should reject SQL injection attempts in parameters', async () => {
      const response = await request(app)
        .get('/users')
        .query({ page: "1; DROP TABLE users;" });

      expect(response.status).toBe(400);
    });

    test('Should handle special characters in parameters', async () => {
      const response = await request(app)
        .get('/users')
        .query({ page: "1' OR '1'='1" });

      expect(response.status).toBe(400);
    });
  });

  // ============================================
  // INPUT VALIDATION TESTS - /users/:id endpoint
  // ============================================

  describe('Input Validation - /users/:id endpoint', () => {

    test('Should accept valid numeric ID', async () => {
      const response = await request(app)
        .get('/users/1');

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
      expect(response.body.data.id).toBe(1);
    });

    test('Should reject non-numeric ID', async () => {
      const response = await request(app)
        .get('/users/abc');

      expect(response.status).toBe(400);
      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('Invalid');
    });

    test('Should reject negative ID', async () => {
      const response = await request(app)
        .get('/users/-1');

      expect(response.status).toBe(400);
      expect(response.body.success).toBe(false);
    });

    test('Should return 404 for non-existent ID', async () => {
      const response = await request(app)
        .get('/users/9999');

      expect(response.status).toBe(404);
      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('not found');
    });

    test('Should reject SQL injection in ID', async () => {
      const response = await request(app)
        .get('/users/1; DROP TABLE users;');

      expect(response.status).toBe(400);
    });
  });

  // ============================================
  // RATE LIMITING TESTS
  // ============================================

  describe('Rate Limiting', () => {

    test('Should include rate limit headers', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['ratelimit-limit']).toBeDefined();
      expect(response.headers['ratelimit-remaining']).toBeDefined();
      expect(response.headers['ratelimit-reset']).toBeDefined();
    });

    test('Should allow requests within rate limit', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.status).toBe(200);
      expect(response.headers['ratelimit-remaining']).toBeDefined();
      const remaining = parseInt(response.headers['ratelimit-remaining']);
      expect(remaining).toBeGreaterThan(0);
    });
  });

  // ============================================
  // SECURITY HEADERS TESTS
  // ============================================

  describe('Security Headers', () => {

    test('Should include X-Content-Type-Options header', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    test('Should include X-Frame-Options header', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['x-frame-options']).toBeDefined();
    });

    test('Should include X-XSS-Protection header', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['x-xss-protection']).toBeDefined();
    });

    test('Should include Content-Security-Policy header', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['content-security-policy']).toBeDefined();
    });
  });

  // ============================================
  // REQUEST SIZE LIMIT TESTS
  // ============================================

  describe('Request Size Limits', () => {

    test('Should reject oversized JSON payloads', async () => {
      const largePayload = {
        data: 'x'.repeat(11000) // 11KB, exceeds 10KB limit
      };

      const response = await request(app)
        .post('/some-endpoint')
        .send(largePayload);

      expect(response.status).toBe(413); // Payload Too Large
    });

    test('Should accept payloads within size limit', async () => {
      const validPayload = {
        data: 'x'.repeat(5000) // 5KB, within limit
      };

      const response = await request(app)
        .post('/health')
        .send(validPayload);

      // Will be 405 (method not allowed) because /health doesn't accept POST,
      // but size validation should pass first
      expect(response.status).not.toBe(413);
    });
  });

  // ============================================
  // RESPONSE FORMAT TESTS
  // ============================================

  describe('Response Format', () => {

    test('Should return consistent error response format', async () => {
      const response = await request(app)
        .get('/users/invalid');

      expect(response.body).toHaveProperty('success');
      expect(response.body).toHaveProperty('error');
      expect(response.body.success).toBe(false);
    });

    test('Should return consistent success response format', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.body).toHaveProperty('status');
      expect(response.body).toHaveProperty('timestamp');
    });
  });

  // ============================================
  // INJECTION ATTACK TESTS
  // ============================================

  describe('Injection Attack Prevention', () => {

    test('Should sanitize MongoDB injection attempts', async () => {
      const response = await request(app)
        .get('/users')
        .query({ page: { $gt: 0 } });

      // Should either validate or reject, not crash
      expect([200, 400]).toContain(response.status);
    });

    test('Should handle NoSQL injection in query params', async () => {
      const response = await request(app)
        .get('/users')
        .query({ 'page[$ne]': '' });

      // Should sanitize the key, not process NoSQL operators
      expect([200, 400]).toContain(response.status);
    });
  });

  // ============================================
  // HEALTH CHECK ENDPOINT TESTS
  // ============================================

  describe('/health endpoint', () => {

    test('Should return 200 OK', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.status).toBe(200);
    });

    test('Should return valid timestamp', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.body.timestamp).toBeDefined();
      const timestamp = new Date(response.body.timestamp);
      expect(timestamp).toBeInstanceOf(Date);
      expect(timestamp.getTime()).not.toBeNaN();
    });

    test('Should return status ok', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.body.status).toBe('ok');
    });
  });
});

# Migration Guide: From Basic app.js to Secure app.js

## Overview
This guide walks you through migrating your application from the basic version to a security-hardened version.

---

## Step 1: Install Required Dependencies

```bash
# Install new security packages
npm install helmet express-rate-limit express-mongo-sanitize validator morgan dotenv

# Install dev dependencies
npm install --save-dev nodemon jest supertest eslint eslint-config-airbnb-base eslint-plugin-import
```

**What each package does:**
- `helmet`: Adds 15+ security headers to responses
- `express-rate-limit`: Prevents brute force/DoS attacks
- `express-mongo-sanitize`: Prevents NoSQL injection
- `validator`: Validates and sanitizes strings
- `morgan`: HTTP request logging
- `dotenv`: Load environment variables from .env file

---

## Step 2: Create Environment Configuration

Create a `.env` file in your project root:

```env
# .env
NODE_ENV=development
PORT=3000
LOG_LEVEL=info
```

Create a `.env.production` file for production:

```env
# .env.production
NODE_ENV=production
PORT=3000
LOG_LEVEL=warn
```

Add to `.gitignore`:
```
.env
.env.local
.env.*.local
node_modules/
```

---

## Step 3: Update app.js

### Option A: Replace Entire File
Replace your current `app.js` with the improved version provided in `app.js.improved`.

```bash
cp app.js app.js.backup  # Backup original
cp app.js.improved app.js
```

### Option B: Incremental Migration
If you have other logic in app.js, integrate these changes incrementally:

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');

const app = express();

// 1. Add security middleware FIRST
app.use(helmet());
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
}));

// 2. Add body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Add sanitization
app.use(mongoSanitize());

// 4. Add logging
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// 5. Update your routes with error handling
app.get('/users', (req, res, next) => {
  try {
    // Validate input
    const page = parseInt(req.query.page || 1, 10);
    if (isNaN(page) || page < 1) {
      return res.status(400).json({ 
        success: false, 
        error: 'Invalid page number' 
      });
    }

    // Your logic here
    res.status(200).json({
      success: true,
      data: [...]
    });
  } catch (error) {
    next(error);
  }
});

// 6. Add error handlers LAST
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found'
  });
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.statusCode || 500).json({
    success: false,
    error: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'Internal server error'
  });
});

// 7. Add process error handlers
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  server.close(() => process.exit(1));
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

module.exports = app;
```

---

## Step 4: Add Input Validation Utilities

Create a new file `validation.js`:

```javascript
// validation.js
const validator = require('validator');

const validatePageNumber = (page) => {
  if (!page) return 1;
  const parsed = parseInt(page, 10);
  if (isNaN(parsed) || parsed < 1) {
    throw new Error('Page must be a positive integer');
  }
  return parsed;
};

const validateLimit = (limit) => {
  if (!limit) return 10;
  const parsed = parseInt(limit, 10);
  if (isNaN(parsed) || parsed < 1 || parsed > 100) {
    throw new Error('Limit must be between 1 and 100');
  }
  return parsed;
};

const validateEmail = (email) => {
  if (!validator.isEmail(email)) {
    throw new Error('Invalid email format');
  }
  return email;
};

const validateId = (id) => {
  const parsed = parseInt(id, 10);
  if (isNaN(parsed) || parsed < 1) {
    throw new Error('Invalid ID format');
  }
  return parsed;
};

module.exports = {
  validatePageNumber,
  validateLimit,
  validateEmail,
  validateId
};
```

Then use in app.js:

```javascript
const { validatePageNumber, validateLimit } = require('./validation');

app.get('/users', (req, res, next) => {
  try {
    const page = validatePageNumber(req.query.page);
    const limit = validateLimit(req.query.limit);
    // ... rest of code
  } catch (error) {
    next(error);
  }
});
```

---

## Step 5: Update package.json Scripts

```json
{
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest --coverage",
    "test:watch": "jest --watch",
    "lint": "eslint .",
    "security-check": "npm audit && npm run lint"
  }
}
```

---

## Step 6: Add Tests

Create `app.test.js` (provided in the separate test file).

Run tests:
```bash
npm test
```

---

## Step 7: Create ESLint Configuration

Create `.eslintrc.js`:

```javascript
module.exports = {
  env: {
    node: true,
    es2021: true,
    jest: true,
  },
  extends: ['airbnb-base'],
  parserOptions: {
    ecmaVersion: 'latest',
    sourceType: 'module',
  },
  rules: {
    'no-console': 'warn',
    'consistent-return': 'warn',
  },
};
```

---

## Step 8: Testing the Migration

### Run Locally

```bash
# Start the application
npm run dev

# In another terminal, test endpoints
curl http://localhost:3000/health
curl "http://localhost:3000/users?page=1&limit=10"

# Test with invalid input
curl "http://localhost:3000/users?page=-1"
curl "http://localhost:3000/users?page=invalid"
```

### Run Test Suite

```bash
npm test
```

Expected output:
```
PASS  app.test.js
  ✓ All tests passing
  ✓ Security headers present
  ✓ Input validation working
  ✓ Error handling comprehensive
  ✓ Rate limiting active
```

---

## Step 9: Deployment Checklist

Before deploying to production:

- [ ] Set `NODE_ENV=production`
- [ ] Update `.env.production` with production values
- [ ] Run security audit: `npm audit`
- [ ] Run tests: `npm test`
- [ ] Run linting: `npm run lint`
- [ ] Review all dependencies for vulnerabilities
- [ ] Enable HTTPS/TLS on your server
- [ ] Set up logging/monitoring
- [ ] Configure rate limiting based on expected traffic
- [ ] Review error messages (don't expose stack traces)
- [ ] Set up backup/recovery procedures

---

## Step 10: Continuous Security

### Regular Security Updates

```bash
# Check for vulnerabilities
npm audit

# Fix vulnerabilities automatically (where possible)
npm audit fix

# Update packages
npm update

# Check outdated packages
npm outdated
```

### Add to CI/CD Pipeline

Create `.github/workflows/security.yml` (for GitHub Actions):

```yaml
name: Security Checks

on: [push, pull_request]

jobs:
  security:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v2
      - uses: actions/setup-node@v2
        with:
          node-version: '18'
      - run: npm install
      - run: npm audit
      - run: npm run lint
      - run: npm test
```

---

## Breaking Changes

### What Changed for API Consumers

#### Old Response Format
```json
[
  { "id": 1, "name": "Alice", "email": "alice@example.com" },
  { "id": 2, "name": "Bob", "email": "bob@example.com" }
]
```

#### New Response Format
```json
{
  "success": true,
  "page": 1,
  "limit": 10,
  "total": 2,
  "data": [
    { "id": 1, "name": "Alice", "email": "alice@example.com" },
    { "id": 2, "name": "Bob", "email": "bob@example.com" }
  ]
}
```

**Migration for API Clients:**
- Update response parsing to use `response.data`
- Check `response.success` field
- Handle pagination with `page` and `limit` fields

#### Error Response Format (New)
```json
{
  "success": false,
  "error": "Page must be a positive integer"
}
```

---

## Rollback Plan

If issues occur:

```bash
# Restore backup
cp app.js.backup app.js

# Restart application
npm start

# Rollback dependencies
git checkout package.json package-lock.json
npm install
```

---

## Common Issues & Solutions

### Issue: Rate limit exceeded during testing
**Solution:** Adjust rate limit or use environment variable:
```javascript
const limiter = rateLimit({
  windowMs: process.env.NODE_ENV === 'test' ? 1 : 15 * 60 * 1000,
  max: process.env.NODE_ENV === 'test' ? 10000 : 100,
});
```

### Issue: Request size limit errors
**Solution:** Increase limit if needed:
```javascript
app.use(express.json({ limit: '100kb' })); // Increased from 10kb
```

### Issue: Tests failing after migration
**Solution:** Verify response format changed and update tests

### Issue: Performance degradation
**Solution:** Check rate limiting config and adjust max/windowMs

---

