// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const xss = require('xss');
const morgan = require('morgan');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Add security headers using helmet
app.use(helmet());

// 2. Request logging for audit trails
app.use(morgan('combined', {
  skip: (req) => req.path === '/health' // Skip health check logs to reduce noise
}));

// 3. Body parser with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Global rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});
app.use(limiter);

// 5. Stricter rate limiting for health checks
const healthLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 30,
});

// ===== ROUTES =====

// Health check endpoint with additional rate limiting
app.get('/health', healthLimiter, (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    handleError(error, res);
  }
});

// Users endpoint with query validation and input sanitization
app.get(
  '/users',
  // Validate query parameters
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          success: false,
          errors: errors.array().map(err => ({
            field: err.param,
            message: err.msg
          })),
        });
      }

      // Parse and validate query parameters with defaults
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      // Sample data
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Implement pagination
      const users = allUsers.slice(offset, offset + limit);

      // Return paginated results
      res.json({
        success: true,
        data: users,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
        },
      });
    } catch (error) {
      handleError(error, res);
    }
  }
);

// Example POST endpoint with body validation
app.post(
  '/users',
  // Validate request body
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
