// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const app = express();

// Security: Set security HTTP headers
app.use(helmet());

// Logging: Monitor all requests
app.use(morgan('combined'));

// Middleware: Parse JSON with size limit to prevent payload attacks
app.use(express.json({ limit: '10kb' }));

// Security: Rate limiting to prevent brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Security: Stricter rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

// Input Validation Helper
function validateQueryParams(query) {
  const errors = [];

  // Validate 'limit' parameter if provided
  if (query.limit !== undefined) {
    const limit = parseInt(query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('limit must be a number between 1 and 100');
    }
  }

  // Validate 'search' parameter if provided
  if (query.search !== undefined) {
    if (typeof query.search !== 'string') {
      errors.push('search must be a string');
    }
    if (query.search.length > 100) {
      errors.push('search must be less than 100 characters');
    }
  }

  return errors;
}

// Health check endpoint - no parameters needed
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', (req, res) => {
  try {
    // Input validation
    const validationErrors = validateQueryParams(req.query);
    if (validationErrors.length > 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid query parameters',
        errors: validationErrors,
      });
    }

    // Parse and use validated parameters with defaults
    const limit = req.query.limit ? Math.min(parseInt(req.query.limit, 10), 100) : 10;
    const search = (req.query.search || '').toLowerCase();

    // Sample data (in production, fetch from secure database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter based on search parameter if provided
    let users = allUsers;
    if (search) {
      users = allUsers.filter(
        (user) =>
          user.name.toLowerCase().includes(search) ||
          user.email.toLowerCase().includes(search)
      );
    }

    // Apply limit
    users = users.slice(0, limit);

    res.json({
      status: 'success',
      data: users,
      count: users.length,
    });
  } catch (error) {
    // Log error for debugging (don't expose to client)
    console.error('Users endpoint error:', error);

    // Return safe error message
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

// Error handling middleware for 404 responses
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Default error response
  let statusCode = err.statusCode || 500;
  let message = 'Internal server error';

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const response = {
    status: 'error',
    message,
  };

  if (isDevelopment) {
    response.error = err.message;
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

# Security Review & Improvement Recommendations for app.js

## Executive Summary
The current app.js lacks critical security controls including input validation, error handling, security headers, and rate limiting. Below are detailed recommendations with severity levels.

---

## Critical Issues (Fix Immediately)

### 1. **No Input Validation** ⚠️ CRITICAL
**Problem:**
- Endpoint accepts any query parameters without validation
- Vulnerable to injection attacks and unexpected behavior
- No parameter type or length checks

**Solution:**
```javascript
function validateQueryParams(query) {
  const errors = [];

  if (query.limit !== undefined) {
    const limit = parseInt(query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('limit must be a number between 1 and 100');
    }
  }

  if (query.search !== undefined) {
    if (typeof query.search !== 'string') {
      errors.push('search must be a string');
    }
    if (query.search.length > 100) {
      errors.push('search must be less than 100 characters');
    }
  }

  return errors;
}
```

**Dependencies to add:**
```bash
npm install express-validator
# Or use simpler manual validation as shown above
```

---

### 2. **Missing Error Handling** ⚠️ CRITICAL
**Problem:**
- No try-catch blocks
- Unhandled errors could crash the server or expose stack traces
- No error middleware for centralized error handling

**Solution:**
```javascript
// Wrap route handlers in try-catch
app.get('/users', (req, res) => {
  try {
    // Validate input
    const validationErrors = validateQueryParams(req.query);
    if (validationErrors.length > 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid query parameters',
        errors: validationErrors,
      });
    }
    // ... rest of logic
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

// Add global error middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.statusCode || 500).json({
    status: 'error',
    message: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});
```

---

## High Priority Issues

### 3. **Missing Security Headers** ⚠️ HIGH
**Problem:**
- No protection against XSS, clickjacking, or other common attacks
- Missing CORS configuration

**Solution:**
```bash
npm install helmet cors
```

```javascript
const helmet = require('helmet');
const cors = require('cors');

// Set security HTTP headers
app.use(helmet());

// Configure CORS appropriately
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
}));
```

**What Helmet provides:**
- Content Security Policy (CSP)
- X-Frame-Options (clickjacking protection)
- X-Content-Type-Options (MIME type sniffing prevention)
- Strict-Transport-Security (HTTPS enforcement)
- X-XSS-Protection

---

### 4. **No Rate Limiting** ⚠️ HIGH
**Problem:**
- Vulnerable to brute force and DoS attacks
- No throttling of requests

**Solution:**
