// Improved application with security best practices and error handling
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const cors = require('cors');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Use helmet to set various HTTP headers
app.use(helmet());

// CORS configuration - restrict to specific origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};
app.use(cors(corsOptions));

// Rate limiting - protect against brute force and DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// More strict rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
});

// Parse JSON body with size limit
app.use(express.json({ limit: '10kb' }));

// ============================================
// LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// ============================================
// ERROR HANDLING MIDDLEWARE (must be before routes)
// ============================================

// Custom error handler
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

// ============================================
// REQUEST VALIDATION HELPERS
// ============================================

const validateQueryParams = (params) => {
  const errors = [];

  if (params.limit) {
    const limit = parseInt(params.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('limit must be a number between 1 and 100');
    }
  }

  if (params.offset) {
    const offset = parseInt(params.offset, 10);
    if (isNaN(offset) || offset < 0) {
      errors.push('offset must be a non-negative number');
    }
  }

  if (params.search && !validator.isLength(params.search, { min: 1, max: 100 })) {
    errors.push('search must be between 1 and 100 characters');
  }

  return errors;
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    next(new AppError('Health check failed', 500));
  }
});

// Get users endpoint with validation
app.get('/users', strictLimiter, (req, res, next) => {
  try {
    // Validate query parameters
    const validationErrors = validateQueryParams(req.query);
    if (validationErrors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: validationErrors,
      });
    }

    // Parse pagination parameters with defaults
    const limit = req.query.limit ? Math.min(parseInt(req.query.limit, 10), 100) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

    // Mock data (in production, query from database with proper escaping)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: allUsers.length,
        limit,
        offset,
        returned: paginatedUsers.length,
      },
    });
  } catch (error) {
    next(new AppError('Failed to fetch users', 500));
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist',
    path: req.path,
  });
});

// ============================================
// GLOBAL ERROR HANDLING MIDDLEWARE
// ============================================

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Log error (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    statusCode,
    message: err.message,
    path: req.path,
    method: req.method,
    ...(isDevelopment && { stack: err.stack }),
  });

  // Don't expose error details in production
  const response = {
    error: 'Internal Server Error',
    ...(isDevelopment && { message: err.message }),
    ...(isDevelopment && { stack: err.stack }),
  };

  // Customize response for specific status codes
  if (statusCode === 400) {
    response.error = 'Bad Request';
  } else if (statusCode === 404) {
    response.error = 'Not Found';
  } else if (statusCode === 429) {
    response.error = 'Too Many Requests';
  }

  res.status(statusCode).json(response);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Improvement Recommendations for app.js

## Executive Summary
The original app.js is a basic Express server with **critical security gaps** that should be addressed before production use. This document outlines vulnerabilities, improvements, and best practices.

---

## 🔴 Critical Issues

### 1. **No Input Validation**
**Risk**: SQL Injection, XSS, malicious data processing
```javascript
// ❌ BEFORE: No validation
app.get('/users', (req, res) => {
  // Query parameters accepted without validation
});

// ✅ AFTER: With validation
const validationErrors = validateQueryParams(req.query);
if (validationErrors.length > 0) {
  return res.status(400).json({ error: 'Validation failed', details: validationErrors });
}
```

### 2. **Missing Error Handling**
**Risk**: Information disclosure, server crashes, unhandled exceptions
```javascript
// ❌ BEFORE: No error handling
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// ✅ AFTER: With try-catch
try {
  res.json({ status: 'ok' });
} catch (error) {
  next(new AppError('Health check failed', 500));
}
```

### 3. **No Rate Limiting**
**Risk**: Brute force attacks, DDoS, API abuse
```javascript
// ✅ ADDED: Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);
```

### 4. **Missing Security Headers**
**Risk**: XSS, Clickjacking, MIME-type sniffing
