## 🔍 Key Code Patterns to Understand

### Pattern 1: Validation Helper
```javascript
const validateQueryParams = (params) => {
  const errors = [];
  // Check each parameter
  if (params.limit && (isNaN(params.limit) || params.limit < 1)) {
    errors.push('limit must be positive number');
  }
  return errors;
};

// Usage
const errors = validateQueryParams(req.query);
if (errors.length > 0) {
  return res.status(400).json({ error: 'Validation failed', details: errors });
}
```

### Pattern 2: Error Handling
```javascript
// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
  }
}

// Usage
try {
  // some operation
  res.json({ data });
} catch (error) {
  next(new AppError('Operation failed', 500));
}

// Global handler catches it
app.use((err, req, res, next) => {
  res.status(err.statusCode || 500).json({ error: err.message });
});
```

### Pattern 3: Rate Limiting
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                   // 100 requests
  message: 'Too many requests'
});

// Apply to all routes
app.use(limiter);

// Or specific routes
app.get('/sensitive', strictLimiter, (req, res) => {
  // max 5 requests per 15 minutes
});
```

### Pattern 4: CORS Configuration
```javascript
const corsOptions = {
  origin: ['http://localhost:3000'],      // Allow only these origins
  credentials: true,                      // Allow cookies
  methods: ['GET', 'OPTIONS'],            // Only GET requests
  allowedHeaders: ['Content-Type'],       // Only these headers
};
app.use(cors(corsOptions));
```

### Pattern 5: Environment-Based Configuration
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';

// Usage in error handling
const isDevelopment = NODE_ENV === 'development';
res.json({
  error: 'Error occurred',
  ...(isDevelopment && { stack: error.stack })  // Only show in dev
});
```

