## 🚨 Common Mistakes to Avoid

### ❌ Don't
```javascript
// Don't expose stack traces in production
app.use((err, req, res) => {
  res.json({ error: err.stack });  // ❌ Dangerous!
});

// Don't hardcode sensitive values
const SECRET = 'my-secret-key';  // ❌ Wrong!

// Don't skip validation
app.get('/users', (req, res) => {
  const limit = req.query.limit;  // ❌ No validation!
});

// Don't open CORS to everyone
app.use(cors());  // ❌ Allows any origin!

// Don't catch errors silently
app.get('/endpoint', (req, res) => {
  // error happens but isn't caught
});
```

### ✅ Do
```javascript
// Do hide stack traces in production
app.use((err, req, res) => {
  const isDev = process.env.NODE_ENV === 'development';
  res.json({
    error: err.message,
    ...(isDev && { stack: err.stack })
  });
});

// Do use environment variables
const SECRET = process.env.SECRET;  // ✅ Correct!

// Do validate all input
app.get('/users', (req, res) => {
  const errors = validateQueryParams(req.query);
  if (errors.length > 0) return res.status(400).json({ errors });
});

// Do restrict CORS explicitly
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS.split(',')
}));

// Do catch and handle errors
app.get('/endpoint', (req, res, next) => {
  try {
    // operations
  } catch (error) {
    next(error);
  }
});
```

