const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Helmet.js - Set security HTTP headers
app.use(helmet());

// 2. Request logging
app.use(morgan('combined'));

// 3. Rate limiting - prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // stricter limit for sensitive endpoints
});

app.use(limiter);

// 4. Body parser middleware with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payloads
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. CORS configuration
const cors = require('cors');
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'OPTIONS'],
};
app.use(cors(corsOptions));

// ============ VALIDATION MIDDLEWARE ============

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation error',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============ ROUTES ============

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get users endpoint with input validation
app.get('/users',
  strictLimiter,
  query('filter').optional().isIn(['active', 'inactive']).withMessage('Invalid filter value'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  handleValidationErrors,
  (req, res) => {
    try {
      const { filter = 'active', limit = 10 } = req.query;

      // Sanitized user data - remove sensitive info
      const users = [
        { id: 1, name: 'Alice', status: 'active' },
        { id: 2, name: 'Bob', status: 'inactive' },
      ];

      // Apply filtering
      const filtered = users.filter(u =>
        filter === 'active' ? u.status === 'active' : u.status === 'inactive'
      );

      // Apply limit
      const result = filtered.slice(0, parseInt(limit, 10));

      res.json({
        data: result,
        count: result.length,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Example: POST endpoint with input validation
app.post('/users',
  strictLimiter,
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  handleValidationErrors,
  (req, res) => {
    try {
      const { name, email } = req.body;

      // Simulate user creation
      const newUser = {
        id: 3,
        name,
        // Don't return email in response without authorization
        createdAt: new Date().toISOString()
      };

      res.status(201).json({ data: newUser });
    } catch (error) {
      console.error('Error in POST /users:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details to client
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(status).json({
    error: message,
    timestamp: new Date().toISOString()
  });
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful error handling for server startup
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', error);
  }
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Improvements for app.js

## Summary of Issues & Fixes

### 🔴 CRITICAL ISSUES

| Issue | Severity | Fix | Impact |
|-------|----------|-----|--------|
| No global error handler | HIGH | Added try-catch and error middleware | Prevents crashes & info leakage |
| No input validation | HIGH | Added express-validator | Prevents injection attacks |
| Missing security headers | HIGH | Added helmet.js | Protects against XSS, clickjacking |
| PII exposure (emails) | HIGH | Removed from list responses | Prevents data breaches |
| No rate limiting | HIGH | Added express-rate-limit | Prevents DoS/brute force |
| No request sanitization | MEDIUM | Added trim(), normalization | Prevents malformed data |

---

## Detailed Recommendations

### 1. **Global Error Handling**
```javascript
// BEFORE: No error handling - server crashes on exception
app.get('/users', (req, res) => {
  res.json([...]); // Any error crashes the app
});

// AFTER: Proper error handling
app.get('/users', (req, res) => {
  try {
    res.json([...]);
  } catch (error) {
    console.error('Error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

### 2. **Input Validation**
```javascript
// BEFORE: No validation of query parameters
app.get('/users?filter=<script>alert('xss')</script>')

// AFTER: Strict validation with express-validator
query('filter')
  .optional()
  .isIn(['active', 'inactive'])
  .withMessage('Invalid filter value')
```

### 3. **Helmet.js - Security Headers**
```javascript
// Adds headers like:
// - Content-Security-Policy
// - X-Frame-Options: DENY (prevent clickjacking)
// - X-Content-Type-Options: nosniff
// - Strict-Transport-Security
app.use(helmet());
```

### 4. **Rate Limiting**
```javascript
// Prevent abuse and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100 // 100 requests per 15 minutes per IP
});
app.use(limiter);
```

### 5. **CORS Configuration**
```javascript
