/**
 * Environment Configuration with Validation
 * 
 * This module validates and loads environment variables with strict type checking
 * and secure defaults. It fails fast if required variables are missing.
 * 
 * Usage:
 *   const config = require('./config');
 *   app.listen(config.PORT);
 */

const requiredVars = {
  NODE_ENV: {
    type: 'string',
    values: ['development', 'production', 'test'],
    description: 'Application environment'
  },
};

const optionalVars = {
  PORT: {
    type: 'number',
    default: 3000,
    min: 1,
    max: 65535,
    description: 'Server port'
  },
  ALLOWED_ORIGINS: {
    type: 'string',
    default: 'http://localhost:3000',
    description: 'CORS allowed origins (comma-separated URLs)'
  },
  // These are NOT used in current code but validated if provided
  DATABASE_URL: {
    type: 'string',
    description: 'PostgreSQL connection string'
  },
  AWS_ACCESS_KEY_ID: {
    type: 'string',
    description: 'AWS access key'
  },
  AWS_SECRET_ACCESS_KEY: {
    type: 'string',
    description: 'AWS secret access key'
  },
  ANTHROPIC_API_KEY: {
    type: 'string',
    description: 'Anthropic/Claude API key'
  },
  STRIPE_SECRET_KEY: {
    type: 'string',
    description: 'Stripe secret key'
  },
  LOGFIRE_TOKEN: {
    type: 'string',
    description: 'Logfire logging token'
  },
};

/**
 * Validate configuration
 * @throws {Error} If required variables are missing or invalid
 * @returns {Object} Validated configuration object
 */
function loadConfig() {
  const config = {};
  const errors = [];
  const warnings = [];

  // Validate required variables
  for (const [key, spec] of Object.entries(requiredVars)) {
    const value = process.env[key];

    if (!value) {
      errors.push(`Missing required variable: ${key}`);
      continue;
    }

    if (spec.values && !spec.values.includes(value)) {
      errors.push(
        `Invalid value for ${key}: "${value}". ` +
        `Must be one of: ${spec.values.join(', ')}`
      );
      continue;
    }

    config[key] = value;
  }

  // Validate optional variables
  for (const [key, spec] of Object.entries(optionalVars)) {
    const value = process.env[key];

    if (!value) {
      // Use default if available
      if (spec.default !== undefined) {
        config[key] = spec.default;
      }
      continue;
    }

    // Type validation
    if (spec.type === 'number') {
      const num = parseInt(value, 10);
      if (isNaN(num)) {
        errors.push(`Invalid number for ${key}: "${value}"`);
        continue;
      }
      if (spec.min !== undefined && num < spec.min) {
        errors.push(`${key} must be >= ${spec.min}, got ${num}`);
        continue;
      }
      if (spec.max !== undefined && num > spec.max) {
        errors.push(`${key} must be <= ${spec.max}, got ${num}`);
        continue;
      }
      config[key] = num;
    } else if (spec.type === 'string') {
      config[key] = value.trim();
    }

    // Warn about potentially sensitive unused variables
    if (key.includes('KEY') || key.includes('TOKEN') || key.includes('SECRET')) {
      // In production, warn if sensitive vars are set
      if (process.env.NODE_ENV === 'production') {
        // This is expected, don't warn
      } else if (process.env.NODE_ENV === 'test') {
        // In test, check if they look like real credentials
        if (isLikelyRealCredential(value)) {
          warnings.push(
            `⚠️  ${key} looks like a real credential in ${process.env.NODE_ENV} environment. ` +
            `Use mock values only.`
          );
        }
      }
    }
  }

  // Report errors
  if (errors.length > 0) {
    console.error('\n❌ Configuration validation failed:\n');
    errors.forEach(err => console.error(`  • ${err}`));
    console.error('\nRequired variables:');
    Object.entries(requiredVars).forEach(([key, spec]) => {
      console.error(`  • ${key}: ${spec.description}`);
    });
    process.exit(1);
  }

  // Report warnings
  if (warnings.length > 0) {
    console.warn('\n⚠️  Configuration warnings:\n');
    warnings.forEach(warn => console.warn(`  ${warn}`));
  }

  // Log configuration in development
  if (process.env.NODE_ENV === 'development') {
    console.log('\n✓ Configuration loaded:');
    Object.entries(config).forEach(([key, value]) => {
      const isSecret = key.includes('KEY') || key.includes('TOKEN') || key.includes('SECRET');
      const displayValue = isSecret ? '(hidden)' : value;
      console.log(`  ${key}: ${displayValue}`);
    });
    console.log();
  }

  // Return config with additional helpers
  return {
    ...config,
    isDevelopment: config.NODE_ENV === 'development',
    isProduction: config.NODE_ENV === 'production',
    isTest: config.NODE_ENV === 'test',
  };
}

/**
 * Check if a string looks like a real credential vs a test/mock value
 * @param {string} value
 * @returns {boolean}
 */
function isLikelyRealCredential(value) {
  // Check for common credential patterns
  const patterns = [
    /^AKIA[0-9A-Z]{16}$/, // AWS Access Key
    /^ASIA[0-9A-Z]{16}$/, // AWS Temporary Key
    /^sk_live_[A-Za-z0-9_]+$/, // Stripe Live Key
    /^sk_test_[A-Za-z0-9_]+$/, // Stripe Test Key (but acceptable)
    /^pk_live_[A-Za-z0-9_]+$/, // Stripe Live Public Key
    /^sk_prod_[A-Za-z0-9_]+$/, // Other live patterns
  ];

  // Real credentials usually don't contain "CANARY", "test", or "mock"
  if (/CANARY|mock|test_|example/i.test(value)) {
    return false;
  }

  // Check if matches real credential patterns
  return patterns.some(pattern => pattern.test(value));
}

