// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Set security HTTP headers
app.use(helmet());

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use('/api/', limiter);

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// ==================== LOGGING ====================

// Simple request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ==================== ROUTES ====================

/**
 * Health check endpoint
 * @returns {Object} Health status
 */
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      // Don't expose exact timestamp - potential information leak
      timestamp: Math.floor(Date.now() / 1000),
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint with optional filtering
 * @query {string} role - Optional role filter (admin, user)
 * @returns {Array} Array of users (without sensitive data)
 */
app.get('/api/users', (req, res, next) => {
  try {
    // Input validation: validate query parameters
    const { role } = req.query;

    // Whitelist allowed roles
    const allowedRoles = ['admin', 'user'];
    if (role && !allowedRoles.includes(role.toLowerCase())) {
      return res.status(400).json({
        error: 'Invalid role parameter',
        message: `Role must be one of: ${allowedRoles.join(', ')}`,
      });
    }

    // Sample data - in real app, this would come from a database
    let users = [
      { id: 1, name: 'Alice', role: 'admin' },
      { id: 2, name: 'Bob', role: 'user' },
    ];

    // Filter by role if provided
    if (role) {
      users = users.filter(u => u.role.toLowerCase() === role.toLowerCase());
    }

    res.json({
      success: true,
      data: users,
      count: users.length,
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Create user endpoint
 * @body {Object} name - User name (required, string, 1-100 chars)
 * @body {Object} role - User role (optional, must be valid role)
 * @returns {Object} Created user
 */
app.post('/api/users', (req, res, next) => {
  try {
    const { name, role } = req.body;

    // Input validation: check required fields
    if (!name || typeof name !== 'string') {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'Name is required and must be a string',
      });
    }

    // Input validation: check name length
    if (name.length < 1 || name.length > 100) {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'Name must be between 1 and 100 characters',
      });
    }

    // Input validation: sanitize and validate role
    const allowedRoles = ['admin', 'user'];
    const userRole = role && allowedRoles.includes(role) ? role : 'user';

    // In real app, save to database here
    const newUser = {
      id: Math.floor(Math.random() * 10000),
      name: name.trim(),
      role: userRole,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      success: true,
      data: newUser,
      message: 'User created successfully',
    });
  } catch (error) {
    next(error);
  }
});

// ==================== 404 HANDLER ====================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested endpoint does not exist',
  });
});

// ==================== GLOBAL ERROR HANDLER ====================

/**
 * Global error handling middleware
 * Must be last middleware - placed at the end
 */
app.use((error, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error(`[ERROR] ${new Date().toISOString()}`);
  console.error(`Path: ${req.method} ${req.path}`);
  console.error(`Message: ${error.message}`);
  console.error(`Stack: ${error.stack}`);

  // Determine status code
  const statusCode = error.statusCode || 500;

  // In production, don't expose internal error details
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    error: isDevelopment ? error.message : 'Internal server error',
    ...(isDevelopment && { stack: error.stack }),
  };

  res.status(statusCode).json(errorResponse);
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

# Security Review: app.js

## Executive Summary
The current application has **critical security gaps** in error handling, input validation, and security hardening. The improved version addresses these with industry best practices.

---

## 🔴 Critical Issues Found

### 1. **No Global Error Handler**
**Risk:** Unhandled errors can crash the server or expose sensitive information

**Original Code:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Issue:** No error handling - if `res.json()` fails, the app crashes

**Fix:**
```javascript
app.use((error, req, res, next) => {
  console.error(`[ERROR] ${error.message}`);
  const statusCode = error.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: isDevelopment ? error.message : 'Internal server error'
  });
});
```

---

### 2. **No Input Validation**
**Risk:** NoSQL injection, XSS, data type attacks

**Original Code:**
```javascript
app.get('/users', (req, res) => { /* No validation */ }
```

**Issues:**
- Query parameters not validated
- No type checking
- Vulnerable to injection attacks

**Fix:**
```javascript
app.get('/api/users', (req, res, next) => {
  try {
    const { role } = req.query;

    // Whitelist validation
    const allowedRoles = ['admin', 'user'];
    if (role && !allowedRoles.includes(role.toLowerCase())) {
      return res.status(400).json({
        error: 'Invalid role parameter',
        message: `Role must be one of: ${allowedRoles.join(', ')}`
      });
    }
    // ... continue
  } catch (error) {
    next(error);
  }
});
```

---

### 3. **No Security Headers**
**Risk:** Clickjacking, MIME sniffing, XSS attacks

**Missing Protections:**
- No X-Frame-Options header
- No X-Content-Type-Options header
- No Content-Security-Policy
- No HSTS (HTTP Strict Transport Security)

**Fix:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets 15+ security headers
```

---

### 4. **No Rate Limiting**
**Risk:** DDoS attacks, brute force attacks, resource exhaustion

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests'
});
app.use('/api/', limiter);
```

---

### 5. **No Request Size Limiting**
**Risk:** Memory exhaustion, malicious payload attacks

**Fix:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 6. **No Data Sanitization**
**Risk:** NoSQL injection, XSS attacks

**Original Code:**
```javascript
app.get('/users', (req, res) => {
  // User input not sanitized
});
```

**Fix:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

app.use(mongoSanitize());
app.use(xss());
```

---

### 7. **Exposed Sensitive Information**
**Risk:** Information disclosure

**Original Code:**
```javascript
{ status: 'ok', timestamp: new Date().toISOString() }
```

**Issues:**
- Exact timestamp reveals server time
- Email addresses exposed in user endpoint
- No response structure consistency

**Fix:**
```javascript
// Use Unix timestamp instead of ISO string
{ status: 'ok', timestamp: Math.floor(Date.now() / 1000) }

// Remove sensitive fields from responses
{ id: 1, name: 'Alice', role: 'admin' } // No email exposed
```

---

### 8. **No Logging Mechanism**
**Risk:** Debugging difficulties, security audit trail loss

**Fix:**
```javascript
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

app.use((error, req, res, next) => {
  console.error(`[ERROR] ${error.message}`);
  console.error(`Stack: ${error.stack}`);
});
```

---

### 9. **No 404 Handler**
**Risk:** Information leakage through default error pages

**Original Code:**
Express returns HTML default 404 page

**Fix:**
```javascript
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested endpoint does not exist'
  });
});
```

---

### 10. **No Request Body Validation (POST/PUT)**
**Risk:** Invalid data stored, type confusion attacks

**Fix:**
```javascript
app.post('/api/users', (req, res, next) => {
  try {
    const { name, role } = req.body;

    // Type validation
    if (!name || typeof name !== 'string') {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'Name is required and must be a string'
      });
    }

    // Length validation
    if (name.length < 1 || name.length > 100) {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'Name must be between 1 and 100 characters'
      });
    }

    // Whitelist validation
    const allowedRoles = ['admin', 'user'];
    if (role && !allowedRoles.includes(role)) {
      return res.status(400).json({
        error: 'Invalid role'
      });
    }
  } catch (error) {
    next(error);
  }
});
```

---

## 📋 Recommended Security Packages

```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.7.0",
    "express-mongo-sanitize": "^2.2.0",
    "xss-clean": "^0.1.1",
    "joi": "^17.9.2"
  },
  "devDependencies": {
    "dotenv": "^16.0.3"
  }
}
```

---

## 🛡️ Additional Best Practices

### 1. **Environment Variables**
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

### 2. **CORS Configuration** (if needed)
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200
}));
```

### 3. **Request ID Tracking**
```javascript
const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = uuidv4();
  res.set('X-Request-ID', req.id);
  next();
});
```

### 4. **Database Input Validation (if using database)**
- Use parameterized queries
- Validate schemas before database operations
- Use ORMs with built-in protections (Mongoose, Sequelize)

### 5. **Authentication & Authorization**
```javascript
// Implement JWT or session-based auth
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Verify token
  next();
};
```

### 6. **HTTPS/TLS**
- Always use HTTPS in production
- Set HSTS headers: `app.use(helmet.hsts())`

### 7. **Database Security**
- Use connection pooling
- Implement query timeouts
- Validate all inputs before database queries

---

## ✅ Security Checklist

- [x] Global error handling middleware
- [x] Input validation on all endpoints
- [x] Security headers (Helmet)
- [x] Rate limiting
- [x] Request size limiting
- [x] Data sanitization (NoSQL injection, XSS)
- [x] No sensitive data exposure
- [x] Request logging
- [x] 404 handling
- [x] Request body validation
- [ ] Authentication (to be implemented)
- [ ] HTTPS/TLS (production setup)
- [ ] Database security (depends on DB choice)
- [ ] CORS configuration (if needed)

---

## 🚀 Migration Path

1. Install dependencies: `npm install helmet express-rate-limit express-mongo-sanitize xss-clean`
2. Replace app.js with improved version
3. Set up environment variables
4. Add tests for validation logic
5. Test thoroughly in staging
6. Deploy with monitoring

---

## References

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Node.js Security Best Practices](https://nodejs.org/en/docs/guides/security/)
- [Express.js Security](https://expressjs.com/en/advanced/best-practice-security.html)
- [Helmet.js Documentation](https://helmetjs.github.io/)

