// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const validator = require('validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ============================================
// VALIDATION & SANITIZATION UTILITIES
// ============================================

// Validate user ID (numeric)
const validateUserId = (id) => {
  if (!id) return { valid: false, error: 'User ID is required' };
  if (!Number.isInteger(Number(id)) || Number(id) <= 0) {
    return { valid: false, error: 'User ID must be a positive integer' };
  }
  return { valid: true };
};

// Validate and sanitize email
const validateEmail = (email) => {
  if (!email) return { valid: false, error: 'Email is required' };
  if (!validator.isEmail(email)) {
    return { valid: false, error: 'Invalid email format' };
  }
  return { valid: true };
};

// Validate and sanitize name
const validateName = (name) => {
  if (!name) return { valid: false, error: 'Name is required' };
  if (typeof name !== 'string') {
    return { valid: false, error: 'Name must be a string' };
  }
  if (name.length < 1 || name.length > 100) {
    return { valid: false, error: 'Name must be between 1 and 100 characters' };
  }
  // Remove potentially harmful characters
  const sanitized = validator.escape(name.trim());
  return { valid: true, value: sanitized };
};

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/users', (req, res) => {
  try {
    // Validate optional query parameters
    const page = req.query.page ? parseInt(req.query.page, 10) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;

    // Input validation for pagination
    if (isNaN(page) || page < 1) {
      return res.status(400).json({
        error: 'Invalid page parameter. Must be a positive integer.',
      });
    }

    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 100.',
      });
    }

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = allUsers.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: allUsers.length,
      },
    });
  } catch (error) {
    // Log error securely (don't expose internal details to client)
    console.error('Error in /users endpoint:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate user ID
    const validation = validateUserId(id);
    if (!validation.valid) {
      return res.status(400).json({ error: validation.error });
    }

    // Mock user data
    const users = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com' },
    };

    const user = users[id];

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    console.error('Error in /users/:id endpoint:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// POST endpoint example (commented for reference)
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Validate input
    if (!name || !email) {
      return res.status(400).json({
        error: 'Missing required fields: name and email',
      });
    }

    const nameValidation = validateName(name);
    if (!nameValidation.valid) {
      return res.status(400).json({ error: nameValidation.error });
    }

    const emailValidation = validateEmail(email);
    if (!emailValidation.valid) {
      return res.status(400).json({ error: emailValidation.error });
    }

    // Create user (mock)
    const newUser = {
      id: Math.floor(Math.random() * 10000),
      name: nameValidation.value,
      email: email.toLowerCase(),
    };

    res.status(201).json(newUser);
  } catch (error) {
    console.error('Error in POST /users endpoint:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err.message);

  // Don't expose internal error details
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal server error' : err.message,
  });
});

// ============================================
// SERVER START
// ============================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

