// Enhanced application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// MIDDLEWARE - Security & Logging
// ============================================================================

// Security headers
app.use(helmet());

// CORS configuration
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  next();
});

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
});

app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// JSON parsing with size limit
app.use(express.json({ limit: '10kb' }));

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

/**
 * Get users endpoint with query validation
 * GET /users?limit=10&offset=0
 */
app.get('/users',
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),

  // Request handler
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid input parameters',
        errors: errors.array().map(err => ({
          field: err.param,
          message: err.msg,
        })),
      });
    }

    try {
      // Parse query parameters with defaults
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      // Mock user database (in production, use real DB with parameterized queries)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const paginatedUsers = allUsers.slice(offset, offset + limit);

      res.status(200).json({
        status: 'success',
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
        },
      });
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({
        status: 'error',
        message: 'Failed to retrieve users',
      });
    }
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    path: req.path,
    method: req.method,
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('[ERROR]', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    status: 'error',
    message: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT} (${NODE_ENV})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Uncaught exception handler
process.on('uncaughtException', (error) => {
  console.error('[UNCAUGHT EXCEPTION]', error);
  process.exit(1);
});

// Unhandled promise rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('[UNHANDLED REJECTION]', reason);
  process.exit(1);
});

module.exports = app;

# Security Review: app.js

## Executive Summary
The current `app.js` is missing critical error handling, input validation, and security measures. This document outlines vulnerabilities and recommended improvements.

---

## 🔴 Critical Issues

### 1. **No Input Validation**
**Risk Level:** HIGH

**Current State:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // Accepts any query parameters
});
```

**Vulnerabilities:**
- Query injection attacks possible
- No bounds checking on pagination
- No type validation

**Solution:**
```javascript
app.get('/users',
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // ... handle request
  }
);
```

**Dependencies to Add:**
```bash
npm install express-validator
```

---

### 2. **Missing Error Handling**
**Risk Level:** HIGH

**Current State:**
- No try-catch blocks
- Unhandled promise rejections could crash server
- No error middleware

**Impact:**
- Server crashes on unexpected errors
- No logging for debugging
- Poor user experience

**Solution:**
- Add try-catch blocks in all route handlers
- Implement global error middleware
- Add process-level error handlers for uncaught exceptions
- Use proper HTTP status codes

---

### 3. **No Security Headers**
**Risk Level:** MEDIUM

**Current State:**
- Vulnerable to clickjacking (X-Frame-Options missing)
- XSS protection headers missing
- HSTS not configured
- Content Security Policy missing

**Solution:**
```bash
npm install helmet
```

```javascript
const helmet = require('helmet');
app.use(helmet());
```

This adds:
- X-Frame-Options: DENY
- X-Content-Type-Options: nosniff
- Strict-Transport-Security
- Content-Security-Policy
- And more...

---

### 4. **Missing Rate Limiting**
**Risk Level:** MEDIUM

**Current State:**
- No protection against brute force attacks
- No DDoS protection
- No request throttling

**Solution:**
```bash
npm install express-rate-limit
```

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);
```

---

### 5. **No CORS Configuration**
**Risk Level:** MEDIUM

**Current State:**
- No origin restrictions
- Could be accessed from any domain
- No preflight handling

**Solution:**
```javascript
app.use((req, res, next) => {
  const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',');
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }

  res.setHeader('Access-Control-Allow-Methods', 'GET, POST');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  next();
});
```

---

### 6. **Sensitive Data Exposure**
**Risk Level:** MEDIUM

**Current State:**
- Email addresses exposed in public endpoint
- No authentication or authorization checks
- No data encryption in transit

**Solution:**
- Add authentication middleware
- Implement role-based access control
- Mask sensitive data in responses
- Use HTTPS in production
- Add request signing/verification

---

### 7. **No Request Size Limits**
**Risk Level:** MEDIUM

**Current State:**
- Potential memory exhaustion
- Large payload attacks possible

**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
```

---

### 8. **Missing Environment Variable Handling**
**Risk Level:** LOW-MEDIUM

**Current State:**
```javascript
app.listen(3000, () => { // Hardcoded port
  console.log('Server running on port 3000');
});
```

**Solution:**
```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});
```

---

### 9. **No Graceful Shutdown**
**Risk Level:** LOW

**Current State:**
- Abrupt server termination
- Pending requests may be dropped
- Resource leaks possible

**Solution:**
```javascript
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

---

### 10. **Inadequate Logging**
**Risk Level:** LOW-MEDIUM

**Current State:**
- No request logging
- No error tracking
- Hard to debug issues

**Solution:**
```javascript
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});
```

Consider using a proper logging library like `winston` or `bunyan` for production.

---

