# Security Best Practices Code Patterns

## 1. Input Validation Pattern

### ❌ BEFORE (Unsafe)
```javascript
app.get('/users', (req, res) => {
  const limit = req.query.limit;  // No validation!
  const offset = req.query.offset; // Could be anything
  res.json({ limit, offset });
});
```

### ✅ AFTER (Secure)
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  // Validation middleware
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be an integer between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .toInt()
    .withMessage('Offset must be a non-negative integer'),

  // Handler
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors: errors.array(),
      });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;
    res.json({ limit, offset });
  }
);
```

---

## 2. Error Handling Pattern

### ❌ BEFORE (Unsafe)
```javascript
app.get('/data', (req, res) => {
  const data = JSON.parse(req.body); // Could throw!
  res.json(data);
});
```

### ✅ AFTER (Secure)
```javascript
app.get('/data', (req, res) => {
  try {
    const data = JSON.parse(req.body);
    res.json(data);
  } catch (error) {
    console.error('Parse error:', error);
    res.status(400).json({
      status: 'error',
      message: 'Invalid JSON payload',
    });
  }
});
```

---

## 3. Database Query Pattern

### ❌ BEFORE (SQL Injection Vulnerable)
```javascript
app.get('/user/:id', (req, res) => {
  const userId = req.params.id;
  const query = `SELECT * FROM users WHERE id = ${userId}`; // VULNERABLE!
  db.query(query, (err, result) => {
    if (err) return res.status(500).json({ error: err });
    res.json(result);
  });
});
```

### ✅ AFTER (Protected)
```javascript
app.get('/user/:id',
  param('id').isInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id);
    const query = 'SELECT * FROM users WHERE id = ?'; // Parameterized!

    db.query(query, [userId], (err, result) => {
      if (err) {
        console.error('Database error:', err);
        return res.status(500).json({ 
          status: 'error',
          message: 'Database query failed' 
        });
      }

      if (!result || result.length === 0) {
        return res.status(404).json({ 
          status: 'error',
          message: 'User not found' 
        });
      }

      res.json({ status: 'success', data: result[0] });
    });
  }
);
```

---

## 4. Authentication Pattern

### ❌ BEFORE (No Authentication)
```javascript
app.get('/admin/users', (req, res) => {
  // Anyone can access!
  res.json(allUsers);
});
```

### ✅ AFTER (With Authentication)
```javascript
const jwt = require('jsonwebtoken');

// Middleware: Verify JWT
const verifyToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({
      status: 'error',
      message: 'Authorization token required',
    });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({
      status: 'error',
      message: 'Invalid or expired token',
    });
  }
};

// Protected route
app.get('/admin/users', verifyToken, (req, res) => {
  // Only authenticated users can access
  if (req.user.role !== 'admin') {
    return res.status(403).json({
      status: 'error',
      message: 'Admin access required',
    });
  }

  res.json({ status: 'success', data: allUsers });
});
```

---

## 5. Data Sanitization Pattern

### ❌ BEFORE (XSS Vulnerable)
```javascript
app.post('/comment', (req, res) => {
  const comment = req.body.text; // Could contain malicious HTML
  db.insert('comments', { text: comment });
  res.json({ text: comment }); // Reflected XSS!
});
```

### ✅ AFTER (Sanitized)
```javascript
const xss = require('xss');

app.post('/comment',
  body('text')
    .trim()
    .notEmpty().withMessage('Comment cannot be empty')
    .isLength({ max: 1000 }).withMessage('Comment too long')
    .escape(), // Escapes HTML

  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const sanitized = xss(req.body.text);

    try {
      db.insert('comments', { text: sanitized });
      res.status(201).json({ 
        status: 'success',
        data: { text: sanitized } 
      });
    } catch (error) {
      console.error('Insert error:', error);
      res.status(500).json({ 
        status: 'error',
        message: 'Failed to save comment' 
      });
    }
  }
);
```

---

## 6. Async/Await Error Handling Pattern

### ❌ BEFORE (Unhandled Promise Rejection)
```javascript
app.get('/data', async (req, res) => {
  const data = await fetchData(); // Could throw!
  res.json(data);
});
```

### ✅ AFTER (Safe)
```javascript
app.get('/data', async (req, res, next) => {
  try {
    const data = await fetchData();
    res.json({ status: 'success', data });
  } catch (error) {
    console.error('Fetch error:', error);
    next(error); // Pass to error middleware
  }
});
```

---

## 7. Middleware Chain Pattern

### ✅ CORRECT PATTERN
```javascript
// 1. Security middleware (first)
app.use(helmet());
app.use(cors());

// 2. Logging middleware
app.use(loggerMiddleware);

// 3. Rate limiting
app.use(rateLimiter);

// 4. Body parsing
app.use(express.json({ limit: '10kb' }));

// 5. Custom auth/validation middleware
app.use(authMiddleware);

// 6. Routes (last)
app.get('/public', publicRoute);
app.get('/protected', verifyToken, protectedRoute);

// 7. Error handling (last)
app.use(errorHandler);
```

---

## 8. Async Route Handler with try-catch Wrapper

### ✅ PATTERN
```javascript
// Create a wrapper to catch async errors automatically
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Use it like this:
app.get('/data', asyncHandler(async (req, res) => {
  const data = await db.query('SELECT * FROM data');
  res.json(data);
  // Errors automatically go to error middleware
}));
```

---

## 9. Validation Schema Pattern

### ✅ PATTERN
```javascript
const { body, validationResult } = require('express-validator');

// Define reusable schemas
const userValidation = {
  create: [
    body('email')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail()
      .toLowerCase(),
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be 2-100 characters'),
    body('password')
      .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
      .matches(/[A-Z]/).withMessage('Password must contain uppercase letter')
      .matches(/[0-9]/).withMessage('Password must contain number'),
  ],
  update: [
    body('name').optional().trim().isLength({ min: 2, max: 100 }),
    body('email').optional().isEmail(),
  ],
};

// Use schemas in routes
app.post('/users', userValidation.create, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process validated data
});
```

---

## 10. Environment Variable Pattern

### ✅ PATTERN
```javascript
// Load environment variables
require('dotenv').config();

// Validate required variables
const requiredEnvVars = ['PORT', 'JWT_SECRET', 'DB_URL'];
const missingVars = requiredEnvVars.filter(v => !process.env[v]);

if (missingVars.length > 0) {
  console.error(`Missing required environment variables: ${missingVars.join(', ')}`);
  process.exit(1);
}

// Type-safe access
const config = {
  port: parseInt(process.env.PORT, 10),
  nodeEnv: process.env.NODE_ENV || 'development',
  jwtSecret: process.env.JWT_SECRET,
  dbUrl: process.env.DB_URL,
  corsOrigins: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
};

module.exports = config;
```

