## 11. Error Response Pattern

### ✅ CONSISTENT ERROR RESPONSES
```javascript
// Structure all errors consistently
const errorResponses = {
  // Client errors (4xx)
  badRequest: (message, errors = []) => ({
    status: 'error',
    code: 'BAD_REQUEST',
    message,
    errors,
  }),

  unauthorized: (message = 'Authentication required') => ({
    status: 'error',
    code: 'UNAUTHORIZED',
    message,
  }),

  forbidden: (message = 'Access denied') => ({
    status: 'error',
    code: 'FORBIDDEN',
    message,
  }),

  notFound: (message = 'Resource not found') => ({
    status: 'error',
    code: 'NOT_FOUND',
    message,
  }),

  // Server errors (5xx)
  internal: (message = 'Internal server error') => ({
    status: 'error',
    code: 'INTERNAL_ERROR',
    message,
  }),
};

// Usage:
app.get('/user/:id', (req, res) => {
  const user = findUser(req.params.id);
  if (!user) {
    return res.status(404).json(errorResponses.notFound('User not found'));
  }
  res.json({ status: 'success', data: user });
});
```

