## 12. Rate Limiting by Endpoint Pattern

### ✅ PATTERN
```javascript
const rateLimit = require('express-rate-limit');

// Different limits for different endpoints
const publicLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests, please try again later',
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter for auth
  skipSuccessfulRequests: true, // Don't count successful attempts
  message: 'Too many login attempts, please try again later',
});

const apiLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 1000,
});

// Apply different limiters
app.post('/login', authLimiter, (req, res) => { /* ... */ });
app.get('/api/data', apiLimiter, (req, res) => { /* ... */ });
app.get('/public', publicLimiter, (req, res) => { /* ... */ });
```

---

## 13. Logging Pattern

### ✅ PATTERN
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Console logging in development
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Usage:
app.get('/data', (req, res) => {
  logger.info('Fetching data', { userId: req.user?.id, path: req.path });

  try {
    // ... code ...
  } catch (error) {
    logger.error('Data fetch failed', {
      error: error.message,
      userId: req.user?.id,
      stack: error.stack,
    });
  }
});
```

