/**
 * Configuration Validation Module
 * Validates environment variables on application startup
 * 
 * Usage: const config = require('./config');
 */

const path = require('path');

// List of required environment variables
const REQUIRED_ENV_VARS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

// List of optional environment variables with defaults
const OPTIONAL_ENV_VARS = {
  PORT: 3000,
  NODE_ENV: 'development',
  LOG_LEVEL: 'info',
  RATE_LIMIT_WINDOW_MS: 900000,
  RATE_LIMIT_MAX_REQUESTS: 100,
  REQUEST_SIZE_LIMIT: '10kb',
};

/**
 * Validate required environment variables
 * @throws {Error} If required variables are missing
 */
function validateRequired() {
  const missing = [];

  REQUIRED_ENV_VARS.forEach(varName => {
    if (!process.env[varName]) {
      missing.push(varName);
    }
  });

  if (missing.length > 0) {
    const message = `Missing required environment variables:\n  - ${missing.join('\n  - ')}\n\nPlease set these variables or update your .env file.`;
    console.error(message);
    throw new Error(message);
  }
}

/**
 * Validate database URL format
 * @throws {Error} If database URL is invalid
 */
function validateDatabaseUrl() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) return; // Skip if not required yet

  try {
    new URL(dbUrl);
  } catch (error) {
    throw new Error(`Invalid DATABASE_URL format: ${error.message}`);
  }
}

/**
 * Validate AWS credentials format
 * @throws {Error} If AWS credentials are invalid
 */
function validateAwsCredentials() {
  const keyId = process.env.AWS_ACCESS_KEY_ID;
  if (keyId && !keyId.startsWith('AKIA')) {
    console.warn('⚠️  AWS_ACCESS_KEY_ID does not start with "AKIA" - may be invalid');
  }
}

/**
 * Validate API keys format
 * @throws {Error} If API keys are invalid
 */
function validateApiKeys() {
  const anthropicKey = process.env.ANTHROPIC_API_KEY;
  if (anthropicKey && !anthropicKey.startsWith('sk-ant-')) {
    console.warn('⚠️  ANTHROPIC_API_KEY does not start with "sk-ant-" - may be invalid');
  }

  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (stripeKey && !stripeKey.startsWith('sk_live_') && !stripeKey.startsWith('sk_test_')) {
    console.warn('⚠️  STRIPE_SECRET_KEY does not start with "sk_live_" or "sk_test_" - may be invalid');
  }
}

/**
 * Log configuration summary (sanitized)
 */
function logConfigSummary() {
  console.log('\n' + '='.repeat(60));
  console.log('ENVIRONMENT CONFIGURATION SUMMARY');
  console.log('='.repeat(60));

  console.log('\nRequired Variables:');
  REQUIRED_ENV_VARS.forEach(varName => {
    const value = process.env[varName];
    const sanitized = value ? `${value.substring(0, 10)}...` : 'NOT SET';
    const status = value ? '✓' : '✗';
    console.log(`  ${status} ${varName.padEnd(25)} ${sanitized}`);
  });

  console.log('\nOptional Variables:');
  Object.entries(OPTIONAL_ENV_VARS).forEach(([varName, defaultValue]) => {
    const value = process.env[varName] || defaultValue;
    console.log(`  ✓ ${varName.padEnd(25)} ${value}`);
  });

  console.log('\n' + '='.repeat(60) + '\n');
}

/**
 * Main validation function - call this on app startup
 */
function validateConfig() {
  try {
    // Load .env file if it exists
    if (process.env.NODE_ENV !== 'production') {
      const envFile = process.env.NODE_ENV === 'test' ? '.env.test' : '.env';
      try {
        require('dotenv').config({ path: envFile });
      } catch (error) {
        console.warn(`Could not load ${envFile}: ${error.message}`);
      }
    }

    console.log(`🔧 Validating configuration for ${process.env.NODE_ENV || 'development'} environment...`);

    // Run all validations
    validateRequired();
    validateDatabaseUrl();
    validateAwsCredentials();
    validateApiKeys();

    // Log summary
    logConfigSummary();

    console.log('✅ Configuration validation passed!\n');
    return true;
  } catch (error) {
    console.error('\n❌ Configuration validation failed!');
    console.error(error.message);
    process.exit(1);
  }
}

/**
 * Get configuration value with fallback to default
 */
function get(varName) {
  return process.env[varName] || OPTIONAL_ENV_VARS[varName];
}

/**
 * Export configuration object
 */
module.exports = {
  validateConfig,
  get,

  // Direct access to common configs
  database: {
    url: () => process.env.DATABASE_URL,
  },
  aws: {
    accessKeyId: () => process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: () => process.env.AWS_SECRET_ACCESS_KEY,
    region: () => process.env.AWS_REGION || 'us-east-1',
  },
  stripe: {
    secretKey: () => process.env.STRIPE_SECRET_KEY,
  },
  anthropic: {
    apiKey: () => process.env.ANTHROPIC_API_KEY,
  },
  logging: {
    token: () => process.env.LOGFIRE_TOKEN,
    level: () => process.env.LOG_LEVEL || 'info',
  },
  server: {
    port: () => parseInt(process.env.PORT || '3000', 10),
    nodeEnv: () => process.env.NODE_ENV || 'development',
    isDevelopment: () => (process.env.NODE_ENV || 'development') === 'development',
    isProduction: () => process.env.NODE_ENV === 'production',
    isTest: () => process.env.NODE_ENV === 'test',
  },
  rateLimit: {
    windowMs: () => parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10),
    max: () => parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10),
  },
  security: {
    requestSizeLimit: () => process.env.REQUEST_SIZE_LIMIT || '10kb',
  }
};

/**
 * Enhanced Express Application
 * With proper environment configuration, validation, and security best practices
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

// Load and validate configuration
const config = require('./config');
config.validateConfig();

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: config.rateLimit.windowMs(),
  max: config.rateLimit.max(),
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Body parser with size limits
const requestSizeLimit = config.security.requestSizeLimit();
app.use(express.json({ limit: requestSizeLimit }));
app.use(express.urlencoded({ limit: requestSizeLimit, extended: true }));

// ============================================
// CUSTOM MIDDLEWARE
// ============================================

// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  if (config.server.isDevelopment()) {
    console.log(`[${timestamp}] ${req.method} ${req.path}`);
  }
  next();
});

// ============================================
// VALIDATION HELPERS
// ============================================

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      error: 'Invalid input',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res, next) => {
  try {
    res.json({
      success: true,
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: config.server.nodeEnv(),
      port: config.server.port(),
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Users endpoint with pagination
 */
app.get('/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const page = Math.max(parseInt(req.query.page) || 1, 1);

      // Sample data - in production, this would come from database
      // In real app, you would use: config.database.url()
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const startIndex = (page - 1) * limit;
      const users = allUsers.slice(startIndex, startIndex + limit);

      res.json({
        success: true,
        data: users,
        pagination: {
          page,
          limit,
          total: allUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * Configuration status endpoint (development only)
 */
if (config.server.isDevelopment()) {
  app.get('/config-status', (req, res, next) => {
    try {
      res.json({
        success: true,
        environment: config.server.nodeEnv(),
        port: config.server.port(),
        rateLimit: {
          windowMs: config.rateLimit.windowMs(),
          maxRequests: config.rateLimit.max(),
        },
        security: {
          requestSizeLimit: config.security.requestSizeLimit(),
        },
        aws: {
          region: config.aws.region(),
        },
        logging: {
          level: config.logging.level(),
        }
      });
    } catch (error) {
      next(error);
    }
  });
}

// ============================================
// 404 ERROR HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} does not exist`
  });
});

// ============================================
// GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  // Log error
  const errorLog = {
    timestamp: new Date().toISOString(),
    error: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
  };

  if (config.server.isDevelopment()) {
    errorLog.stack = err.stack;
  }

  console.error('ERROR:', errorLog);

  // Don't leak error details in production
  const statusCode = err.statusCode || err.status || 500;
  const message = config.server.isProduction() 
    ? 'Internal Server Error'
    : err.message;

  res.status(statusCode).json({
    success: false,
    error: 'Internal Server Error',
    message: message,
    ...(config.server.isDevelopment() && { stack: err.stack })
  });
});

// ============================================
// GRACEFUL SHUTDOWN HANDLING
// ============================================

process.on('unhandledRejection', (reason, promise) => {
  console.error('⚠️  Unhandled Rejection at:', promise, 'reason:', reason);
});

process.on('uncaughtException', (error) => {
  console.error('❌ Uncaught Exception:', error);
  if (config.server.isProduction()) {
    process.exit(1);
  }
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = config.server.port();
const server = app.listen(PORT, () => {
  console.log(`\n${'='.repeat(60)}`);
  console.log(`✓ Server running on port ${PORT}`);
  console.log(`✓ Environment: ${config.server.nodeEnv()}`);
  console.log(`✓ Timestamp: ${new Date().toISOString()}`);
  console.log(`${'='.repeat(60)}\n`);
});

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('\n🛑 SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('✓ Server closed');
    process.exit(0);
  });
});

module.exports = app;

