// Improved application with security best practices
// - Error handling
// - Input validation
// - Security headers
// - Rate limiting
// - Proper logging

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validationResult, query } = require('express-validator');
const app = express();

// ===== MIDDLEWARE =====

// Security headers
app.use(helmet());

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting - prevent brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks (optional)
    return req.path === '/health';
  }
});

app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// ===== ROUTES =====

/**
 * Health check endpoint
 * Public endpoint for monitoring
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Health check failed'
    });
  }
});

/**
 * Get users endpoint with validation
 * - Validates optional filter parameters
 * - Sanitizes output (no sensitive data exposed)
 * - Implements pagination
 */
app.get('/users',
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid input parameters',
          errors: errors.array().map(e => ({
            param: e.param,
            msg: e.msg
          }))
        });
      }

      // Parse and default query parameters
      const limit = Math.min(parseInt(req.query.limit || '10', 10), 100);
      const offset = Math.max(parseInt(req.query.offset || '0', 10), 0);

      // Mock database - in production, this would query a real database
      const allUsers = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
        { id: 3, name: 'Charlie' }
      ];

      // Filter by ID if provided
      let filtered = allUsers;
      if (req.query.id) {
        const requestedId = parseInt(req.query.id, 10);
        filtered = allUsers.filter(u => u.id === requestedId);
      }

      // Pagination
      const paginated = filtered.slice(offset, offset + limit);

      // Secure response with pagination metadata
      res.json({
        status: 'success',
        data: paginated,
        pagination: {
          limit,
          offset,
          total: filtered.length,
          hasMore: offset + limit < filtered.length
        }
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        status: 'error',
        message: 'Internal server error'
      });
    }
  }
);

// ===== ERROR HANDLING =====

/**
 * 404 handler - must be after all other routes
 */
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    path: req.path
  });
});

/**
 * Global error handler - must be last
 * Catches all errors and returns safe responses
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method
  });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const errorResponse = {
    status: 'error',
    message: isDevelopment ? err.message : 'Internal server error'
  };

  if (isDevelopment) {
    errorResponse.stack = err.stack;
  }

  res.status(err.statusCode || 500).json(errorResponse);
});

// ===== SERVER STARTUP =====

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Validate port
if (PORT < 1024 || PORT > 65535) {
  console.error('Invalid port number. Must be between 1024 and 65535');
  process.exit(1);
}

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

