## Before and After Example

### BEFORE (Vulnerable)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Problems:
// - No error handling
// - No input validation
// - Exposes sensitive data (emails)
// - No rate limiting
// - No logging
```

### AFTER (Secure)
```javascript
app.get('/users',
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  (req, res) => {
    try {
      // Input validation
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          status: 'error',
          errors: errors.array()
        });
      }

      // Parse parameters
      const limit = Math.min(parseInt(req.query.limit || '10', 10), 100);
      const offset = Math.max(parseInt(req.query.offset || '0', 10), 0);

      // Sanitized data (no emails)
      const allUsers = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' }
      ];

      // Pagination
      const paginated = allUsers.slice(offset, offset + limit);

      // Secure response
      res.json({
        status: 'success',
        data: paginated,
        pagination: {
          limit, offset, total: allUsers.length,
          hasMore: offset + limit < allUsers.length
        }
      });
    } catch (error) {
      console.error('Error:', error);
      res.status(500).json({
        status: 'error',
        message: 'Internal server error'
      });
    }
  }
);

// Improvements:
// ✅ Input validation with helpful error messages
// ✅ Try-catch error handling
// ✅ No sensitive data exposure
// ✅ Pagination support
// ✅ Consistent response format
// ✅ Rate limited at middleware level
// ✅ Logged via middleware
```

