// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Use helmet to set various HTTP headers
app.use(helmet());

// 2. Set CORS with restrictive options
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'HEAD', 'OPTIONS'],
  allowedHeaders: ['Content-Type'],
  maxAge: 86400, // 24 hours
}));

// 3. Request logging (use 'combined' in production for detailed logs)
app.use(morgan('dev'));

// 4. Body size limits to prevent DOS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 5. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use('/api/', limiter);

// ============ VALIDATION HELPERS ============

/**
 * Validate and sanitize user input
 * @param {string} input - Input to validate
 * @param {object} options - Validation options
 * @returns {string|null} - Sanitized input or null if invalid
 */
function validateInput(input, options = {}) {
  const {
    maxLength = 255,
    minLength = 0,
    pattern = null,
    required = false,
  } = options;

  // Check if required
  if (required && (!input || input.trim().length === 0)) {
    return null;
  }

  // Check type
  if (typeof input !== 'string') {
    return null;
  }

  // Check length
  if (input.length > maxLength || input.length < minLength) {
    return null;
  }

  // Check pattern if provided
  if (pattern && !pattern.test(input)) {
    return null;
  }

  // Trim whitespace
  return input.trim();
}

/**
 * Query parameter validator
 * @param {object} query - Query parameters object
 * @returns {object|null} - Validated query or null if invalid
 */
function validateQueryParams(query) {
  const validated = {};

  // Validate 'limit' parameter if present
  if (query.limit) {
    const limit = parseInt(query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return null;
    }
    validated.limit = limit;
  } else {
    validated.limit = 10;
  }

  // Validate 'offset' parameter if present
  if (query.offset) {
    const offset = parseInt(query.offset, 10);
    if (isNaN(offset) || offset < 0) {
      return null;
    }
    validated.offset = offset;
  } else {
    validated.offset = 0;
  }

  return validated;
}

// ============ ROUTES ============

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

/**
 * Get users with pagination support
 * Input validation: limit (1-100), offset (>= 0)
 */
app.get('/api/users', (req, res) => {
  try {
    // Validate query parameters
    const queryParams = validateQueryParams(req.query);
    if (!queryParams) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid query parameters. Limit must be 1-100, offset must be >= 0.',
      });
    }

    // Mock user database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(
      queryParams.offset,
      queryParams.offset + queryParams.limit
    );

    // Return with pagination metadata
    res.json({
      status: 'success',
      data: users,
      pagination: {
        limit: queryParams.limit,
        offset: queryParams.offset,
        total: allUsers.length,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

/**
 * Search users by name
 * Input validation: search query (required, 1-50 chars, alphanumeric + spaces)
 */
app.get('/api/users/search', (req, res) => {
  try {
    const { q } = req.query;

    // Validate search parameter
    const searchTerm = validateInput(q, {
      required: true,
      minLength: 1,
      maxLength: 50,
      pattern: /^[a-zA-Z0-9\s]*$/, // Alphanumeric and spaces only
    });

    if (!searchTerm) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid search query. Must be 1-50 alphanumeric characters.',
      });
    }

    // Mock search (in real app, would query database safely)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const results = allUsers.filter(user =>
      user.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    res.json({
      status: 'success',
      data: results,
      query: searchTerm,
    });
  } catch (error) {
    console.error('Error searching users:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

// ============ ERROR HANDLING ============

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found',
    path: req.path,
  });
});

/**
 * Global error handler (must be last)
 */
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't expose internal error details to client
  const status = error.status || 500;
  const message = status === 500 ? 'Internal server error' : error.message;

  res.status(status).json({
    status: 'error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack }),
  });
});

// ============ SERVER START ============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

