// Improved application with security and error handling best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { v4: uuidv4 } = require('uuid');
const app = express();

// ============================================================================
// ENVIRONMENT CONFIGURATION
// ============================================================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers
app.use(helmet());

// 2. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// 3. Request Parsing Middleware
app.use(express.json({
  limit: '10kb', // Limit request size to prevent large payload attacks
}));

app.use(express.urlencoded({
  limit: '10kb',
  extended: true,
}));

// ============================================================================
// REQUEST LOGGING & CONTEXT MIDDLEWARE
// ============================================================================

// Add unique request ID for tracing
app.use((req, res, next) => {
  req.id = uuidv4();
  req.timestamp = new Date();

  // Log incoming requests (in production, use proper logging library)
  if (NODE_ENV === 'development') {
    console.log(`[${req.id}] ${req.method} ${req.path}`);
  }

  next();
});

// ============================================================================
// INPUT VALIDATION HELPERS
// ============================================================================

const validateQueryParams = (query) => {
  const errors = [];

  // Example: Validate limit parameter if present
  if (query.limit) {
    const limit = parseInt(query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('Limit must be a number between 1 and 100');
    }
  }

  // Example: Validate offset parameter if present
  if (query.offset) {
    const offset = parseInt(query.offset, 10);
    if (isNaN(offset) || offset < 0) {
      errors.push('Offset must be a non-negative number');
    }
  }

  return errors;
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health Check Endpoint
 * Public endpoint for monitoring/load balancers
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: NODE_ENV,
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      requestId: req.id,
    });
  }
});

/**
 * Get Users Endpoint (with improvements)
 * 
 * IMPROVEMENTS:
 * - Input validation for query parameters
 * - Pagination support
 * - Data sanitization (no sensitive fields exposed)
 * - Error handling
 */
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const errors = validateQueryParams(req.query);
    if (errors.length > 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid query parameters',
        errors,
        requestId: req.id,
      });
    }

    const limit = Math.min(parseInt(req.query.limit || '10', 10), 100);
    const offset = parseInt(req.query.offset || '0', 10);

    // Mock users data (in production, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Sanitize response - remove sensitive fields
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      // NOTE: Consider if email should be exposed at all
      // Only include based on authentication/authorization
    }));

    res.json({
      status: 'success',
      data: sanitizedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length,
      },
      requestId: req.id,
    });
  } catch (error) {
    console.error(`[${req.id}] Error in /users:`, error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      requestId: req.id,
      // NOTE: Don't expose error details in production
      ...(NODE_ENV === 'development' && { error: error.message }),
    });
  }
});

/**
 * Example: POST endpoint with body validation
 */
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    const errors = [];

    if (!name || typeof name !== 'string') {
      errors.push('Name is required and must be a string');
    } else if (name.length < 2 || name.length > 100) {
      errors.push('Name must be between 2 and 100 characters');
    }

    // Simple email validation (use email-validator lib in production)
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email)) {
      errors.push('Valid email is required');
    }

    if (errors.length > 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors,
        requestId: req.id,
      });
    }

    // Simulate user creation (in production, save to database)
    const newUser = { id: 3, name, email };

    res.status(201).json({
      status: 'success',
      data: newUser,
      requestId: req.id,
    });
  } catch (error) {
    console.error(`[${req.id}] Error in POST /users:`, error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      requestId: req.id,
    });
  }
});

// ============================================================================
// 404 HANDLER
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    path: req.path,
    requestId: req.id,
  });
});

// ============================================================================
// GLOBAL ERROR HANDLER
// ============================================================================

app.use((err, req, res, next) => {
  console.error(`[${req?.id || 'unknown'}] Unhandled error:`, err);

  // Don't leak error details in production
  const message = NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({
    status: 'error',
    message,
    requestId: req?.id,
    ...(NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============================================================================
// UNHANDLED REJECTION HANDLER
// ============================================================================

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, send to error tracking service (e.g., Sentry)
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`[${NODE_ENV}] Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security & Best Practices Review: app.js

## Executive Summary
The current `app.js` lacks essential security measures, error handling, and input validation. This review identifies critical issues and provides actionable recommendations.

---

## 🔴 Critical Issues

### 1. **Missing Error Handling**
**Risk Level:** HIGH

**Current Problem:**
- No try-catch blocks around route handlers
- No global error handler
- Unhandled promise rejections will crash the server
- No error logging

**Recommendations:**
```javascript
// ✅ DO: Wrap route handlers in try-catch
app.get('/users', (req, res) => {
  try {
    // Route logic
  } catch (error) {
    console.error('Error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ✅ DO: Add global error handler
app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// ✅ DO: Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  // Send to error tracking service
});
```

---

### 2. **No Input Validation**
**Risk Level:** HIGH

**Current Problem:**
- Query parameters not validated
- No type checking
- No bounds checking
- Vulnerable to injection attacks

**Recommendations:**
```javascript
// ✅ DO: Validate all inputs
const validateQueryParams = (query) => {
  const errors = [];

  if (query.limit) {
    const limit = parseInt(query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('Invalid limit');
    }
  }

  return errors;
};

app.get('/users', (req, res) => {
  const errors = validateQueryParams(req.query);
  if (errors.length > 0) {
    return res.status(400).json({ errors });
  }
  // Process request
});
```

**Tools to Use:**
- `joi` - Schema validation
- `express-validator` - Express middleware validation
- `zod` - TypeScript-first schema validation

---

### 3. **Information Disclosure / Sensitive Data Exposure**
**Risk Level:** HIGH

**Current Problem:**
- `/users` endpoint exposes all user email addresses without authentication
- No access control
- Enables account enumeration attacks
- Violates privacy principles

**Recommendations:**
```javascript
// ❌ DON'T: Expose sensitive data
res.json([
  { id: 1, name: 'Alice', email: 'alice@example.com' }, // ← Sensitive!
]);

// ✅ DO: Sanitize response
const sanitized = users.map(u => ({ id: u.id, name: u.name }));
res.json(sanitized);

// ✅ DO: Require authentication
app.get('/users/me', authenticateUser, (req, res) => {
  res.json(req.user);
});
```

---

### 4. **No Security Headers**
**Risk Level:** MEDIUM

**Current Problem:**
- No protection against common attacks (XSS, Clickjacking, CSRF)
- No HSTS for HTTPS
- No Content Security Policy
- Vulnerable to various attack vectors

**Recommendations:**
```javascript
// ✅ DO: Use helmet.js for security headers
const helmet = require('helmet');
app.use(helmet());

// This enables:
// - X-Content-Type-Options: nosniff (prevents MIME sniffing)
// - X-Frame-Options: DENY (prevents clickjacking)
// - X-XSS-Protection: 1; mode=block
// - Strict-Transport-Security (HSTS)
// - Content Security Policy
// And more...
```

---

### 5. **No Rate Limiting**
**Risk Level:** MEDIUM

**Current Problem:**
- No protection against brute force attacks
- No DDoS mitigation
- Vulnerable to abuse

**Recommendations:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests',
});

app.use(limiter);

// Or apply to specific routes:
app.post('/login', limiter, (req, res) => {
  // Handle login
});
```

---

### 6. **Request Size Not Limited**
**Risk Level:** MEDIUM

**Current Problem:**
- No limit on request body size
- Vulnerable to payload bombs / memory exhaustion
- Uncontrolled resource consumption

**Recommendations:**
```javascript
// ✅ DO: Limit request size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ 
  limit: '10kb',
  extended: true,
}));
```

---

### 7. **Hard-coded Configuration**
**Risk Level:** LOW

**Current Problem:**
- Port is hard-coded
- No environment variable support
- Different configs needed for dev/staging/production

**Recommendations:**
```javascript
// ✅ DO: Use environment variables
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const API_KEY = process.env.API_KEY; // Required for production

if (NODE_ENV === 'production' && !API_KEY) {
  throw new Error('API_KEY is required in production');
}
```

---

### 8. **No Logging**
**Risk Level:** MEDIUM

**Current Problem:**
- No request logging for audit trail
- No error logging for debugging
- No monitoring capability
- Security incidents cannot be tracked

**Recommendations:**
```javascript
// ✅ DO: Add request logging
app.use((req, res, next) => {
  req.id = generateUUID();
  console.log(`[${req.id}] ${req.method} ${req.path}`);
  next();
});

// ✅ DO: Use production logging library
// - winston
// - bunyan
// - pino
// - morgan (HTTP logger)

const logger = require('winston');
logger.error(`[${req.id}] Error:`, error);
```

---

### 9. **No CORS Configuration**
**Risk Level:** MEDIUM (Context dependent)

**Current Problem:**
- No CORS configuration
- May be vulnerable to cross-origin attacks
- Or may have overly permissive CORS

**Recommendations:**
```javascript
const cors = require('cors');

// ✅ DO: Configure CORS appropriately
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
  maxAge: 3600,
}));

// Or restrict to specific routes:
app.get('/public', cors(), (req, res) => {
  res.json({ data: 'public' });
});
```

---

### 10. **No Request Timeout**
**Risk Level:** LOW-MEDIUM

**Current Problem:**
- No request timeout configured
- Slow loris attacks possible
- Resource exhaustion vulnerability

**Recommendations:**
```javascript
// ✅ DO: Set timeouts
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 seconds
  res.setTimeout(30000);
  next();
});

// Or at server level:
server.timeout = 30000;
server.keepAliveTimeout = 65000;
```

---

## 📋 Recommended Dependencies

Add these to `package.json`:

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^7.0.0",
    "express-validator": "^7.0.0",
    "uuid": "^9.0.0",
    "cors": "^2.8.5",
    "morgan": "^1.10.0"
  },
  "devDependencies": {
    "nodemon": "^3.0.0"
  }
}
```

---

## ✅ Security Checklist

- [ ] Error handling implemented (try-catch, global handler)
- [ ] Input validation on all endpoints
- [ ] Sensitive data not exposed in responses
- [ ] Helmet.js enabled for security headers
- [ ] Rate limiting implemented
- [ ] Request size limits configured
- [ ] Environment variables for configuration
- [ ] Request logging implemented
- [ ] CORS configured appropriately
- [ ] Request timeouts set
- [ ] Authentication/Authorization (if needed)
- [ ] SQL injection prevention (if using database)
- [ ] XSS prevention (if returning user input)
- [ ] CSRF protection (if needed)
- [ ] HTTPS only (in production)
- [ ] No secrets in code
- [ ] Dependencies regularly updated
- [ ] Security testing (SAST, dependency scanning)

---

## 🚀 Next Steps

1. **Install Security Middleware:**
   ```bash
   npm install helmet express-rate-limit express-validator uuid cors morgan
   ```

2. **Update Configuration:**
   - Create `.env` file with environment variables
   - Update `app.js` to use improved version

3. **Add Testing:**
   - Unit tests for validation functions
   - Integration tests for endpoints
   - Security tests (e.g., invalid inputs)

4. **Implement Logging:**
   - Choose logging library (Winston, Pino, etc.)
   - Configure structured logging
   - Set up log aggregation/analysis

5. **Production Hardening:**
   - Enable HTTPS/TLS
   - Set up WAF (Web Application Firewall)
   - Implement authentication/authorization
   - Add database query parameterization
   - Set up monitoring and alerting

---

## 📚 Additional Resources

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Node.js Security](https://nodejs.org/en/docs/guides/nodejs-security/)
- [CWE/SANS Top 25](https://cwe.mitre.org/top25/)

