/**
 * Secure Express Application with Best Practices
 * - Input validation
 * - Error handling
 * - Security headers
 * - Rate limiting
 * - Logging
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Security headers
app.use(helmet());

// Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// CORS configuration
app.use((req, res, next) => {
  const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

  if (allowedOrigins.includes(req.origin) || allowedOrigins.includes('*')) {
    res.header('Access-Control-Allow-Origin', req.origin);
  }

  res.header('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.header('Access-Control-Max-Age', '3600');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }

  next();
});

// ============================================
// 2. RATE LIMITING
// ============================================

// General rate limiter
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
  skip: (req) => {
    // Skip rate limiting for health checks in some cases (optional)
    return false;
  },
});

// Stricter limiter for sensitive endpoints
const sensitiveLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // More restrictive for sensitive operations
  message: 'Too many requests to this endpoint, please try again later.',
});

app.use(generalLimiter);

// ============================================
// 3. LOGGING
// ============================================

// Custom morgan format for production
const morganFormat = ':remote-addr - :method :url HTTP/:http-version :status :res[content-length] - :response-time ms';
app.use(morgan(morganFormat));

// ============================================
// 4. REQUEST VALIDATION MIDDLEWARE
// ============================================

// Middleware to check validation results
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      message: 'Validation failed',
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================
// 5. REQUEST TIMEOUT
// ============================================

app.use((req, res, next) => {
  req.setTimeout(30000); // 30 second timeout
  res.setTimeout(30000);
  next();
});

// ============================================
// 6. ROUTES
// ============================================

/**
 * Health check endpoint
 * No authentication required
 */
app.get('/health',
  query('verbose')
    .optional()
    .isBoolean()
    .withMessage('verbose must be a boolean'),
  handleValidationErrors,
  (req, res) => {
    try {
      const verbose = req.query.verbose === 'true';
      const response = {
        status: 'ok',
        timestamp: new Date().toISOString(),
      };

      if (verbose) {
        response.uptime = process.uptime();
        response.memory = process.memoryUsage();
      }

      res.json(response);
    } catch (error) {
      console.error('Health check error:', error);
      res.status(500).json({
        status: 'error',
        message: 'Health check failed',
      });
    }
  }
);

/**
 * Get users endpoint
 * In production, this should require authentication and have proper authorization
 */
app.get('/users',
  sensitiveLimiter,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('offset must be a non-negative integer')
    .toInt(),
  handleValidationErrors,
  (req, res) => {
    try {
      const limit = req.query.limit || 10;
      const offset = req.query.offset || 0;

      // Mock user data
      const users = [
        { id: 1, name: 'Alice' }, // Email removed (PII)
        { id: 2, name: 'Bob' },   // Email removed (PII)
      ];

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        status: 'success',
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: users.length,
        },
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        status: 'error',
        message: 'Failed to fetch users',
      });
    }
  }
);

/**
 * Test endpoint with POST request validation
 */
app.post('/users',
  sensitiveLimiter,
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email address')
    .normalizeEmail(),
  handleValidationErrors,
  (req, res) => {
    try {
      // Process user creation
      res.status(201).json({
        status: 'success',
        message: 'User created',
        data: {
          id: 3,
          name: req.body.name,
          email: req.body.email,
        },
      });
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({
        status: 'error',
        message: 'Failed to create user',
      });
    }
  }
);

// ============================================
// 7. 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    path: req.path,
    method: req.method,
  });
});

// ============================================
// 8. ERROR HANDLING MIDDLEWARE
// ============================================

// Global error handler (must be last)
app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  console.error('Error:', {
    status,
    message,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const responseMessage = isDevelopment ? message : 'Internal Server Error';

  res.status(status).json({
    status: 'error',
    message: responseMessage,
    ...(isDevelopment && { error: err.message }),
  });
});

// ============================================
// 9. SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to exit or alert monitoring systems
});

module.exports = app;

/**
 * Example Test Suite for Security Best Practices
 * Run with: npm test
 */

const request = require('supertest');
const app = require('./app-improved');

describe('Security & Validation Tests', () => {

  // ============================================
  // HEALTH ENDPOINT TESTS
  // ============================================

  describe('GET /health', () => {
    test('should return 200 with status ok', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.body).toHaveProperty('status', 'ok');
      expect(response.body).toHaveProperty('timestamp');
    });

    test('should accept verbose parameter', async () => {
      const response = await request(app)
        .get('/health?verbose=true')
        .expect(200);

      expect(response.body).toHaveProperty('uptime');
      expect(response.body).toHaveProperty('memory');
    });

    test('should reject invalid verbose parameter', async () => {
      const response = await request(app)
        .get('/health?verbose=invalid')
        .expect(400);

      expect(response.body).toHaveProperty('status', 'error');
      expect(response.body).toHaveProperty('errors');
    });
  });

  // ============================================
  // USERS ENDPOINT TESTS
  // ============================================

  describe('GET /users', () => {
    test('should return users list', async () => {
      const response = await request(app)
        .get('/users')
        .expect(200);

      expect(response.body).toHaveProperty('status', 'success');
      expect(Array.isArray(response.body.data)).toBe(true);
    });

    test('should validate limit parameter', async () => {
      const response = await request(app)
        .get('/users?limit=101')
        .expect(400);

      expect(response.body.message).toBe('Validation failed');
    });

    test('should reject negative offset', async () => {
