// Enhanced application with security best practices
// Includes error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security headers
app.use(helmet());

// CORS configuration (restrict as needed)
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// More restrictive rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many requests to this endpoint, please try again later.',
});

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================
// REQUEST VALIDATION HELPERS
// ============================================

/**
 * Validate query parameters
 * @param {Object} query - Query parameters to validate
 * @returns {Object} - Validation result with isValid and errors
 */
function validateQueryParams(query) {
  const errors = [];

  // Validate optional limit parameter
  if (query.limit) {
    if (!Number.isInteger(parseInt(query.limit)) || parseInt(query.limit) < 1 || parseInt(query.limit) > 100) {
      errors.push('limit must be a number between 1 and 100');
    }
  }

  // Validate optional offset parameter
  if (query.offset) {
    if (!Number.isInteger(parseInt(query.offset)) || parseInt(query.offset) < 0) {
      errors.push('offset must be a non-negative integer');
    }
  }

  return {
    isValid: errors.length === 0,
    errors
  };
}

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * Returns server status
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get users endpoint
 * Supports pagination via query parameters
 * Note: In production, add authentication and authorization checks
 */
app.get('/users', strictLimiter, (req, res) => {
  try {
    // Validate query parameters
    const validation = validateQueryParams(req.query);
    if (!validation.isValid) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: validation.errors
      });
    }

    // TODO: Add authentication middleware to verify user has permission
    // if (!req.user) {
    //   return res.status(401).json({ error: 'Unauthorized' });
    // }

    // Parse pagination parameters
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = parseInt(req.query.offset) || 0;

    // Mock user data - in production, fetch from database with parameterized queries
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(offset, offset + limit);

    // Return paginated results with metadata
    res.json({
      data: users,
      pagination: {
        limit,
        offset,
        total: allUsers.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Example POST endpoint for creating a user
 * Demonstrates input validation and sanitization
 */
app.post('/users', strictLimiter, (req, res) => {
  try {
    // Check request body exists
    if (!req.body || Object.keys(req.body).length === 0) {
      return res.status(400).json({ error: 'Request body is required' });
    }

    const { name, email } = req.body;

    // Validate required fields
    if (!name || !email) {
      return res.status(400).json({
        error: 'Validation failed',
        details: ['name and email are required fields']
      });
    }

    // Validate and sanitize input
    const errors = [];

    // Validate name
    if (typeof name !== 'string' || name.trim().length === 0) {
      errors.push('name must be a non-empty string');
    }
    if (name.length > 100) {
      errors.push('name must not exceed 100 characters');
    }

    // Validate email
    if (!validator.isEmail(email)) {
      errors.push('email must be a valid email address');
    }

    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors
      });
    }

    // TODO: Add authentication middleware
    // if (!req.user) {
    //   return res.status(401).json({ error: 'Unauthorized' });
    // }

    // Sanitize input
    const sanitizedName = validator.trim(validator.escape(name));
    const sanitizedEmail = validator.normalizeEmail(email);

    // TODO: Save to database with prepared statements
    // In production, use parameterized queries to prevent SQL injection

    res.status(201).json({
      id: 3,
      name: sanitizedName,
      email: sanitizedEmail
    });
  } catch (error) {
    console.error('Create user error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist`,
    path: req.path
  });
});

/**
 * Global error handling middleware
 * Should be the last middleware defined
 */
app.use((err, req, res, next) => {
  // Log error details (in production, use a proper logging service)
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method
  });

  // Don't expose internal error details to client
  const statusCode = err.status || err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: 'Internal Server Error',
    ...(isProduction ? {} : { details: err.message }) // Only expose details in development
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

