/**
 * Configuration Validation Module
 * 
 * Validates environment variables and provides type-safe config
 * Ensures application fails fast if configuration is invalid
 * 
 * Usage:
 *   const config = require('./config');
 *   app.listen(config.port, () => {
 *     console.log(`Server running on port ${config.port}`);
 *   });
 */

const fs = require('fs');
const path = require('path');

/**
 * Load environment-specific .env file
 * @param {string} env - Environment name (development, test, production, etc.)
 */
function loadEnvFile(env) {
  const envFile = env === 'production' 
    ? '.env.production' 
    : `.env.${env}`;

  const filePath = path.join(__dirname, envFile);

  if (fs.existsSync(filePath)) {
    require('dotenv').config({ path: filePath });
  }
}

/**
 * Validate port number
 * @param {string|number} port - Port number to validate
 * @returns {number} - Validated port number
 * @throws {Error} - If port is invalid
 */
function validatePort(port) {
  const portNum = parseInt(port, 10);

  if (isNaN(portNum)) {
    throw new Error(`PORT must be a number, got "${port}"`);
  }

  if (portNum < 1 || portNum > 65535) {
    throw new Error(`PORT must be between 1 and 65535, got ${portNum}`);
  }

  return portNum;
}

/**
 * Validate NODE_ENV
 * @param {string} env - Environment name
 * @returns {string} - Validated environment
 * @throws {Error} - If environment is invalid
 */
function validateNodeEnv(env) {
  const validEnvs = ['development', 'test', 'staging', 'production'];

  if (!env) {
    return 'development';
  }

  if (!validEnvs.includes(env)) {
    throw new Error(
      `NODE_ENV must be one of: ${validEnvs.join(', ')}, got "${env}"`
    );
  }

  return env;
}

/**
 * Validate CORS allowed origins
 * @param {string} origins - Comma-separated list of origins
 * @param {string} env - Environment name
 * @returns {string} - Validated origins
 * @throws {Error} - If origins are invalid in production
 */
function validateAllowedOrigins(origins, env) {
  if (!origins) {
    if (env === 'production') {
      throw new Error(
        'ALLOWED_ORIGINS is required in production environment'
      );
    }
    return 'http://localhost:3000';
  }

  // Validate each origin is a valid URL format
  const originList = origins.split(',').map(o => o.trim());

  for (const origin of originList) {
    // Basic URL validation
    if (!origin.startsWith('http://') && !origin.startsWith('https://')) {
      throw new Error(
        `Invalid origin "${origin}": must start with http:// or https://`
      );
    }

    // In production, warn if using http://
    if (env === 'production' && origin.startsWith('http://')) {
      console.warn(
        `⚠️  WARNING: Production origin uses http:// (should use https://): ${origin}`
      );
    }
  }

  return origins;
}

/**
 * Validate all configuration
 * @throws {Error} - If any validation fails
 * @returns {Object} - Validated configuration object
 */
function validateConfig() {
  const errors = [];

  try {
    // First, determine NODE_ENV
    const nodeEnv = validateNodeEnv(process.env.NODE_ENV);

    // Load environment-specific .env file
    if (process.env.NODE_ENV) {
      loadEnvFile(nodeEnv);
    }

    // Validate each configuration variable
    let port;
    try {
      port = validatePort(process.env.PORT || 3000);
    } catch (e) {
      errors.push(e.message);
    }

    let allowedOrigins;
    try {
      allowedOrigins = validateAllowedOrigins(process.env.ALLOWED_ORIGINS, nodeEnv);
    } catch (e) {
      errors.push(e.message);
    }

    // If there are validation errors, throw them all at once
    if (errors.length > 0) {
      const errorMessage = 'Configuration validation failed:\n' +
        errors.map(err => `  ❌ ${err}`).join('\n');
      throw new Error(errorMessage);
    }

    return {
      nodeEnv,
      port,
      allowedOrigins,
      isProduction: nodeEnv === 'production',
      isDevelopment: nodeEnv === 'development',
      isTest: nodeEnv === 'test',
      isStaging: nodeEnv === 'staging'
    };

  } catch (error) {
    console.error('Configuration Error:\n', error.message);
    process.exit(1);
  }
}

/**
 * Get validated configuration object
 * Caches the result to avoid re-validation
 */
let configCache = null;

function getConfig() {
  if (!configCache) {
    configCache = validateConfig();
  }
  return configCache;
}

/**
 * Print configuration to console (safe output, hides secrets)
 */
function printConfig() {
  const config = getConfig();
  console.log('\n' + '='.repeat(50));
  console.log('Application Configuration');
  console.log('='.repeat(50));
  console.log(`Environment:    ${config.nodeEnv.toUpperCase()}`);
  console.log(`Port:           ${config.port}`);
  console.log(`CORS Origins:   ${config.allowedOrigins}`);
  console.log('='.repeat(50) + '\n');
}

module.exports = {
  getConfig,
  printConfig,
  // For testing
  validateConfig: () => validateConfig(),
  validatePort,
  validateNodeEnv,
  validateAllowedOrigins,
  loadEnvFile
};

