/**
 * Simple logger module
 * In production, consider using Winston, Pino, or Bunyan
 */

const fs = require('fs');
const path = require('path');

const LOG_DIR = 'logs';
const LOG_FILE = path.join(LOG_DIR, 'app.log');

// Ensure logs directory exists
if (!fs.existsSync(LOG_DIR)) {
  fs.mkdirSync(LOG_DIR);
}

const logLevels = {
  ERROR: 'ERROR',
  WARN: 'WARN',
  INFO: 'INFO',
  DEBUG: 'DEBUG',
};

const formatLog = (level, message, metadata) => {
  const timestamp = new Date().toISOString();
  const meta = metadata ? JSON.stringify(metadata) : '';
  return `${timestamp} [${level}] ${message} ${meta}`.trim();
};

const writeLog = (level, message, metadata) => {
  const logMessage = formatLog(level, message, metadata);
  console.log(logMessage);

  // Also write to file
  try {
    fs.appendFileSync(LOG_FILE, logMessage + '\n');
  } catch (error) {
    console.error('Failed to write to log file:', error.message);
  }
};

module.exports = {
  error: (message, metadata) => writeLog(logLevels.ERROR, message, metadata),
  warn: (message, metadata) => writeLog(logLevels.WARN, message, metadata),
  info: (message, metadata) => writeLog(logLevels.INFO, message, metadata),
  debug: (message, metadata) => {
    if (process.env.NODE_ENV === 'development') {
      writeLog(logLevels.DEBUG, message, metadata);
    }
  },
};

