/**
 * Configuration module
 * Loads and validates environment variables
 */

const logger = require('./logger');

// Define configuration schema
const config = {
  // Server
  port: parseInt(process.env.PORT || '3000', 10),
  nodeEnv: process.env.NODE_ENV || 'development',
  isDevelopment: (process.env.NODE_ENV || 'development') === 'development',
  isProduction: process.env.NODE_ENV === 'production',

  // Security & CORS
  allowedOrigins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000')
    .split(',')
    .map(origin => origin.trim()),

  // Logging
  logLevel: process.env.LOG_LEVEL || 'info',

  // Rate Limiting
  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10), // 15 minutes
    maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10),
  },

  // Database (if implemented)
  database: {
    url: process.env.DATABASE_URL || null,
    poolSize: parseInt(process.env.DATABASE_POOL_SIZE || '10', 10),
  },

  // AWS (if implemented)
  aws: {
    region: process.env.AWS_REGION || 'us-east-1',
    accessKeyId: process.env.AWS_ACCESS_KEY_ID || null,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || null,
  },

  // External Services
  services: {
    anthropic: {
      apiKey: process.env.ANTHROPIC_API_KEY || null,
    },
    stripe: {
      secretKey: process.env.STRIPE_SECRET_KEY || null,
    },
    logfire: {
      token: process.env.LOGFIRE_TOKEN || null,
    },
  },
};

/**
 * Validate configuration on startup
 */
const validateConfig = () => {
  const errors = [];

  // Validate port
  if (!Number.isInteger(config.port) || config.port < 1 || config.port > 65535) {
    errors.push('PORT must be a valid port number (1-65535)');
  }

  // Validate NODE_ENV
  if (!['development', 'production', 'test'].includes(config.nodeEnv)) {
    errors.push("NODE_ENV must be 'development', 'production', or 'test'");
  }

  // Validate ALLOWED_ORIGINS format
  if (!Array.isArray(config.allowedOrigins) || config.allowedOrigins.length === 0) {
    errors.push('ALLOWED_ORIGINS must be a non-empty comma-separated list');
  }

  // Validate rate limit settings
  if (!Number.isInteger(config.rateLimit.windowMs) || config.rateLimit.windowMs < 1000) {
    errors.push('RATE_LIMIT_WINDOW_MS must be an integer >= 1000');
  }

  if (!Number.isInteger(config.rateLimit.maxRequests) || config.rateLimit.maxRequests < 1) {
    errors.push('RATE_LIMIT_MAX_REQUESTS must be a positive integer');
  }

  // Production-specific validation
  if (config.isProduction) {
    // In production, ensure we're not using defaults
    if (process.env.PORT === undefined) {
      logger.warn('PORT not set in production, using default 3000');
    }
  }

  if (errors.length > 0) {
    logger.error('Configuration validation failed:', { errors });
    errors.forEach(error => logger.error(`  - ${error}`));
    process.exit(1);
  }

  logger.info('Configuration validated successfully', {
    port: config.port,
    environment: config.nodeEnv,
    allowedOrigins: config.allowedOrigins.join(', '),
  });
};

module.exports = {
  config,
  validateConfig,
};

