    }
  }
);

// ============ ERROR HANDLING ============

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  logger.warn('Route not found', { method: req.method, path: req.path });
  res.status(404).json({
    error: 'Not found',
    path: req.path,
  });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
  });

  const errorDetails = config.isDevelopment ? { message: err.message } : {};

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(config.isDevelopment && errorDetails),
  });
});

// ============ SERVER STARTUP ============

// Only start server if this is the main module (not imported for testing)
if (require.main === module) {
  const server = app.listen(config.port, () => {
    logger.info(`Server running on port ${config.port}`, {
      environment: config.nodeEnv,
      allowedOrigins: config.allowedOrigins.join(', '),
    });
  });

  // Graceful shutdown
  const gracefulShutdown = () => {
    logger.info('Graceful shutdown initiated');
    server.close(() => {
      logger.info('HTTP server closed');
      process.exit(0);
    });

    // Force exit after 10 seconds
    setTimeout(() => {
      logger.error('Forced shutdown: connections did not close in time');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', gracefulShutdown);
  process.on('SIGINT', gracefulShutdown);
}

module.exports = app;

