// Enhanced Express application with security best practices
// Includes: error handling, input validation, security headers, logging, and rate limiting

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============= ENVIRONMENT CONFIGURATION =============
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============= LOGGING =============
app.use(morgan('combined'));

// ============= SECURITY MIDDLEWARE =============
// Add security headers
app.use(helmet());

// CORS configuration - restrict origins in production
const corsOptions = {
  origin: process.env.CORS_ORIGIN || 'localhost',
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// Body size limits to prevent large payload attacks
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Rate limiting - prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// ============= ROUTES =============

/**
 * Health check endpoint
 * Requires: Nothing
 * Returns: Status and timestamp
 */
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint with input validation
 * Query params: limit (optional), offset (optional), filter (optional)
 */
app.get('/users',
  // Input validation middleware
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  query('filter')
    .optional()
    .trim()
    .matches(/^[a-zA-Z0-9\s-]*$/)
    .withMessage('Filter contains invalid characters'),
  (req, res, next) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          success: false,
          errors: errors.array().map(err => ({
            field: err.param,
            message: err.msg
          }))
        });
      }

      // Extract and sanitize query parameters
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = parseInt(req.query.offset) || 0;
      const filter = req.query.filter ? req.query.filter.toLowerCase().trim() : null;

      // Mock user data
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Apply filter if provided
      let filteredUsers = allUsers;
      if (filter) {
        filteredUsers = allUsers.filter(user =>
          user.name.toLowerCase().includes(filter) ||
          user.email.toLowerCase().includes(filter)
        );
      }

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      // Success response
      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          total: filteredUsers.length,
          limit,
          offset,
          returned: paginatedUsers.length
        }
      });

    } catch (error) {
      next(error);
    }
  }
);

/**
 * Example POST endpoint with input validation
 */
app.post('/users',
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 1, max: 100 }).withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]*$/).withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),
  (req, res, next) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          success: false,
          errors: errors.array().map(err => ({
            field: err.param,
            message: err.msg
          }))
        });
      }

      const { name, email } = req.body;

      // Create user (mock)
      const newUser = {
        id: Math.random(),
        name,
        email
      };

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: newUser
      });

    } catch (error) {
      next(error);
    }
  }
);

// ============= 404 HANDLER =============
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Not Found',
    message: 'The requested endpoint does not exist',
    path: req.path
  });
});

// ============= GLOBAL ERROR HANDLER =============
app.use((err, req, res, next) => {
  // Log error details (don't expose sensitive info to client)
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method
  });

  // Determine status code
  const status = err.status || err.statusCode || 500;
  const isDevelopment = NODE_ENV === 'development';

  // Send response
  res.status(status).json({
    success: false,
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============= SERVER STARTUP =============
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV} environment)`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

