      const res = await request(app)
        .get('/users')
        .expect(200);

      expect(res.body).toHaveProperty('success', true);
      expect(res.body).toHaveProperty('data');
      expect(res.body).toHaveProperty('pagination');
      expect(Array.isArray(res.body.data)).toBe(true);
    });

    it('should validate limit parameter - max 100', async () => {
      const res = await request(app)
        .get('/users?limit=50')
        .expect(200);

      expect(res.body.pagination.limit).toBe(50);
    });

    it('should reject invalid limit - too high', async () => {
      const res = await request(app)
        .get('/users?limit=999')
        .expect(400);

      expect(res.body.success).toBe(false);
      expect(res.body.errors).toBeDefined();
    });

    it('should reject invalid limit - negative', async () => {
      const res = await request(app)
        .get('/users?limit=-5')
        .expect(400);

      expect(res.body.success).toBe(false);
    });

    it('should reject invalid limit - non-numeric', async () => {
      const res = await request(app)
        .get('/users?limit=abc')
        .expect(400);

      expect(res.body.success).toBe(false);
    });

    it('should validate offset parameter', async () => {
      const res = await request(app)
        .get('/users?offset=5')
        .expect(200);

      expect(res.body.pagination.offset).toBe(5);
    });

    it('should reject negative offset', async () => {
      const res = await request(app)
        .get('/users?offset=-1')
        .expect(400);

      expect(res.body.success).toBe(false);
    });

    it('should sanitize filter parameter', async () => {
      const res = await request(app)
