  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// Parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// REQUEST LOGGING MIDDLEWARE
// ============================================================================

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
    });
  });
  next();
});

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
    });
  }
});

/**
 * Get users endpoint
 * GET /users
 * Query parameters:
 *   - limit (optional): number of results to return (1-100)
 *   - offset (optional): pagination offset (0+)
 */
app.get('/users', (req, res) => {
  try {
    // Input validation
    let limit = 10; // default
    let offset = 0; // default

    if (req.query.limit) {
      // Validate limit is a positive integer
      if (!validator.isInt(req.query.limit, { min: 1, max: 100 })) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be an integer between 1 and 100.',
        });
      }
      limit = parseInt(req.query.limit, 10);
    }

    if (req.query.offset) {
      // Validate offset is a non-negative integer
      if (!validator.isInt(req.query.offset, { min: 0 })) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative integer.',
        });
      }
      offset = parseInt(req.query.offset, 10);
    }

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length,
      },
    });
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({
      error: 'Internal server error',
    });
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  console.error('Unhandled error:', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
  });

  const status = err.status || err.statusCode || 500;

  res.status(status).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js - Recommendations

## Executive Summary
The current application lacks essential security controls. This document outlines critical vulnerabilities and recommended improvements.

---

## 🔴 Critical Issues

### 1. No Input Validation
**Current Issue:**
```javascript
app.get('/users', (req, res) => {
  // Query parameters completely unvalidated
  res.json([...]);
});
```

**Risks:**
- Injection attacks through query parameters
- Unexpected application behavior
- DoS through malformed inputs
- Integer overflow attacks

**Solution:**
```javascript
const validator = require('validator');

app.get('/users', (req, res) => {
  if (req.query.limit) {
    if (!validator.isInt(req.query.limit, { min: 1, max: 100 })) {
      return res.status(400).json({ error: 'Invalid limit' });
    }
  }
  // Process validated input
});
```

---

### 2. Missing Security Headers
**Current Issue:** No security headers set

**Risks:**
- XSS (Cross-Site Scripting)
- Clickjacking attacks
- MIME type sniffing
- Unencrypted connections

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet());
```

This adds:
- `X-Frame-Options: DENY` - Prevents clickjacking
- `X-Content-Type-Options: nosniff` - Prevents MIME sniffing
- `Strict-Transport-Security` - Enforces HTTPS
- `Content-Security-Policy` - Prevents XSS
- And more...

---

### 3. No Error Handling
**Current Issue:** No try-catch or error middleware

**Risks:**
- Unhandled exceptions crash the server
- Stack traces exposed to users
- Debugging becomes difficult
- Security information disclosure

**Solution:**
```javascript
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok' });
  } catch (error) {
    console.error('Error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';
  console.error(err);
  res.status(500).json({
    error: isDev ? err.message : 'Internal server error'
  });
});
```

---

### 4. No Rate Limiting
**Current Issue:** Endpoints unprotected against abuse

**Risks:**
- Denial of Service (DoS) attacks
- Resource exhaustion
- API abuse
- Bot attacks

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP
  message: 'Too many requests, try again later'
});

app.use(limiter);
```

---

### 5. Unrestricted Body Size
**Current Issue:** No body size limits

**Risks:**
- Memory exhaustion attacks
- Buffer overflow attacks
- DoS through large payloads

**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 6. Sensitive Data Exposure
**Current Issue:** User data returned without authentication/authorization

```javascript
app.get('/users', (req, res) => {
  res.json([...all users...]); // No access control!
});
```

**Risks:**
- Information disclosure
- Privacy violations
- GDPR/data protection violations
- Unauthorized data access

**Solution:**
```javascript
// Add authentication middleware
app.use(authenticate);

// Add authorization checks
app.get('/users', authorize('read:users'), (req, res) => {
  res.json([...]);
});
```

---

### 7. No Request/Error Logging
**Current Issue:** No logging for security monitoring

**Risks:**
- Can't detect attacks
- Difficult to investigate incidents
- No audit trail
- Compliance violations

**Solution:**
```javascript
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: Date.now() - start,
      ip: req.ip,
    });
  });
  next();
});
```

---

## 🟡 Important Improvements

### 8. Missing HTTP Status Codes
**Issue:** Inconsistent status codes

**Solution:**
```javascript
// Always use appropriate status codes
app.get('/users', (req, res) => {
  // ... validation ...
  if (validationError) {
    return res.status(400).json({ error: '...' }); // 400 Bad Request
  }
