// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const validator = require('validator');
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Set security HTTP headers
app.use(helmet());

// 2. CORS - Restrict to trusted origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'HEAD', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};
app.use(cors(corsOptions));

// 3. Body parser with size limits
app.use(express.json({ limit: '1kb' }));
app.use(express.urlencoded({ limit: '1kb', extended: false }));

// 4. Rate limiting - Prevent brute force and DOS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  keyGenerator: (req, res) => {
    // Use IP address as the key
    return req.ip;
  },
});
app.use(limiter);

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

// Middleware to sanitize query parameters
const sanitizeQuery = (req, res, next) => {
  try {
    for (let key in req.query) {
      // Validate query params are strings and not excessively long
      if (typeof req.query[key] !== 'string' || req.query[key].length > 255) {
        return res.status(400).json({
          error: 'Invalid query parameters',
          message: 'Query parameters must be strings with max 255 characters',
        });
      }
      // Sanitize the value
      req.query[key] = validator.trim(req.query[key]);
    }
    next();
  } catch (err) {
    return res.status(400).json({ error: 'Invalid request format' });
  }
};
app.use(sanitizeQuery);

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (err) {
    console.error('Health check error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get users endpoint
 * GET /users
 * Query params: limit (optional, max 100), offset (optional)
 */
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    let limit = 10; // Default limit
    let offset = 0; // Default offset

    // Validate and parse limit parameter
    if (req.query.limit) {
      const parsedLimit = parseInt(req.query.limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter',
          message: 'Limit must be a number between 1 and 100',
        });
      }
      limit = parsedLimit;
    }

    // Validate and parse offset parameter
    if (req.query.offset) {
      const parsedOffset = parseInt(req.query.offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter',
          message: 'Offset must be a non-negative number',
        });
      }
      offset = parsedOffset;
    }

    // Mock database - In production, this would query a database with proper ORM
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Return with metadata (though should add auth checks in production)
    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length,
      },
    });
  } catch (err) {
    console.error('Get users error:', err);
    res.status(500).json({
      error: 'Internal server error',
      // Note: In production, don't expose stack traces; use correlation IDs instead
    });
  }
});

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested endpoint does not exist',
  });
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  const statusCode = err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: 'Internal Server Error',
    // Only expose message in development
    ...(isProduction ? {} : { message: err.message }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js

## Executive Summary
The original app.js has **critical security gaps** that should be addressed before production deployment. Below is a detailed analysis with recommendations.

---

## Critical Issues Found

### 1. 🔴 **CRITICAL: Missing Authentication & Authorization**
**Severity**: CRITICAL  
**Issue**: User endpoint exposes all user data without authentication checks  
**Risk**: Information disclosure, privacy violation  
**Fix**:
```javascript
// Add authentication middleware
const requireAuth = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Verify token (JWT, OAuth, etc.)
  next();
};

app.get('/users', requireAuth, (req, res) => {
  // Only return authorized user's data
  // ...
});
```

---

### 2. 🔴 **CRITICAL: No Input Validation**
**Severity**: CRITICAL  
**Issue**: Query parameters not validated or sanitized  
**Risk**: Injection attacks, application crashes  
**Example Attack**:
```
GET /users?limit=99999999999999999999&offset=malicious
GET /users?limit=<script>alert(1)</script>
```
**Fix**: Use validator library and parse/validate all inputs
```javascript
const validator = require('validator');

if (req.query.limit) {
  const parsed = parseInt(req.query.limit, 10);
  if (isNaN(parsed) || parsed < 1 || parsed > 100) {
    return res.status(400).json({ error: 'Invalid limit' });
  }
}
```

---

### 3. 🔴 **CRITICAL: No Error Handling**
**Severity**: CRITICAL  
**Issue**: Unhandled exceptions will crash the server  
**Risk**: DOS attacks, information disclosure via stack traces  
**Fix**: Wrap all routes in try-catch and add global error handler
```javascript
app.get('/users', (req, res) => {
  try {
    // route logic
  } catch (err) {
    console.error('Error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  res.status(500).json({ error: 'Internal server error' });
});
```

---

### 4. 🟠 **HIGH: Missing Security Headers**
**Severity**: HIGH  
**Issue**: No protection against XSS, clickjacking, MIME-sniffing  
**Risk**: Various web-based attacks  
**Fix**:
```javascript
const helmet = require('helmet');
app.use(helmet());
```

---

### 5. 🟠 **HIGH: No Rate Limiting**
**Severity**: HIGH  
**Issue**: No protection against brute force or DOS attacks  
**Risk**: Resource exhaustion, service unavailability  
**Fix**:
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);
```

---

### 6. 🟠 **HIGH: No CORS Configuration**
**Severity**: HIGH  
**Issue**: CORS not explicitly configured (uses defaults)  
**Risk**: Cross-origin attacks, unauthorized API access  
**Fix**:
```javascript
const cors = require('cors');
app.use(cors({
  origin: ['https://trusted-domain.com'],
  credentials: true,
  methods: ['GET', 'HEAD']
}));
```

---

### 7. 🟡 **MEDIUM: No Request Size Limits**
**Severity**: MEDIUM  
**Issue**: Unbounded request payloads  
**Risk**: DOS via large payloads  
**Fix**:
```javascript
app.use(express.json({ limit: '1kb' }));
app.use(express.urlencoded({ limit: '1kb' }));
```

---

### 8. 🟡 **MEDIUM: Information Disclosure**
**Severity**: MEDIUM  
**Issue**: Stack traces exposed in error responses  
**Risk**: Attackers learn system details  
**Fix**:
```javascript
// Only expose stack traces in development
res.json({
  error: 'Internal Server Error',
  ...(isProduction ? {} : { stack: err.stack })
});
```

---

### 9. 🟡 **MEDIUM: No Logging/Audit Trail**
**Severity**: MEDIUM  
**Issue**: No request logging for debugging/forensics  
**Risk**: Unable to detect or investigate attacks  
**Fix**:
```javascript
const morgan = require('morgan');
app.use(morgan('combined'));
```

---

### 10. 🟡 **MEDIUM: No 404 Handler**
**Severity**: MEDIUM  
**Issue**: Unmatched routes don't have explicit handlers  
**Risk**: Inconsistent error responses  
**Fix**:
```javascript
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

