// Simple application with enhanced error handling and security
// Security improvements: input validation, error handling, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ============================================
// MIDDLEWARE - Security & Parsing
// ============================================

// Use helmet to set HTTP security headers
app.use(helmet());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});
app.use(limiter);

// Parse JSON with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next();
});

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * GET /health
 * Returns server status with timestamp
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    handleError(res, error, 'Health check failed');
  }
});

/**
 * Get users endpoint
 * GET /users
 * Optional query params: limit (1-100), offset (>=0)
 * Returns list of users with pagination support
 */
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = Math.max(parseInt(req.query.offset) || 0, 0);

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.status(200).json({
      success: true,
      data: paginatedUsers,
      pagination: {
        total: allUsers.length,
        limit,
        offset,
      },
    });
  } catch (error) {
    handleError(res, error, 'Failed to retrieve users');
  }
});

// ============================================
// MIDDLEWARE - Input Validation
// ============================================

/**
 * Validate query parameters
 * Prevents injection attacks and invalid input
 */
function validateQueryParams(req, res, next) {
  try {
    const { limit, offset } = req.query;

    // Validate limit parameter
    if (limit !== undefined) {
      if (!/^\d+$/.test(limit)) {
        return res.status(400).json({
          success: false,
          error: 'Invalid limit parameter. Must be a positive integer.',
        });
      }
      const limitNum = parseInt(limit);
      if (limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          success: false,
          error: 'Limit parameter must be between 1 and 100.',
        });
      }
    }

    // Validate offset parameter
    if (offset !== undefined) {
      if (!/^\d+$/.test(offset)) {
        return res.status(400).json({
          success: false,
          error: 'Invalid offset parameter. Must be a non-negative integer.',
        });
      }
      const offsetNum = parseInt(offset);
      if (offsetNum < 0) {
        return res.status(400).json({
          success: false,
          error: 'Offset parameter cannot be negative.',
        });
      }
    }

    next();
  } catch (error) {
    handleError(res, error, 'Query validation error');
  }
}

// ============================================
// ERROR HANDLING
// ============================================

/**
 * Centralized error handler
 * Prevents stack traces from leaking to clients
 */
function handleError(res, error, defaultMessage = 'An error occurred') {
  console.error(`Error: ${defaultMessage}`, error);

  // Don't expose stack traces or internal error details to clients
  res.status(500).json({
    success: false,
    error: defaultMessage,
    // In production, you might want to remove the message field entirely
    // and use error codes instead for client-side handling
  });
}

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Route not found',
    path: req.path,
  });
});

/**
 * Global error handler
 * Must be defined last
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    success: false,
    error: message,
  });
});

// ============================================
// SERVER START
// ============================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

