// Validates and reports on environment variable configuration

const envSchema = require('./env.schema');

/**
 * Validate environment variables against schema
 * @returns {boolean} - True if validation passes
 * @throws {Error} - If required variables are missing or invalid
 */
function validateEnv() {
  const errors = [];
  const warnings = [];
  const configured = [];

  console.log('\n📋 Environment Configuration Check:');
  console.log('=====================================\n');

  Object.entries(envSchema).forEach(([key, config]) => {
    const value = process.env[key];
    const isDefined = typeof value !== 'undefined' && value !== '';

    // ========== Check Required Variables ==========
    if (config.required && !isDefined) {
      errors.push({
        level: 'ERROR',
        message: `Missing required environment variable: ${key}`,
        hint: config.description
      });
      return;
    }

    // ========== Check Enum Values ==========
    if (isDefined && config.enum && !config.enum.includes(value)) {
      errors.push({
        level: 'ERROR',
        message: `Invalid ${key}="${value}"`,
        hint: `Must be one of: ${config.enum.join(', ')}`
      });
      return;
    }

    // ========== Check Type ==========
    if (isDefined && config.type === 'number') {
      const parsed = parseInt(value, 10);
      if (isNaN(parsed)) {
        errors.push({
          level: 'ERROR',
          message: `${key} must be a number, got: "${value}"`,
          hint: `Example: ${config.default || '3000'}`
        });
        return;
      }
    }

    // ========== Warn About Missing Optional Sensitive Variables ==========
    if (!isDefined && !config.required && config.sensitive) {
      const defaultMsg = config.default ? ` (will use default: ${config.default})` : '';
      warnings.push({
        level: 'WARN',
        message: `Optional sensitive variable not configured: ${key}${defaultMsg}`,
        hint: config.description
      });
      return;
    }

    // ========== Track Configured Variables ==========
    if (isDefined) {
      const displayValue = config.sensitive ? '***REDACTED***' : value;
      configured.push({
        name: key,
        value: displayValue,
        source: 'environment'
      });
    } else if (config.default) {
      configured.push({
        name: key,
        value: String(config.default),
        source: 'default'
      });
    }
  });

  // ========== Print Results ==========

  if (configured.length > 0) {
    console.log('✅ Configured Variables:');
    configured.forEach(item => {
      const source = item.source === 'default' ? ' [DEFAULT]' : '';
      console.log(`   ${item.name}: ${item.value}${source}`);
    });
    console.log();
  }

  if (warnings.length > 0) {
    console.log('⚠️  Warnings:');
    warnings.forEach(warn => {
      console.log(`   ${warn.message}`);
      if (warn.hint) console.log(`      └─ ${warn.hint}`);
    });
    console.log();
  }

  if (errors.length > 0) {
    console.error('❌ Configuration Errors:');
    errors.forEach(err => {
      console.error(`   ${err.message}`);
      if (err.hint) console.error(`      └─ ${err.hint}`);
    });
    console.log();
    console.error('Cannot start application. Fix errors above.\n');
    process.exit(1);
  }

  console.log('✨ All environment variables validated successfully!\n');
  return true;
}

/**
 * Get environment variable with validation
 * @param {string} key - Variable name
 * @param {*} defaultValue - Default value if not set
 * @returns {*} - Variable value or default
 */
function getEnv(key, defaultValue) {
  const schema = envSchema[key];
  const value = process.env[key];

  if (typeof value !== 'undefined' && value !== '') {
    if (schema && schema.type === 'number') {
      return parseInt(value, 10);
    }
    return value;
  }

  return defaultValue !== undefined ? defaultValue : schema?.default;
}

/**
 * Check if a variable is set
 * @param {string} key - Variable name
 * @returns {boolean}
 */
function hasEnv(key) {
  const value = process.env[key];
  return typeof value !== 'undefined' && value !== '';
}

/**
 * Print environment configuration schema
 */
function printSchema() {
  console.log('\n📖 Environment Variables Schema:');
  console.log('=================================\n');

  Object.entries(envSchema).forEach(([key, config]) => {
    const required = config.required ? '(REQUIRED)' : '(optional)';
    const defaultStr = config.default ? ` - default: "${config.default}"` : '';
    const sensitive = config.sensitive ? ' [SENSITIVE]' : '';
    const enumStr = config.enum ? ` - values: ${config.enum.join('|')}` : '';

    console.log(`${key} ${required}${sensitive}`);
    console.log(`   Type: ${config.type}${defaultStr}${enumStr}`);
    console.log(`   ${config.description}`);
    if (config.example) console.log(`   Example: ${config.example}`);
    console.log();
  });
}

module.exports = {
  validateEnv,
  getEnv,
  hasEnv,
  printSchema,
  schema: envSchema
};

