## Security Review of app.js

### Current Issues & Recommendations

#### **1. ❌ Missing Input Validation & Sanitization**
The `/users` endpoint doesn't validate any query parameters. If query parameters are added in the future without validation, this could lead to vulnerabilities.

**Recommendation:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  query('id').optional().isInt().toInt(),
  query('name').optional().trim().escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // ... rest of handler
  }
);
```

---

#### **2. ❌ No Error Handling Middleware**
There's no centralized error handling. Unhandled errors could expose sensitive information.

**Recommendation - Add global error handler:**
```javascript
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message
  });
});
```

---

#### **3. ⚠️ Sensitive Data Exposure**
Email addresses and user data are returned without any protection or access control.

**Recommendations:**
- Implement authentication/authorization
- Consider role-based access control (RBAC)
- Implement rate limiting to prevent data enumeration attacks

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(limiter);
```

---

#### **4. ❌ Missing Security Headers**
No security headers are configured.

**Recommendation:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds various HTTP headers for security
```

---

#### **5. ❌ No CORS Configuration**
Missing CORS policy could allow unauthorized cross-origin requests.

**Recommendation:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST'],
  maxAge: 3600
};

app.use(cors(corsOptions));
```

---

#### **6. ❌ Missing Request Logging**
No logging for security auditing.

**Recommendation:**
```javascript
const morgan = require('morgan');
app.use(morgan('combined')); // or ':remote-addr :method :url :status'
```

---

#### **7. ⚠️ No 404 Handler**
Unhandled routes could leak information.

**Recommendation:**
```javascript
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

### **Improved Version of app.js**

Here's a more secure version:

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// Security Middleware
app.use(helmet());
app.use(morgan('combined'));
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000',
  credentials: true
}));

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests'
});
app.use('/api/', limiter);

app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

app.get('/users',
  query('id').optional().isInt().toInt(),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      if (req.query.id) {
        const user = users.find(u => u.id === req.query.id);
        if (!user) {
          return res.status(404).json({ error: 'User not found' });
        }
        return res.json(user);
      }

      res.json(users);
    } catch (error) {
      console.error('Error in /users:', error.message);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global Error Handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err.message);
  const statusCode = err.status || 500;
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

