// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const logger = require('./logger'); // Assumed logging utility

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Parse JSON with size limit to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
    };
    res.status(200).json(response);
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get users endpoint with optional filtering
 * GET /users?limit=10&offset=0
 */
app.get(
  '/users',
  [
    // Input validation
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a positive integer'),
  ],
  (req, res) => {
    try {
      // Handle validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Invalid input parameters',
          details: errors.array(),
        });
      }

      // Extract and set defaults
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      // Mock data (in production, fetch from database)
      const allUsers = [
        { id: 1, name: 'Alice' }, // Note: email removed for privacy
        { id: 2, name: 'Bob' },
      ];

      // Apply pagination
      const paginatedUsers = allUsers.slice(offset, offset + limit);

      res.status(200).json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
        },
      });
    } catch (error) {
      logger.error('Get users error:', error);
      res.status(500).json({ error: 'Failed to retrieve users' });
    }
  }
);

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handling middleware (should be last)
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', err);

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    error: 'Internal server error',
    ...(isDevelopment && { message: err.message, stack: err.stack }),
  };

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json(errorResponse);
});

// ============================================
// SERVER START
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Improvement Guide for app.js

## Executive Summary
The current application lacks critical security measures including input validation, error handling, rate limiting, and security headers. Below are detailed recommendations.

---

## 🔴 Critical Issues

### 1. **No Input Validation**
**Risk**: Injection attacks, parameter pollution, DoS attacks

**Current Code**:
```javascript
app.get('/users', (req, res) => {
  // No validation of query parameters
  res.json([...]);
});
```

**Improved Code**:
```javascript
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ error: 'Invalid input' });
    }
    // Process request
  }
);
```

---

### 2. **Inadequate Error Handling**
**Risk**: Information disclosure, unhandled exceptions crashing server

**Issues**:
- No try-catch blocks
- No global error handler
- Errors may expose stack traces

**Solution**:
```javascript
// Wrap route handlers in try-catch
app.get('/users', (req, res) => {
  try {
    // ... code
  } catch (error) {
    logger.error('Error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error middleware
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', err);
  const isDev = process.env.NODE_ENV === 'development';
  res.status(err.statusCode || 500).json({
    error: 'Internal server error',
    ...(isDev && { message: err.message })
  });
});
```

---

### 3. **Missing Security Headers**
**Risk**: XSS, clickjacking, MIME-type sniffing

**Solution**:
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds multiple security headers
```

Headers added:
- `X-Content-Type-Options: nosniff`
- `X-Frame-Options: DENY`
- `X-XSS-Protection: 1; mode=block`
- `Strict-Transport-Security`
- Content Security Policy

---

### 4. **No Rate Limiting**
**Risk**: Brute force attacks, DoS attacks

**Solution**:
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // max requests per window
  message: 'Too many requests'
});

app.use(limiter);
```

---

### 5. **No Request Size Limits**
**Risk**: Memory exhaustion, DoS attacks

**Solution**:
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb' }));
```

---

## 🟡 Medium Issues

### 6. **Information Disclosure**
**Risk**: Exposing sensitive data unnecessarily

**Current**: User emails are exposed in public `/users` endpoint
```javascript
{ id: 1, name: 'Alice', email: 'alice@example.com' }
```

**Improved**:
```javascript
{ id: 1, name: 'Alice' } // Remove sensitive fields
```

---

### 7. **No Logging**
**Risk**: Cannot track or audit security incidents

**Solution**:
```javascript
const logger = require('./logger');
logger.error('Error details:', error);
logger.info('Request processed');
```

---

### 8. **Hardcoded Configuration**
**Risk**: Port and secrets in code

**Current**:
```javascript
app.listen(3000, ...);
```

**Improved**:
```javascript
const PORT = process.env.PORT || 3000;
app.listen(PORT, ...);
```

---

### 9. **No Graceful Shutdown**
**Risk**: Data loss, incomplete requests on restart

**Solution**:
```javascript
process.on('SIGTERM', () => {
  logger.info('Shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});
```

---

### 10. **No CORS Configuration**
**Risk**: Uncontrolled cross-origin access

**Solution**:
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['localhost:3000'],
  methods: ['GET'],
  credentials: true
}));
```

---

## 🟢 Implementation Checklist

- [ ] Install dependencies:
  ```bash
  npm install helmet express-rate-limit express-validator cors
  npm install --save-dev winston # for logging
  ```

- [ ] Create logger utility (`logger.js`)
- [ ] Implement input validation on all routes
- [ ] Add global error handler
- [ ] Configure security headers with helmet
- [ ] Set up rate limiting
- [ ] Add request size limits
- [ ] Remove sensitive data from responses
- [ ] Implement graceful shutdown
- [ ] Add CORS configuration
- [ ] Set up environment variables
- [ ] Add logging throughout the app
- [ ] Test error scenarios
- [ ] Document security measures

---

## 📋 Environment Variables

Create `.env` file:
```
PORT=3000
NODE_ENV=development
ALLOWED_ORIGINS=http://localhost:3000,https://app.example.com
LOG_LEVEL=info
RATE_LIMIT_WINDOW_MS=900000
RATE_LIMIT_MAX_REQUESTS=100
```

---

## 🔗 Additional Resources

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Node.js Security Best Practices](https://nodejs.org/en/docs/guides/security/)
- [Helmet.js Documentation](https://helmetjs.github.io/)
- [Express-validator](https://express-validator.github.io/docs/)

---

## Testing Recommendations

```javascript
