// logger.js - Simple logging utility
const fs = require('fs');
const path = require('path');

const LOG_LEVELS = {
  ERROR: 0,
  WARN: 1,
  INFO: 2,
  DEBUG: 3,
};

const currentLogLevel = LOG_LEVELS[process.env.LOG_LEVEL || 'INFO'];

const logDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir);
}

const formatTimestamp = () => new Date().toISOString();

const writeLog = (level, message, data = null) => {
  if (LOG_LEVELS[level] > currentLogLevel) return;

  const timestamp = formatTimestamp();
  const logMessage = `[${timestamp}] [${level}] ${message}${
    data ? ' ' + JSON.stringify(data) : ''
  }\n`;

  // Console output (always)
  console[level === 'ERROR' ? 'error' : level === 'WARN' ? 'warn' : 'log'](
    logMessage
  );

  // File output (errors only in production)
  if (process.env.NODE_ENV === 'production' || level === 'ERROR') {
    const logFile = path.join(
      logDir,
      `${level.toLowerCase()}-${new Date().toISOString().split('T')[0]}.log`
    );
    fs.appendFileSync(logFile, logMessage, { encoding: 'utf8' });
  }
};

module.exports = {
  error: (message, data) => writeLog('ERROR', message, data),
  warn: (message, data) => writeLog('WARN', message, data),
  info: (message, data) => writeLog('INFO', message, data),
  debug: (message, data) => writeLog('DEBUG', message, data),
};

