// config.js - Environment configuration with validation
const path = require('path');

// Load .env file if it exists
require('dotenv').config({ path: path.join(__dirname, '.env') });

/**
 * Configuration schema defining all environment variables
 */
const CONFIG_SCHEMA = {
  required: [],
  optional: [
    {
      name: 'PORT',
      default: '3000',
      type: 'number',
      description: 'Server listening port',
    },
    {
      name: 'NODE_ENV',
      default: 'development',
      type: 'string',
      enum: ['development', 'staging', 'production'],
      description: 'Application environment',
    },
    {
      name: 'LOG_LEVEL',
      default: 'info',
      type: 'string',
      enum: ['error', 'warn', 'info', 'debug'],
      description: 'Logging verbosity level',
    },
    {
      name: 'ALLOWED_ORIGINS',
      default: 'http://localhost:3000',
      type: 'string',
      description: 'Comma-separated list of allowed CORS origins',
    },
    {
      name: 'RATE_LIMIT_WINDOW_MS',
      default: '900000',
      type: 'number',
      description: 'Rate limit time window in milliseconds (15 minutes default)',
    },
    {
      name: 'RATE_LIMIT_MAX_REQUESTS',
      default: '100',
      type: 'number',
      description: 'Maximum requests allowed per rate limit window',
    },
  ],
};

/**
 * Validate environment variables against schema
 */
function validateConfig() {
  const config = {};
  const errors = [];
  const warnings = [];

  // Validate required variables
  for (const { name, type, enum: enumValues, description } of CONFIG_SCHEMA.required) {
    const value = process.env[name];

    if (!value) {
      errors.push(`Missing required environment variable: ${name} - ${description}`);
      continue;
    }

    const validated = validateVariable(name, value, type, enumValues);
    if (validated.error) {
      errors.push(validated.error);
    } else {
      config[name] = validated.value;
    }
  }

  // Validate optional variables (use defaults if not set)
  for (const { name, default: defaultValue, type, enum: enumValues, description } of CONFIG_SCHEMA.optional) {
    const value = process.env[name] || defaultValue;

    const validated = validateVariable(name, value, type, enumValues);
    if (validated.error) {
      errors.push(validated.error);
    } else {
      config[name] = validated.value;
      if (!process.env[name]) {
        warnings.push(`${name} not set, using default: ${defaultValue}`);
      }
    }
  }

  // Throw on required errors
  if (errors.length > 0) {
    throw new Error(`Configuration validation failed:\n${errors.join('\n')}`);
  }

  // Log warnings
  if (warnings.length > 0) {
    warnings.forEach(w => console.warn(`⚠️  ${w}`));
  }

  return config;
}

/**
 * Validate individual variable type and enum values
 */
function validateVariable(name, value, type, enumValues) {
  try {
    let converted = value;

    // Type conversion
    if (type === 'number') {
      converted = parseInt(value, 10);
      if (isNaN(converted)) {
        return {
          error: `Invalid ${name}: expected number, got "${value}"`,
        };
      }
    }

    // Enum validation
    if (enumValues && Array.isArray(enumValues)) {
      if (!enumValues.includes(converted.toString())) {
        return {
          error: `Invalid ${name}: "${converted}" must be one of [${enumValues.join(', ')}]`,
        };
      }
    }

    return { value: converted };
  } catch (error) {
    return { error: `Error validating ${name}: ${error.message}` };
  }
}

/**
 * Format and display configuration on startup
 */
function logConfiguration(config) {
  console.log('\n========================================');
  console.log('Application Configuration');
  console.log('========================================');
  console.log(`PORT:                     ${config.PORT}`);
  console.log(`NODE_ENV:                 ${config.NODE_ENV}`);
  console.log(`LOG_LEVEL:                ${config.LOG_LEVEL}`);
  console.log(`ALLOWED_ORIGINS:          ${config.ALLOWED_ORIGINS}`);
  console.log(`RATE_LIMIT_WINDOW_MS:     ${config.RATE_LIMIT_WINDOW_MS}ms`);
  console.log(`RATE_LIMIT_MAX_REQUESTS:  ${config.RATE_LIMIT_MAX_REQUESTS}`);
  console.log('========================================\n');
}

/**
 * Get parsed configuration object
 */
let cachedConfig = null;

function getConfig() {
  if (!cachedConfig) {
    cachedConfig = validateConfig();
    logConfiguration(cachedConfig);
  }
  return cachedConfig;
}

module.exports = {
  getConfig,
  validateConfig,
  CONFIG_SCHEMA,
};

