// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
require('dotenv').config();

const app = express();

// ============================================
// MIDDLEWARE SETUP
// ============================================

// Security: Set security HTTP headers
app.use(helmet());

// Security: Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Parse JSON bodies
app.use(express.json({ limit: '10kb' })); // Limit payload size

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * GET /users
 * Query parameters:
 *   - filter (optional): Filter by user ID
 *   - limit (optional): Limit number of results
 */
app.get('/users', (req, res) => {
  try {
    // Input validation
    const { filter, limit } = req.query;

    // Validate filter parameter if provided
    if (filter !== undefined) {
      if (!validator.isNumeric(String(filter))) {
        return res.status(400).json({
          error: 'Invalid filter parameter. Must be a numeric user ID.',
        });
      }
    }

    // Validate limit parameter if provided
    if (limit !== undefined) {
      if (!validator.isNumeric(String(limit))) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be a number.',
        });
      }
      const limitNum = parseInt(limit, 10);
      if (limitNum < 1 || limitNum > 1000) {
        return res.status(400).json({
          error: 'Limit must be between 1 and 1000.',
        });
      }
    }

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filter if provided
    let result = users;
    if (filter !== undefined) {
      const filterId = parseInt(filter, 10);
      result = users.filter((user) => user.id === filterId);
      if (result.length === 0) {
        return res.status(404).json({
          error: 'User not found.',
        });
      }
    }

    // Apply limit if provided
    if (limit !== undefined) {
      result = result.slice(0, parseInt(limit, 10));
    }

    // Remove sensitive fields if needed (example: don't expose internal IDs in production)
    // For now, returning as-is, but in production you might filter certain fields
    const sanitizedResult = result.map((user) => ({
      id: user.id,
      name: user.name,
      // email: removed for security (only return if needed)
    }));

    res.json(sanitizedResult);
  } catch (error) {
    console.error('Error in GET /users:', error);
    res.status(500).json({
      error: 'Internal server error. Please try again later.',
    });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unexpected error:', err);

  // Don't expose sensitive error details to clients
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    error: message,
    timestamp: new Date().toISOString(),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Improvement Recommendations for app.js

## Executive Summary
The original app.js is a basic Express application with several security and reliability gaps. This review addresses error handling, input validation, and security best practices.

---

## Critical Issues Found

### 1. **NO ERROR HANDLING** ⚠️ CRITICAL
**Problem:**
- No try-catch blocks in route handlers
- No global error middleware
- No 404 handler
- Unhandled promise rejections will crash the server

**Impact:** Application crashes on errors, poor user experience, information leakage

**Fix:**
```javascript
// Add try-catch in routes
app.get('/users', (req, res) => {
  try {
    // route logic
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Add global error middleware (must be last)
app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.statusCode || 500).json({ error: 'Server error' });
});
```

---

### 2. **NO INPUT VALIDATION** ⚠️ HIGH
**Problem:**
- Query parameters accepted without validation
- No checks for malformed or malicious input
- Vulnerable to injection attacks

**Impact:** Buffer overflow, injection attacks, DoS attacks

**Fix:**
```javascript
const validator = require('validator');

app.get('/users', (req, res) => {
  const { filter, limit } = req.query;

  // Validate numeric inputs
  if (filter && !validator.isNumeric(String(filter))) {
    return res.status(400).json({ error: 'Invalid filter' });
  }

  // Validate range
  if (limit && (parseInt(limit) < 1 || parseInt(limit) > 1000)) {
    return res.status(400).json({ error: 'Limit out of range' });
  }
});
```

---

### 3. **MISSING SECURITY HEADERS** ⚠️ HIGH
**Problem:**
- No Content Security Policy (CSP)
- No X-Frame-Options protection
- No X-Content-Type-Options
- Vulnerable to clickjacking, MIME type sniffing, XSS

**Impact:** Clickjacking attacks, MIME type sniffing, XSS vulnerabilities

**Fix:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds 15+ security headers
```

---

### 4. **NO RATE LIMITING** ⚠️ MEDIUM
**Problem:**
- Anyone can make unlimited requests
- Vulnerable to DoS/DDoS attacks
- Resource exhaustion possible

**Impact:** Service disruption, increased costs

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per window
});

app.use(limiter);
```

---

### 5. **SENSITIVE DATA EXPOSURE** ⚠️ MEDIUM
**Problem:**
- Email addresses exposed in /users endpoint
- No field filtering
- No data classification

**Impact:** Privacy breach, GDPR/compliance violations

**Fix:**
```javascript
const sanitized = users.map(user => ({
  id: user.id,
  name: user.name
  // email removed
}));
res.json(sanitized);
```

---

### 6. **MISSING PAYLOAD SIZE LIMIT** ⚠️ MEDIUM
**Problem:**
- No limit on request body size
- Vulnerable to memory exhaustion

**Impact:** DoS attacks, memory overflow

**Fix:**
```javascript
app.use(express.json({ limit: '10kb' }));
```

---

### 7. **HARDCODED CONFIGURATION** ⚠️ LOW
**Problem:**
- Port hardcoded to 3000
- No environment configuration
- NODE_ENV not considered

**Impact:** Inflexible deployment, information leakage

**Fix:**
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
```

---

### 8. **NO REQUEST LOGGING** ⚠️ LOW
**Problem:**
- No audit trail
- Difficult to debug
- Cannot track security events

**Impact:** Reduced observability, difficult incident response

**Fix:**
```javascript
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});
```

---

### 9. **NO GRACEFUL SHUTDOWN** ⚠️ LOW
**Problem:**
- Server doesn't handle signals properly
- Active connections may be lost during restart

**Impact:** Data loss, poor user experience

**Fix:**
```javascript
process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
});
```

---

### 10. **INFORMATION DISCLOSURE** ⚠️ MEDIUM
**Problem:**
- Error messages expose stack traces in production
- Timestamps may leak information

**Impact:** Information leakage to attackers

**Fix:**
```javascript
const message = process.env.NODE_ENV === 'production'
  ? 'Internal server error'
  : err.message;
res.status(500).json({ error: message });
```

---

## Recommended Dependencies

Add these to `package.json`:

```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "express-rate-limit": "^7.0.0",
    "validator": "^13.11.0",
    "dotenv": "^16.3.1"
  }
}
```

Install with:
```bash
npm install helmet express-rate-limit validator dotenv
```

---

## Additional Security Best Practices

### 1. **Use HTTPS in Production**
```javascript
if (process.env.NODE_ENV === 'production') {
  // Enforce HTTPS
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}
```

### 2. **Implement CORS Properly**
```javascript
const cors = require('cors');
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));
```

### 3. **Add Request ID for Tracing**
```javascript
const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});
```

### 4. **Implement Database Query Parameterization**
(When adding database layer)
```javascript
// ✅ GOOD - Parameterized query
db.query('SELECT * FROM users WHERE id = ?', [userId]);

// ❌ BAD - SQL Injection vulnerable
db.query(`SELECT * FROM users WHERE id = ${userId}`);
```

### 5. **Use OWASP Top 10 Checklist**
- A01: Broken Access Control
- A02: Cryptographic Failures
- A03: Injection
- A04: Insecure Design
- A05: Security Misconfiguration
- A06: Vulnerable & Outdated Components
- A07: Authentication Failures
- A08: Software & Data Integrity Failures
- A09: Logging & Monitoring Failures
- A10: SSRF

---

## Testing Recommendations

### 1. **Security Testing**
```bash
# Check for vulnerabilities
npm audit

# OWASP ZAP scanning
# NIST security guidelines
```

### 2. **Unit Tests for Validation**
```javascript
describe('GET /users', () => {
  it('should reject non-numeric filter', (done) => {
    request(app)
      .get('/users?filter=abc')
      .expect(400)
      .end(done);
  });
});
```

---

## Summary of Improvements

| Issue | Severity | Fix Applied |
|-------|----------|-------------|
| No error handling | CRITICAL | Global error middleware + try-catch |
| No input validation | HIGH | Validator library + range checks |
| Missing security headers | HIGH | Helmet.js |
| No rate limiting | MEDIUM | express-rate-limit |
| Sensitive data exposed | MEDIUM | Field filtering |
| No payload size limit | MEDIUM | express.json limit |
| Hardcoded config | LOW | dotenv support |
| No request logging | LOW | Logging middleware |
| No graceful shutdown | LOW | Signal handlers |
| Information disclosure | MEDIUM | Error message filtering |

---

## Implementation Steps

1. Install dependencies: `npm install helmet express-rate-limit validator dotenv`
2. Replace app.js with improved version (app_improved.js)
3. Create .env file with configuration
4. Add unit/integration tests
5. Enable HTTPS in production
6. Set up security monitoring/alerting
7. Perform security audit with OWASP ZAP
8. Document security policies

---

## References

- [OWASP Top 10](https://owasp.org/Top10/)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [NIST Secure Software Development Framework](https://csrc.nist.gov/projects/secure-software-development-framework/)
- [Helmet.js Documentation](https://helmetjs.github.io/)

