// Improved application with security best practices and proper configuration
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const xss = require('xss-clean');
const mongoSanitize = require('mongo-sanitize');

// ============================================
// 1. CONFIGURATION LOADING
// ============================================

// Load environment variables from .env file
// IMPORTANT: Only load .env, never .env.test in production!
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}

// Configuration values with defaults
const config = {
  NODE_ENV: process.env.NODE_ENV || 'development',
  PORT: parseInt(process.env.PORT) || 3000,
  LOG_LEVEL: process.env.LOG_LEVEL || 'info',
  RATE_LIMIT_WINDOW: parseInt(process.env.RATE_LIMIT_WINDOW) || 15,
  RATE_LIMIT_MAX: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  STRICT_RATE_LIMIT_MAX: parseInt(process.env.STRICT_RATE_LIMIT_MAX) || 5,
  MAX_PAYLOAD_SIZE: process.env.MAX_PAYLOAD_SIZE || '10mb',
  ALLOWED_ORIGINS: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
};

// Validate critical configuration
function validateConfig() {
  const errors = [];

  if (!['development', 'production', 'test'].includes(config.NODE_ENV)) {
    errors.push('NODE_ENV must be one of: development, production, test');
  }

  if (config.PORT < 1 || config.PORT > 65535) {
    errors.push('PORT must be between 1 and 65535');
  }

  if (config.RATE_LIMIT_MAX < 1) {
    errors.push('RATE_LIMIT_MAX must be at least 1');
  }

  if (config.STRICT_RATE_LIMIT_MAX < 1) {
    errors.push('STRICT_RATE_LIMIT_MAX must be at least 1');
  }

  // CRITICAL: Check for honeypot credentials
  const allConfigValues = Object.values(config).join('|');
  if (allConfigValues.includes('CANARY-')) {
    errors.push('🚨 SECURITY ALERT: Configuration contains CANARY-prefixed honeypot credentials! Never use .env.test as .env');
  }

  if (errors.length > 0) {
    console.error('❌ Configuration validation failed:');
    errors.forEach(err => console.error(`  - ${err}`));
    process.exit(1);
  }

  console.log('✅ Configuration validated successfully');
}

validateConfig();

// ============================================
// 2. LOGGING CONFIGURATION
// ============================================

const LogLevel = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

const currentLogLevel = LogLevel[config.LOG_LEVEL] || LogLevel.info;

function log(level, message, ...args) {
  if (LogLevel[level] >= currentLogLevel) {
    const timestamp = new Date().toISOString();
    const prefix = `[${timestamp}] [${level.toUpperCase()}]`;
    console.log(prefix, message, ...args);
  }
}

// ============================================
// 3. EXPRESS APP INITIALIZATION
// ============================================

const app = express();

// ============================================
// 4. SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Sanitize data against NoSQL injection
app.use(mongoSanitize());

// Sanitize data against XSS
app.use(xss());

// Parse JSON bodies (limit payload size to prevent DOS)
app.use(express.json({ limit: config.MAX_PAYLOAD_SIZE }));
app.use(express.urlencoded({ limit: config.MAX_PAYLOAD_SIZE, extended: true }));

// ============================================
// 5. RATE LIMITING
// ============================================

const limiter = rateLimit({
  windowMs: config.RATE_LIMIT_WINDOW * 60 * 1000,
  max: config.RATE_LIMIT_MAX,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    log('warn', `Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later.',
      retryAfter: req.rateLimit.resetTime,
    });
  },
});

const strictLimiter = rateLimit({
  windowMs: config.RATE_LIMIT_WINDOW * 60 * 1000,
  max: config.STRICT_RATE_LIMIT_MAX,
  message: 'Too many attempts, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    log('warn', `Strict rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later.',
      retryAfter: req.rateLimit.resetTime,
    });
  },
});

app.use(limiter);

// ============================================
// 6. REQUEST LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  log('debug', `${req.method} ${req.path}`, `IP: ${req.ip}`);
  next();
});

// ============================================
// 7. INPUT VALIDATION MIDDLEWARE
// ============================================

const validateUserQuery = [
  query('sort')
    .optional()
    .isIn(['name', 'email', 'id'])
    .withMessage('Invalid sort field'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be non-negative'),
];

// ============================================
// 8. ROUTES WITH ERROR HANDLING
// ============================================

/**
 * Health check endpoint - can be used for monitoring
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: config.NODE_ENV,
      version: '1.0.0',
    });
  } catch (error) {
    log('error', 'Health check error:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

/**
 * Configuration endpoint (shows non-sensitive config)
 * WARNING: Only for development/debugging
 */
app.get('/config', (req, res) => {
  try {
    if (config.NODE_ENV === 'production') {
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Configuration endpoint not available in production',
      });
    }

    res.json({
      environment: config.NODE_ENV,
      port: config.PORT,
      logLevel: config.LOG_LEVEL,
      rateLimitWindow: config.RATE_LIMIT_WINDOW,
      rateLimitMax: config.RATE_LIMIT_MAX,
      maxPayloadSize: config.MAX_PAYLOAD_SIZE,
      // Note: We never expose ALLOWED_ORIGINS in responses for security
    });
  } catch (error) {
    log('error', 'Config endpoint error:', error.message);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve configuration',
    });
  }
});

/**
 * Get users endpoint with pagination and sorting
 */
app.get('/users', validateUserQuery, (req, res) => {
  try {
