    ];

    // Extract and validate query parameters with defaults
    const sort = req.query.sort || 'id';
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = parseInt(req.query.offset) || 0;

    // Sort users
    const sortedUsers = [...users].sort((a, b) => {
      const aVal = a[sort];
      const bVal = b[sort];
      if (aVal < bVal) return -1;
      if (aVal > bVal) return 1;
      return 0;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length,
      },
    });
  } catch (error) {
    log('error', 'Get users error:', error.message);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users',
    });
  }
});

/**
 * User creation endpoint with input validation
 */
app.post('/users', strictLimiter, [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
], (req, res) => {
  try {
    // Validate request body
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array().map(err => ({
          field: err.param,
          message: err.msg,
        })),
      });
    }

    // Create user (example)
    const newUser = {
      id: Math.floor(Math.random() * 10000),
      name: req.body.name,
      email: req.body.email,
    };

    log('info', `User created: ${newUser.email}`);

    res.status(201).json({
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    log('error', 'Create user error:', error.message);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to create user',
    });
  }
});

// ============================================
// 9. 404 HANDLER
// ============================================

app.use((req, res) => {
  log('warn', `404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({
    error: 'Not Found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist`,
  });
});

// ============================================
// 10. GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  log('error', `Unhandled error: ${err.message}`, err.stack);

  // Don't leak error details to client in production
  const isDevelopment = config.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================
// 11. SERVER STARTUP
// ============================================

const server = app.listen(config.PORT, () => {
  log('info', `✅ Server started successfully`);
  log('info', `Environment: ${config.NODE_ENV}`);
  log('info', `Port: ${config.PORT}`);
  log('info', `Log Level: ${config.LOG_LEVEL}`);
  log('info', `Rate Limit: ${config.RATE_LIMIT_MAX} requests per ${config.RATE_LIMIT_WINDOW} minutes`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  log('warn', 'SIGTERM received, shutting down gracefully...');
  server.close(() => {
    log('info', 'Server shut down');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  log('warn', 'SIGINT received, shutting down gracefully...');
  server.close(() => {
    log('info', 'Server shut down');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  log('error', 'Uncaught Exception:', err.message);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  log('error', 'Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

