// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Set security HTTP headers
app.use(helmet());

// Parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// ==================== LOGGING ====================

const logger = {
  error: (message, error) => console.error(`[ERROR] ${new Date().toISOString()} - ${message}`, error),
  warn: (message) => console.warn(`[WARN] ${new Date().toISOString()} - ${message}`),
  info: (message) => console.info(`[INFO] ${new Date().toISOString()} - ${message}`),
};

// ==================== VALIDATION MIDDLEWARE ====================

// Custom validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      message: 'Validation failed',
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ==================== ROUTES ====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    logger.error('Health check failed', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error',
    });
  }
});

// Get users with optional filtering
app.get(
  '/users',
  query('filter')
    .optional()
    .isIn(['all', 'names'])
    .withMessage('Invalid filter value. Allowed: all, names'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  handleValidationErrors,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const filter = req.query.filter || 'all';
      const limit = parseInt(req.query.limit, 10) || 10;

      let result = users.slice(0, limit);

      // Apply filtering
      if (filter === 'names') {
        result = result.map(user => ({ id: user.id, name: user.name }));
      }

      res.json({
        success: true,
        data: result,
        count: result.length,
      });
    } catch (error) {
      logger.error('Failed to fetch users', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error',
      });
    }
  }
);

// Get single user by ID
app.get(
  '/users/:id',
  query('includeEmail')
    .optional()
    .isIn(['true', 'false'])
    .withMessage('includeEmail must be true or false'),
  handleValidationErrors,
  (req, res) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Validate ID format
      if (isNaN(userId) || userId < 1) {
        return res.status(400).json({
          success: false,
          message: 'Invalid user ID format',
        });
      }

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'User not found',
        });
      }

      const includeEmail = req.query.includeEmail === 'true';
      const response = {
        id: user.id,
        name: user.name,
      };

      if (includeEmail) {
        response.email = user.email;
      }

      res.json({
        success: true,
        data: response,
      });
    } catch (error) {
      logger.error('Failed to fetch user', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error',
      });
    }
  }
);

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Endpoint not found',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error('Unhandled error', err);

  // Default error response
  const statusCode = err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    success: false,
    message: isProduction ? 'Internal server error' : err.message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ==================== SERVER INITIALIZATION ====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  logger.info(`Server running on ${HOST}:${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', { promise, reason });
  process.exit(1);
});

module.exports = app;

