/**
 * Enhanced Express Application with Security Best Practices
 * Includes: error handling, input validation, security headers, logging
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const dotenv = require('dotenv');

// Load environment variables
dotenv.config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================
// MIDDLEWARE - Security
// ============================================

// Set security HTTP headers
app.use(helmet());

// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Sanitize data against NoSQL injection
app.use(mongoSanitize());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============================================
// MIDDLEWARE - Logging
// ============================================

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} (${duration}ms)`);
  });
  next();
});

// ============================================
// ROUTES
// ============================================

/**
 * GET /health
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
    });
  } catch (error) {
    handleError(res, error, 'Health check failed', 500);
  }
});

/**
 * GET /users
 * Get list of users with optional filtering
 * Query params: id (number), email (email format)
 */
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const { id, email } = req.query;
    const errors = [];

    // Validate id if provided
    if (id !== undefined) {
      if (!validator.isNumeric(String(id))) {
        errors.push('Invalid id: must be a number');
      }
    }

    // Validate email if provided
    if (email !== undefined) {
      if (!validator.isEmail(String(email))) {
        errors.push('Invalid email format');
      }
    }

    // Return validation errors if any
    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors,
      });
    }

    // Mock database
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filters
    if (id !== undefined) {
      const userId = parseInt(id, 10);
      users = users.filter(user => user.id === userId);

      if (users.length === 0) {
        return res.status(404).json({
          error: 'User not found',
          id: userId,
        });
      }
    }

    if (email !== undefined) {
      users = users.filter(user => user.email.toLowerCase() === String(email).toLowerCase());

      if (users.length === 0) {
        return res.status(404).json({
          error: 'User not found',
          email: email,
        });
      }
    }

    res.json({
      success: true,
      data: users,
      count: users.length,
    });
  } catch (error) {
    handleError(res, error, 'Failed to retrieve users', 500);
  }
});

/**
 * POST /users
 * Create a new user
 * Body: { name: string, email: string }
 */
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;
    const errors = [];

    // Input validation
    if (!name) {
      errors.push('Name is required');
    } else if (!validator.isLength(String(name), { min: 1, max: 100 })) {
      errors.push('Name must be between 1 and 100 characters');
    }

    if (!email) {
      errors.push('Email is required');
    } else if (!validator.isEmail(String(email))) {
      errors.push('Invalid email format');
    }

    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors,
      });
    }

    // Sanitize input
    const sanitizedName = validator.trim(String(name));
    const sanitizedEmail = validator.normalizeEmail(String(email));

    // Mock: Create user (in real app, would save to database)
    const newUser = {
      id: Math.floor(Math.random() * 10000),
      name: sanitizedName,
      email: sanitizedEmail,
    };

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    handleError(res, error, 'Failed to create user', 500);
  }
});

// ============================================
// ERROR HANDLING
// ============================================

/**
 * 404 Not Found Handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The endpoint ${req.method} ${req.path} does not exist`,
    timestamp: new Date().toISOString(),
  });
});

/**
 * Global Error Handler Middleware
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details in production
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(err.status || 500).json({
    error: err.name || 'Error',
    message: message,
    ...(NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ============================================
// HELPER FUNCTIONS
// ============================================

/**
 * Centralized error handler
 * @param {Response} res - Express response object
 * @param {Error} error - Error object
 * @param {string} message - User-friendly message
 * @param {number} statusCode - HTTP status code
 */
function handleError(res, error, message, statusCode = 500) {
  console.error(`[Error] ${message}:`, error);

  const response = {
    error: message,
    timestamp: new Date().toISOString(),
  };

  // Only include error details in development
  if (NODE_ENV !== 'production') {
    response.details = error.message;
  }

  res.status(statusCode).json(response);
}

// ============================================
// SERVER STARTUP
// ============================================

const server = app.listen(PORT, () => {
  console.log(`✓ Server running on port ${PORT}`);
  console.log(`✓ Environment: ${NODE_ENV}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

