      const res = await request(app).get('/users?email=alice@example.com');

      expect(res.status).toBe(200);
      expect(res.body.data.length).toBe(1);
      expect(res.body.data[0].email).toBe('alice@example.com');
    });

    test('should reject invalid email parameter', async () => {
      const res = await request(app).get('/users?email=not-an-email');

      expect(res.status).toBe(400);
      expect(res.body).toHaveProperty('error', 'Validation failed');
      expect(res.body.details[0]).toContain('Invalid email');
    });

    test('should return 404 when email not found', async () => {
      const res = await request(app).get('/users?email=nonexistent@example.com');

      expect(res.status).toBe(404);
      expect(res.body).toHaveProperty('error', 'User not found');
    });
  });

  // ============================================
  // POST /users Tests
  // ============================================

  describe('POST /users', () => {
