        .send(userData);

      expect(res.status).toBe(201);
      expect(res.body).toHaveProperty('success', true);
      expect(res.body).toHaveProperty('data');
      expect(res.body.data.name).toBe('John Doe');
      expect(res.body.data.email).toBe('john@example.com');
    });

    test('should normalize email address', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'Jane', email: 'JANE@EXAMPLE.COM' });

      expect(res.status).toBe(201);
      expect(res.body.data.email).toBe('jane@example.com');
    });

    test('should reject missing name', async () => {
      const res = await request(app)
        .post('/users')
        .send({ email: 'john@example.com' });

      expect(res.status).toBe(400);
      expect(res.body.details.some(d => d.includes('Name'))).toBe(true);
    });

    test('should reject missing email', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'John' });

      expect(res.status).toBe(400);
      expect(res.body.details.some(d => d.includes('Email'))).toBe(true);
    });

    test('should reject invalid email format', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'John', email: 'invalid-email' });

      expect(res.status).toBe(400);
      expect(res.body.details.some(d => d.includes('email'))).toBe(true);
    });

    test('should reject name exceeding max length', async () => {
      const longName = 'a'.repeat(101);
      const res = await request(app)
        .post('/users')
        .send({ name: longName, email: 'john@example.com' });

      expect(res.status).toBe(400);
      expect(res.body.details.some(d => d.includes('Name'))).toBe(true);
    });

    test('should accept name at boundary length', async () => {
      const boundaryName = 'a'.repeat(100);
      const res = await request(app)
        .post('/users')
        .send({ name: boundaryName, email: 'john@example.com' });

      expect(res.status).toBe(201);
    });
  });

  // ============================================
  // Security Headers Tests
  // ============================================

  describe('Security Headers', () => {
    test('should include Content-Security-Policy header', async () => {
      const res = await request(app).get('/health');

      expect(res.headers).toHaveProperty('content-security-policy');
    });

    test('should include X-Content-Type-Options header', async () => {
      const res = await request(app).get('/health');

      expect(res.headers['x-content-type-options']).toBe('nosniff');
    });

    test('should include X-Frame-Options header', async () => {
      const res = await request(app).get('/health');

      expect(res.headers['x-frame-options']).toBe('DENY');
    });
  });

  // ============================================
  // 404 Tests
  // ============================================

  describe('404 Not Found', () => {
    test('should return 404 for non-existent endpoint', async () => {
