// Enhanced application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

const app = express();
const PORT = process.env.PORT || 3000;

// ============================================
// MIDDLEWARE - SECURITY & INPUT VALIDATION
// ============================================

// Use Helmet to set various HTTP headers for security
app.use(helmet());

// Enable CORS with specific origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Parse JSON with size limit to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Strict rate limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.',
});

// ============================================
// REQUEST LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);

  // Prevent sensitive data logging
  if (req.body) {
    const sanitizedBody = { ...req.body };
    if (sanitizedBody.password) sanitizedBody.password = '***';
    if (sanitizedBody.token) sanitizedBody.token = '***';
    console.log('Body:', sanitizedBody);
  }

  next();
});

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

const validateEmail = (email) => {
  if (!email || typeof email !== 'string') return false;
  return validator.isEmail(email);
};

const validateUserId = (id) => {
  const numId = parseInt(id, 10);
  if (!Number.isInteger(numId) || numId < 1) return false;
  return true;
};

// ============================================
// ROUTES WITH ERROR HANDLING
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Get all users
app.get('/api/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.status(200).json(users);
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// Get user by ID with input validation
app.get('/api/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Input validation
    if (!validateUserId(id)) {
      return res.status(400).json({ 
        error: 'Invalid user ID. Must be a positive integer.' 
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(id, 10));

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.status(200).json(user);
  } catch (error) {
    console.error('Get user by ID error:', error);
    res.status(500).json({ error: 'Failed to retrieve user' });
  }
});

// Search users with query validation
app.get('/api/users/search', (req, res) => {
  try {
    const { email, name } = req.query;

    // Input validation
    const errors = [];

    if (email && !validateEmail(email)) {
      errors.push('Invalid email format');
    }

    if (name && (typeof name !== 'string' || name.length > 100)) {
      errors.push('Name must be a string with max 100 characters');
    }

    if (errors.length > 0) {
      return res.status(400).json({ errors });
    }

    // Mock search logic
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const filtered = users.filter(u => {
      if (email && u.email !== email) return false;
      if (name && !u.name.toLowerCase().includes(name.toLowerCase())) return false;
      return true;
    });

    res.status(200).json(filtered);
  } catch (error) {
    console.error('Search users error:', error);
    res.status(500).json({ error: 'Search failed' });
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method
  });

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    error: 'Internal Server Error',
    ...(isDevelopment && { details: err.message })
  };

  res.status(err.statusCode || 500).json(errorResponse);
});

// ============================================
// SERVER STARTUP & SHUTDOWN
// ============================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

# Security Review & Recommendations for app.js

## Summary of Issues Found

### 🔴 Critical Issues
1. **No Error Handling**: Unhandled errors will crash the server or expose stack traces
2. **No Input Validation**: Routes accept user input without validation
3. **Missing Security Headers**: No protection against common attacks (XSS, Clickjacking, etc.)
4. **No Rate Limiting**: Application is vulnerable to brute force and DoS attacks

### 🟡 Medium Issues
1. **No CORS Configuration**: Potential for unauthorized cross-origin requests
2. **Minimal Logging**: Cannot audit or debug security incidents
3. **No Request Size Limits**: Vulnerable to large payload attacks
4. **Hardcoded Configuration**: No environment-based settings

---

## Detailed Recommendations

### 1. Error Handling
**Problem**: No try-catch blocks or error middleware
**Solution**:
```javascript
// Add try-catch to all route handlers
app.get('/api/users/:id', (req, res) => {
  try {
    // route logic
  } catch (error) {
    console.error('Error:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Add global error handler middleware
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Server error' });
});
```

### 2. Input Validation
**Problem**: Query/path parameters not validated
**Solution**:
```javascript
// Validate user ID is integer
const validateUserId = (id) => {
  const numId = parseInt(id, 10);
  return Number.isInteger(numId) && numId > 0;
};

app.get('/api/users/:id', (req, res) => {
  if (!validateUserId(req.params.id)) {
    return res.status(400).json({ error: 'Invalid ID' });
  }
  // proceed
});

// Use validator library for emails
const validator = require('validator');
if (!validator.isEmail(email)) {
  return res.status(400).json({ error: 'Invalid email' });
}
```

### 3. Security Headers
**Problem**: No HTTP security headers
**Solution**:
```javascript
// Use Helmet middleware
const helmet = require('helmet');
app.use(helmet());
// Adds: CSP, X-Frame-Options, X-Content-Type-Options, etc.
```

### 4. Rate Limiting
**Problem**: No protection against brute force attacks
**Solution**:
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit to 100 requests per windowMs
});
app.use('/api/', limiter);
```

### 5. CORS Configuration
**Problem**: CORS not configured, allowing any origin
**Solution**:
```javascript
const cors = require('cors');
app.use(cors({
  origin: 'http://localhost:3000', // specify allowed origins
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

### 6. Data Sanitization
**Problem**: Vulnerable to NoSQL injection
**Solution**:
```javascript
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize()); // Removes $ and . from user input
```

### 7. Request Size Limits
**Problem**: No limits on payload size
**Solution**:
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

### 8. Logging
**Problem**: Insufficient logging for security auditing
**Solution**:
```javascript
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});
// Never log sensitive data (passwords, tokens)
```

### 9. 404 Handling
**Problem**: No handler for undefined routes
**Solution**:
```javascript
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

### 10. Graceful Shutdown
**Problem**: No cleanup on process termination
**Solution**:
```javascript
process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

