// Improved application with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const app = express();

// ============== SECURITY MIDDLEWARE ==============

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// More aggressive limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many attempts, please try again later',
});

// Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ============== REQUEST VALIDATION ==============

/**
 * Validates that a value is a positive integer
 */
function validatePositiveInteger(value, fieldName) {
  const parsed = parseInt(value, 10);
  if (isNaN(parsed) || parsed <= 0 || parsed.toString() !== value) {
    throw new Error(`${fieldName} must be a positive integer`);
  }
  return parsed;
}

/**
 * Validates email format (basic validation)
 */
function validateEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new Error('Invalid email format');
  }
  return email;
}

/**
 * Sanitizes string input
 */
function sanitizeString(str) {
  if (typeof str !== 'string') {
    throw new Error('Input must be a string');
  }
  return str.trim().slice(0, 100); // Limit length and trim
}

// ============== ERROR HANDLING MIDDLEWARE ==============

/**
 * Custom error handling middleware
 */
const errorHandler = (err, req, res, next) => {
  const isDev = process.env.NODE_ENV !== 'production';

  // Default error
  let status = err.status || 500;
  let message = err.message || 'Internal Server Error';

  // Validation errors
  if (err.message && err.message.includes('must be')) {
    status = 400;
  }

  // Don't expose internal error details in production
  const errorResponse = {
    status: 'error',
    message: isDev ? message : 'An error occurred',
    ...(isDev && { stack: err.stack }), // Only in development
  };

  console.error(`[${new Date().toISOString()}] Error:`, err);

  res.status(status).json(errorResponse);
};

// ============== ROUTES ==============

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res, next) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (err) {
    next(err);
  }
});

/**
 * Get all users (with optional filtering)
 * GET /users?limit=10&offset=0
 */
app.get('/users', (req, res, next) => {
  try {
    // Input validation
    const limit = req.query.limit ? validatePositiveInteger(req.query.limit, 'limit') : 10;
    const offset = req.query.offset ? validatePositiveInteger(req.query.offset, 'offset') : 0;

    // Enforce reasonable limits
    if (limit > 100) {
      throw new Error('limit must not exceed 100');
    }

    // Mock data (in production, would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(offset, offset + limit);

    res.status(200).json({
      status: 'success',
      data: {
        users,
        count: users.length,
        total: allUsers.length,
        limit,
        offset,
      },
    });
  } catch (err) {
    next(err);
  }
});

/**
 * Get user by ID
 * GET /users/:id
 */
app.get('/users/:id', (req, res, next) => {
  try {
    const id = validatePositiveInteger(req.params.id, 'User ID');

    // Mock data
    const mockUsers = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com' },
    };

    const user = mockUsers[id];

    if (!user) {
      const err = new Error('User not found');
      err.status = 404;
      throw err;
    }

    res.status(200).json({
      status: 'success',
      data: { user },
    });
  } catch (err) {
    next(err);
  }
});

/**
 * Create a new user (example with validation)
 * POST /users
 */
app.post('/users', authLimiter, (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name || !email) {
      const err = new Error('Missing required fields: name, email');
      err.status = 400;
      throw err;
    }

    // Validate inputs
    const sanitizedName = sanitizeString(name);
    const validatedEmail = validateEmail(email);

    // Mock user creation
    const newUser = {
      id: 3,
      name: sanitizedName,
      email: validatedEmail,
    };

    res.status(201).json({
      status: 'success',
      data: { user: newUser },
    });
  } catch (err) {
    next(err);
  }
});

// ============== 404 HANDLER ==============

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
  });
});

// ============== ERROR HANDLER (MUST BE LAST) ==============

app.use(errorHandler);

// ============== SERVER STARTUP ==============

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security & Best Practices Review for app.js

## Summary of Issues Found

### 🔴 Critical Issues

1. **No Error Handling**
   - Unhandled exceptions will crash the server or expose stack traces
   - No structured error responses

2. **No Input Validation**
   - Query parameters accepted without validation
   - Susceptible to injection attacks and type confusion

3. **No Security Headers**
   - Missing helmet.js protection
   - No rate limiting against DoS attacks

4. **No Request Size Limits**
   - Could allow memory exhaustion attacks
   - No payload size validation

### 🟡 Important Issues

5. **No Authentication/Authorization**
   - User data exposed without access control
   - No JWT or session validation

6. **No CORS Configuration**
   - Open to cross-origin requests
   - Should explicitly define allowed origins

7. **Unstructured Error Responses**
   - Inconsistent response format
   - Stack traces could leak sensitive info

8. **No Request Logging**
   - Difficult to debug issues or detect attacks
   - No audit trail

---

## Detailed Recommendations

### 1. ✅ Add Security Headers (Helmet.js)

```javascript
const helmet = require('helmet');
app.use(helmet());
```

**Benefits:**
- Sets X-Frame-Options (prevents clickjacking)
- Sets X-Content-Type-Options (prevents MIME sniffing)
- Removes X-Powered-By header
- Enables Strict-Transport-Security for HTTPS
- Sets Content Security Policy

**Package**: `npm install helmet`

---

### 2. ✅ Implement Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests',
  standardHeaders: true,
});

app.use(limiter);
```

**Benefits:**
- Prevents DoS attacks
- Protects against brute force attempts
- Different limits for different endpoints

**Package**: `npm install express-rate-limit`

---

### 3. ✅ Add Input Validation

```javascript
function validatePositiveInteger(value, fieldName) {
  const parsed = parseInt(value, 10);
  if (isNaN(parsed) || parsed <= 0 || parsed.toString() !== value) {
    throw new Error(`${fieldName} must be a positive integer`);
  }
  return parsed;
}

function validateEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new Error('Invalid email format');
  }
  return email;
}
```

**Benefits:**
- Prevents type confusion attacks
- Stops injection attacks
- Ensures data integrity

**Best Practices:**
- Validate on server (never trust client)
- Whitelist allowed values
- Provide clear error messages
- Use libraries like `joi` for complex validation

---

### 4. ✅ Implement Error Handling

```javascript
const errorHandler = (err, req, res, next) => {
  const isDev = process.env.NODE_ENV !== 'production';

  let status = err.status || 500;
  let message = err.message || 'Internal Server Error';

  const errorResponse = {
    status: 'error',
    message: isDev ? message : 'An error occurred',
    ...(isDev && { stack: err.stack }),
  };

  console.error(`[${new Date().toISOString()}] Error:`, err);
  res.status(status).json(errorResponse);
};

app.use(errorHandler);
```

**Benefits:**
- Consistent error responses
- Prevents stack trace leakage
- Proper HTTP status codes
- Error logging for debugging

**Key Pattern:**
- Wrap all route handlers in try-catch
- Pass errors to `next(err)` for middleware to handle

---

### 5. ✅ Limit Request Size

```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

**Benefits:**
- Prevents memory exhaustion attacks
- Protects against large payload uploads
- Adjustable limits per use case

---

### 6. ✅ Sanitize Input Data

```javascript
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize());

function sanitizeString(str) {
  if (typeof str !== 'string') throw new Error('Must be string');
  return str.trim().slice(0, 100);
}
```

**Benefits:**
- Prevents NoSQL injection
- Removes dangerous characters
- Limits string length to prevent abuse

**Package**: `npm install express-mongo-sanitize`

---

### 7. ✅ Add Request Logging

```javascript
const morgan = require('morgan');
app.use(morgan('combined')); // or 'dev' for development
```

**Benefits:**
- Audit trail of requests
- Detect suspicious patterns
- Debugging aid

**Package**: `npm install morgan`

---

### 8. ✅ Implement Graceful Shutdown

```javascript
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('Shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

**Benefits:**
- Allows in-flight requests to complete
- Prevents data loss
- Clean process termination

---

### 9. ✅ Use Environment Variables

```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

**Benefits:**
- Configuration management
- Different settings per environment
- Secrets management (don't hardcode)

**.env file:**
```
PORT=3000
NODE_ENV=production
```

---

### 10. ✅ Add Response Structure Consistency

```javascript
// Success response
res.json({
  status: 'success',
  data: { users },
  timestamp: new Date().toISOString(),
});

// Error response
res.json({
  status: 'error',
  message: 'User not found',
  timestamp: new Date().toISOString(),
});
```

**Benefits:**
- Clients know what to expect
- Easier API consumption
- Professional API design

---

## Security Checklist

- [ ] **Authentication**: Add JWT or session-based auth
- [ ] **Authorization**: Implement role-based access control
- [ ] **HTTPS**: Use SSL/TLS in production
- [ ] **CORS**: Configure allowed origins
- [ ] **CSP**: Content Security Policy headers
- [ ] **SQL/NoSQL Injection**: Use parameterized queries/sanitization
