## 🔍 Validation Functions Template

```javascript
// Reusable validation utilities
const validators = {
  // Positive integer
  positiveInt: (val, name) => {
    const num = parseInt(val, 10);
    if (isNaN(num) || num <= 0) throw new Error(`${name} must be positive`);
    return num;
  },

  // Email
  email: (email) => {
    const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!regex.test(email)) throw new Error('Invalid email');
    return email;
  },

  // String length
  string: (str, min = 1, max = 100) => {
    if (typeof str !== 'string') throw new Error('Must be string');
    if (str.length < min || str.length > max) {
      throw new Error(`Length must be ${min}-${max}`);
    }
    return str.trim();
  },

  // Required field
  required: (val, name) => {
    if (!val) throw new Error(`${name} is required`);
    return val;
  },
};
```

