// Improved application with error handling and security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();
const PORT = process.env.PORT || 3000;

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Set security HTTP headers
app.use(helmet());

// Body parsing with size limits (prevent payload attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting (prevent brute force/DDoS)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============================================================================
// LOGGING MIDDLEWARE
// ============================================================================

// Simple request logging (consider using winston or pino in production)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint (no auth required)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Get users with pagination and filtering
app.get(
  '/users',
  // Input validation
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('name')
    .optional()
    .trim()
    .isLength({ max: 100 })
    .withMessage('Name must be less than 100 characters'),
  validateInput,
  (req, res, next) => {
    try {
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const nameFilter = req.query.name ? req.query.name.toLowerCase() : null;

      // Mock database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter if name provided
      let filtered = allUsers;
      if (nameFilter) {
        filtered = allUsers.filter(u =>
          u.name.toLowerCase().includes(nameFilter)
        );
      }

      // Pagination
      const start = (page - 1) * limit;
      const end = start + limit;
      const paginatedUsers = filtered.slice(start, end);

      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: filtered.length,
          pages: Math.ceil(filtered.length / limit),
        },
      });
    } catch (error) {
      next(error); // Pass to error handler
    }
  }
);

// Get user by ID with validation
app.get(
  '/users/:id',
  query('fields')
    .optional()
    .custom((value) => {
      const allowed = ['id', 'name', 'email'];
      const requested = value.split(',').map(f => f.trim());
      if (!requested.every(f => allowed.includes(f))) {
        throw new Error('Invalid field requested');
      }
      return true;
    })
    .withMessage('Invalid fields parameter'),
  validateInput,
  (req, res, next) => {
    try {
      const userId = parseInt(req.params.id);

      // Validate ID is a valid integer
      if (isNaN(userId) || userId <= 0) {
        return res.status(400).json({
          error: 'Invalid user ID',
          details: 'User ID must be a positive integer',
        });
      }

      // Mock database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = allUsers.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
        });
      }

      // Field filtering if requested
      if (req.query.fields) {
        const allowedFields = req.query.fields.split(',').map(f => f.trim());
        const filtered = {};
        allowedFields.forEach(field => {
          if (field in user) {
            filtered[field] = user[field];
          }
        });
        return res.json({ data: filtered });
      }

      res.json({ data: user });
    } catch (error) {
      next(error); // Pass to error handler
    }
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
  });

  const statusCode = err.statusCode || err.status || 500;
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(statusCode).json({
    error: err.message || 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security & Best Practices Review - app.js

## Critical Issues Found

### 🔴 HIGH PRIORITY

#### 1. **No Input Validation**
**Issue:** User input is completely unvalidated
```javascript
// ❌ BEFORE: No validation
app.get('/users', (req, res) => {
  res.json([...]); // Query params ignored
});
```

**Risk:** 
- NoSQL injection attacks
- XSS through error messages
- Logic errors from unexpected input types

**Fix:**
```javascript
// ✅ AFTER: Validate all input
app.get('/users',
  query('page').optional().isInt({ min: 1 }),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  validateInput,
  (req, res) => { /* ... */ }
);
```

---

#### 2. **No Error Handling**
**Issue:** Missing error handlers at endpoint and global levels
```javascript
// ❌ BEFORE: No try-catch
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Risk:**
- Unhandled exceptions crash server
- Stack traces leaked to clients
- No error logging/monitoring
- Poor debugging capabilities

**Fix:**
```javascript
// ✅ AFTER: Comprehensive error handling
try {
  // route logic
} catch (error) {
  next(error); // Pass to global error handler
}

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: err.message,
    ...(isDevelopment && { stack: err.stack })
  });
});
```

---

#### 3. **No Security Headers**
**Issue:** Missing HTTP security headers
```javascript
// ❌ BEFORE: No helmet
const app = express();
```

**Risk:**
- Clickjacking attacks
- MIME type sniffing
- XSS vulnerabilities
- Insecure SSL/TLS communication

**Fix:**
```javascript
// ✅ AFTER: Add helmet middleware
const helmet = require('helmet');
app.use(helmet());
// Automatically adds:
// - Content-Security-Policy
// - X-Frame-Options
// - X-Content-Type-Options
// - Strict-Transport-Security
// - etc.
```

---

#### 4. **Exposed Sensitive Data**
**Issue:** Email addresses exposed without authentication
```javascript
// ❌ BEFORE: No auth required
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' }
  ]);
});
```

**Risk:**
- PII (Personally Identifiable Information) exposure
- GDPR/privacy violations
- Information disclosure attack

**Fix:**
```javascript
// ✅ AFTER: Add authentication
app.get('/users', authenticate, authorize('admin'), (req, res) => {
  res.json([...]);
});
// Or use field filtering in responses
```

---

### 🟠 MEDIUM PRIORITY

#### 5. **No Rate Limiting**
**Issue:** No protection against brute force or DDoS
```javascript
// ❌ BEFORE: Unlimited requests accepted
```

**Risk:**
- Brute force attacks
- DDoS vulnerability
- Resource exhaustion

**Fix:**
```javascript
// ✅ AFTER: Rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);
```

---

#### 6. **No Request Size Limits**
**Issue:** No payload size restrictions
```javascript
// ❌ BEFORE: Unlimited body size
app.use(express.json());
```

**Risk:**
- Memory exhaustion attacks
- Large payload processing delays
- Buffer overflow attempts

**Fix:**
```javascript
// ✅ AFTER: Set size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb' }));
```

---

#### 7. **No Request Logging**
**Issue:** No audit trail or monitoring
```javascript
// ❌ BEFORE: Only console.log on startup
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Risk:**
- No incident investigation capability
- No security event tracking
- Difficult debugging

**Fix:**
```javascript
// ✅ AFTER: Add request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    console.log(
      `${req.method} ${req.path} - ${res.statusCode} - ${Date.now() - start}ms`
    );
  });
  next();
});
```

---

#### 8. **No Graceful Shutdown**
**Issue:** Hard termination can corrupt data
```javascript
// ❌ BEFORE: No signal handling
```

**Risk:**
- In-flight requests abruptly terminated
- Database connection issues
- Data corruption

**Fix:**
```javascript
// ✅ AFTER: Handle shutdown signals
process.on('SIGTERM', () => {
  server.close(() => {
    process.exit(0);
  });
});
```

---

### 🟡 LOW PRIORITY (Best Practices)

#### 9. **No Environment Variables**
- Use `process.env.PORT` instead of hardcoded `3000`
- Use `process.env.NODE_ENV` to differentiate environments

#### 10. **No CORS Configuration**
- Either explicitly configure CORS or disable cross-origin requests
- Currently uses Express defaults (allows all origins)

#### 11. **Missing API Documentation**
- No endpoint descriptions
- No parameter documentation
- Consider: OpenAPI/Swagger documentation

#### 12. **No Validation for ID Parameters**
```javascript
// ❌ BEFORE: Path parameter not validated
app.get('/users/:id', (req, res) => { /* ... */ });

// ✅ AFTER: Validate path parameters
const userId = parseInt(req.params.id);
if (isNaN(userId) || userId <= 0) {
  return res.status(400).json({ error: 'Invalid user ID' });
}
```

