// Improved application with security best practices
// Features: input validation, error handling, security headers, logging, rate limiting

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers - Protects against XSS, clickjacking, MIME sniffing, etc.
app.use(helmet());

// 2. Logging - Monitor requests for security incidents
app.use(morgan('combined'));

// 3. Body parser with size limits - Prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Rate Limiting - Prevent brute force and DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// More strict rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 30,
  message: 'Too many requests, please try again later.',
});

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

/**
 * Sanitize user input to prevent injection attacks
 */
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return '';
  return input.trim().slice(0, 100); // Limit length to 100 chars
};

/**
 * Validate query parameters
 */
const validateQueryParams = (req, res, next) => {
  const allowedParams = ['limit', 'offset', 'sort'];
  const providedParams = Object.keys(req.query);

  // Check for unexpected parameters
  const invalidParams = providedParams.filter(p => !allowedParams.includes(p));
  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: 'Invalid query parameters',
      invalid: invalidParams,
    });
  }

  // Validate limit (should be a positive number)
  if (req.query.limit) {
    const limit = parseInt(req.query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        details: 'limit must be a number between 1 and 100',
      });
    }
  }

  // Validate offset
  if (req.query.offset) {
    const offset = parseInt(req.query.offset, 10);
    if (isNaN(offset) || offset < 0) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        details: 'offset must be a non-negative number',
      });
    }
  }

  next();
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
