  res.set('X-Request-ID', req.id);
  next();
});
```

### 4. **Add Content Security Policy**
```javascript
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
  },
}));
```

### 5. **Implement Input Sanitization**
