// Improved application with security best practices
// Enhanced error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const app = express();

// ============================================================================
// 1. SECURITY MIDDLEWARE
// ============================================================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Parse JSON with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// 2. LOGGING MIDDLEWARE
// ============================================================================

app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============================================================================
// 3. INPUT VALIDATION UTILITIES
// ============================================================================

/**
 * Validate query parameters
 * @param {string} param - Parameter to validate
 * @param {string} type - Type: 'string', 'number', 'email', 'uuid'
 * @returns {boolean} Valid or not
 */
function validateParam(param, type) {
  if (param === undefined || param === null) {
    return true; // Optional parameter
  }

  const paramStr = String(param).trim();

  switch (type) {
    case 'string':
      return typeof paramStr === 'string' && paramStr.length > 0 && paramStr.length <= 255;
    case 'number':
      return !isNaN(paramStr) && Number.isInteger(Number(paramStr)) && Number(paramStr) > 0;
    case 'email':
      return validator.isEmail(paramStr);
    case 'uuid':
      return validator.isUUID(paramStr);
    default:
      return false;
  }
}

/**
 * Sanitize string input
 * @param {string} input - Input to sanitize
 * @returns {string} Sanitized input
 */
function sanitizeInput(input) {
  if (typeof input !== 'string') {
    return '';
  }
  return validator.escape(validator.trim(input)).substring(0, 255);
}

// ============================================================================
// 4. ROUTES
// ============================================================================

/**
 * Health check endpoint
 * No authentication required
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Error in health check:', error.message);
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString(),
    });
  }
});

/**
 * Get users endpoint
 * Note: In production, add authentication/authorization
 */
app.get('/users', (req, res) => {
  try {
    // Input validation
    const { limit, offset, search } = req.query;

    // Validate limit parameter
    if (limit !== undefined) {
      if (!validateParam(limit, 'number')) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be a positive integer.',
          code: 'INVALID_INPUT',
        });
      }
    }

    // Validate offset parameter
    if (offset !== undefined) {
      if (!validateParam(offset, 'number')) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a positive integer.',
          code: 'INVALID_INPUT',
        });
      }
    }

    // Validate and sanitize search parameter
    if (search !== undefined) {
      if (!validateParam(search, 'string')) {
        return res.status(400).json({
          error: 'Invalid search parameter. Must be a non-empty string.',
          code: 'INVALID_INPUT',
        });
      }
    }

    // Safe defaults
    const pageLimit = Math.min(parseInt(limit) || 10, 100); // Cap at 100
    const pageOffset = Math.max(parseInt(offset) || 0, 0);
    const searchTerm = search ? sanitizeInput(search) : null;

    // Mock data (in production, query a database with parameterized queries)
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple in-memory filtering (use database queries in production)
    let results = mockUsers;
    if (searchTerm) {
      results = results.filter(
        (user) =>
          user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
          user.email.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Pagination
    const total = results.length;
    const paginatedResults = results.slice(pageOffset, pageOffset + pageLimit);

    res.json({
      data: paginatedResults,
      pagination: {
        limit: pageLimit,
        offset: pageOffset,
        total,
      },
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Error fetching users:', error.message);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR',
      timestamp: new Date().toISOString(),
    });
  }
});

// ============================================================================
// 5. ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    code: 'NOT_FOUND',
    path: req.path,
    timestamp: new Date().toISOString(),
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Prevent leaking error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const errorResponse = {
    error: isDevelopment ? err.message : 'Internal server error',
    code: 'INTERNAL_ERROR',
    timestamp: new Date().toISOString(),
  };

  if (isDevelopment) {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ============================================================================
// 6. SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

/**
 * Test Suite for Secure Express Application
 * Tests for error handling, input validation, and security
 */

const request = require('supertest');
const app = require('./app_improved');

describe('App Security Tests', () => {
  // ===================================================================
  // HEALTH ENDPOINT TESTS
  // ===================================================================

  describe('GET /health', () => {
    it('should return 200 with ok status', async () => {
      const res = await request(app).get('/health');

      expect(res.status).toBe(200);
      expect(res.body.status).toBe('ok');
      expect(res.body.timestamp).toBeDefined();
    });

    it('should return JSON with correct content-type', async () => {
      const res = await request(app).get('/health');

      expect(res.type).toMatch(/json/);
    });

    it('should have security headers', async () => {
      const res = await request(app).get('/health');

      expect(res.headers['x-content-type-options']).toBe('nosniff');
      expect(res.headers['x-frame-options']).toBeDefined();
      expect(res.headers['strict-transport-security']).toBeDefined();
    });
  });

  // ===================================================================
  // USERS ENDPOINT - INPUT VALIDATION TESTS
  // ===================================================================

  describe('GET /users', () => {
    it('should return 200 with user list', async () => {
      const res = await request(app).get('/users');

      expect(res.status).toBe(200);
      expect(res.body.data).toBeDefined();
      expect(Array.isArray(res.body.data)).toBe(true);
      expect(res.body.pagination).toBeDefined();
    });

    // ===================================================================
    // LIMIT PARAMETER VALIDATION
    // ===================================================================

    it('should reject limit parameter with non-numeric value', async () => {
      const res = await request(app)
        .get('/users')
        .query({ limit: 'abc' });

      expect(res.status).toBe(400);
      expect(res.body.code).toBe('INVALID_INPUT');
      expect(res.body.error).toContain('Invalid limit');
    });

    it('should reject limit parameter with negative value', async () => {
      const res = await request(app)
        .get('/users')
        .query({ limit: -5 });

      expect(res.status).toBe(400);
      expect(res.body.code).toBe('INVALID_INPUT');
    });

    it('should reject limit parameter with float value', async () => {
      const res = await request(app)
        .get('/users')
        .query({ limit: 10.5 });

      expect(res.status).toBe(400);
      expect(res.body.code).toBe('INVALID_INPUT');
    });

    it('should reject limit parameter with SQL injection attempt', async () => {
      const res = await request(app)
        .get('/users')
        .query({ limit: "10; DROP TABLE users;--" });

      expect(res.status).toBe(400);
      expect(res.body.code).toBe('INVALID_INPUT');
    });

    it('should accept valid limit parameter', async () => {
      const res = await request(app)
        .get('/users')
        .query({ limit: 10 });

      expect(res.status).toBe(200);
      expect(res.body.pagination.limit).toBeLessThanOrEqual(10);
    });

    it('should cap limit at maximum value', async () => {
      const res = await request(app)
        .get('/users')
        .query({ limit: 1000 });

      expect(res.status).toBe(200);
      expect(res.body.pagination.limit).toBeLessThanOrEqual(100); // Capped at 100
    });

    // ===================================================================
    // OFFSET PARAMETER VALIDATION
    // ===================================================================

    it('should reject offset parameter with non-numeric value', async () => {
      const res = await request(app)
        .get('/users')
        .query({ offset: 'xyz' });

      expect(res.status).toBe(400);
      expect(res.body.code).toBe('INVALID_INPUT');
    });

    it('should reject offset parameter with negative value', async () => {
      const res = await request(app)
        .get('/users')
        .query({ offset: -1 });

      expect(res.status).toBe(400);
      expect(res.body.code).toBe('INVALID_INPUT');
    });

    it('should accept valid offset parameter', async () => {
      const res = await request(app)
        .get('/users')
        .query({ offset: 0 });

      expect(res.status).toBe(200);
      expect(res.body.pagination.offset).toBe(0);
    });

    // ===================================================================
    // SEARCH PARAMETER VALIDATION
    // ===================================================================

    it('should reject search parameter that is too long', async () => {
      const longString = 'a'.repeat(300);
      const res = await request(app)
        .get('/users')
        .query({ search: longString });

      expect(res.status).toBe(400);
      expect(res.body.code).toBe('INVALID_INPUT');
    });

    it('should sanitize search parameter with HTML/script tags', async () => {
      const res = await request(app)
        .get('/users')
        .query({ search: '<script>alert("xss")</script>' });

      expect(res.status).toBe(200);
      // Verify no raw script tags in response
      expect(JSON.stringify(res.body)).not.toContain('<script>');
    });

    it('should reject search parameter with empty string', async () => {
      const res = await request(app)
        .get('/users')
        .query({ search: '' });

      expect(res.status).toBe(400);
      expect(res.body.code).toBe('INVALID_INPUT');
    });

    it('should accept valid search parameter', async () => {
      const res = await request(app)
        .get('/users')
        .query({ search: 'Alice' });

      expect(res.status).toBe(200);
      expect(Array.isArray(res.body.data)).toBe(true);
    });

    it('should filter users by search term', async () => {
      const res = await request(app)
        .get('/users')
        .query({ search: 'Alice' });

      expect(res.status).toBe(200);
      const foundAlice = res.body.data.some((user) =>
        user.name.toLowerCase().includes('alice')
      );
      expect(foundAlice).toBe(true);
    });

    // ===================================================================
    // COMBINED PARAMETERS VALIDATION
    // ===================================================================

    it('should handle multiple valid parameters', async () => {
      const res = await request(app)
        .get('/users')
        .query({ limit: 10, offset: 0, search: 'Bob' });

      expect(res.status).toBe(200);
      expect(res.body.pagination.limit).toBe(10);
      expect(res.body.pagination.offset).toBe(0);
    });

    it('should fail if any parameter is invalid', async () => {
      const res = await request(app)
        .get('/users')
        .query({ limit: 10, offset: 'invalid', search: 'Bob' });

      expect(res.status).toBe(400);
    });

    // ===================================================================
    // INJECTION ATTACK TESTS
    // ===================================================================

    it('should escape SQL injection in search parameter', async () => {
