# Before & After Comparison

## Overview
This document shows side-by-side comparison of the original app.js and the improved version.

---

## 1. SECURITY HEADERS & MIDDLEWARE

### BEFORE (Vulnerable)
```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Issues:**
- ❌ No security headers
- ❌ No CORS protection
- ❌ No rate limiting
- ❌ No request size limits
- ❌ Vulnerable to XSS, clickjacking, CSRF

### AFTER (Secure)
```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Set security HTTP headers (15+ headers)
app.use(helmet());

// Rate limiting: 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Parse JSON with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Improvements:**
- ✅ Security headers set (CSP, X-Frame-Options, etc.)
- ✅ Rate limiting prevents DoS/brute force
- ✅ Request size limits prevent buffer overflow
- ✅ Protected from XSS, clickjacking, MIME sniffing

---

## 2. INPUT VALIDATION

### BEFORE (No Validation)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Issues:**
- ❌ No parameter validation
- ❌ No input sanitization
- ❌ Vulnerable to injection attacks
- ❌ No boundary checks

### AFTER (With Validation)
```javascript
function validateParam(param, type) {
  if (param === undefined || param === null) {
    return true; // Optional parameter
  }

  const paramStr = String(param).trim();

  switch (type) {
    case 'number':
      return !isNaN(paramStr) && Number.isInteger(Number(paramStr)) && Number(paramStr) > 0;
    case 'string':
      return paramStr.length > 0 && paramStr.length <= 255;
    case 'email':
      return validator.isEmail(paramStr);
    default:
      return false;
  }
}

function sanitizeInput(input) {
  if (typeof input !== 'string') {
    return '';
  }
  return validator.escape(validator.trim(input)).substring(0, 255);
}

app.get('/users', (req, res) => {
  try {
    const { limit, offset, search } = req.query;

    // Validate parameters
    if (limit !== undefined && !validateParam(limit, 'number')) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be a positive integer.',
        code: 'INVALID_INPUT',
      });
    }

    if (offset !== undefined && !validateParam(offset, 'number')) {
      return res.status(400).json({
        error: 'Invalid offset parameter. Must be a positive integer.',
        code: 'INVALID_INPUT',
      });
    }

    if (search !== undefined && !validateParam(search, 'string')) {
      return res.status(400).json({
        error: 'Invalid search parameter.',
        code: 'INVALID_INPUT',
      });
    }

    // Safe defaults and sanitization
    const pageLimit = Math.min(parseInt(limit) || 10, 100);
    const pageOffset = Math.max(parseInt(offset) || 0, 0);
    const searchTerm = search ? sanitizeInput(search) : null;

    // ... filtered response ...
  } catch (error) {
    // Error handling (see below)
  }
});
```

**Improvements:**
- ✅ Type validation (number, string, email)
- ✅ Boundary checks (max length, positive integers)
- ✅ Input sanitization (HTML escaping)
- ✅ Safe defaults (no null/undefined issues)
- ✅ Protected from injection attacks

---

## 3. ERROR HANDLING

### BEFORE (No Error Handling)
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // What if this throws?
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
// No error handler, no 404 handler, no graceful shutdown
```

**Issues:**
- ❌ Unhandled exceptions crash the server
- ❌ No 404 handler (generic HTML response)
- ❌ No error logging
- ❌ No graceful shutdown
- ❌ Stack traces exposed to clients

### AFTER (With Error Handling)
```javascript
// Route with error handling
app.get('/users', (req, res) => {
  try {
    // ... validation and processing ...
    res.json(data);
  } catch (error) {
    console.error('Error fetching users:', error.message);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR',
      timestamp: new Date().toISOString(),
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    code: 'NOT_FOUND',
    path: req.path,
    timestamp: new Date().toISOString(),
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const isDevelopment = process.env.NODE_ENV !== 'production';
  const errorResponse = {
    error: isDevelopment ? err.message : 'Internal server error',
    code: 'INTERNAL_ERROR',
    timestamp: new Date().toISOString(),
  };

  if (isDevelopment) {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// Server startup with graceful shutdown
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});
```

**Improvements:**
- ✅ Try-catch in all routes
- ✅ Global error handler catches unhandled exceptions
- ✅ 404 handler for undefined routes
- ✅ Proper error logging
- ✅ Environment-based error messages (no stack trace in production)
- ✅ Graceful shutdown handling
- ✅ Consistent error response format

---

## 4. LOGGING & MONITORING

### BEFORE (No Logging)
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
// No request logging, no error tracking
```

**Issues:**
- ❌ No visibility into requests
- ❌ No audit trail
- ❌ Difficult debugging
- ❌ No security monitoring

### AFTER (With Logging)
```javascript
// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Error logging in catch blocks
try {
  // ...
} catch (error) {
  console.error('Error fetching users:', error.message);
  console.error('Stack:', error.stack);
  res.status(500).json({ error: 'Internal server error' });
}

// Error tracking in global handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  // Could send to Sentry, DataDog, etc.
});
```

**Improvements:**
- ✅ All requests logged with timestamps
- ✅ Error messages logged for debugging
- ✅ Stack traces available in development
- ✅ Easy integration with monitoring tools

---

## 5. CONFIGURATION & DEPLOYMENT

### BEFORE (Hardcoded)
```javascript
const PORT = 3000; // Hardcoded

app.listen(PORT, () => {
  console.log('Server running on port 3000');
});
```

**Issues:**
- ❌ Hardcoded port
- ❌ No environment-based config
- ❌ No graceful shutdown
- ❌ No environment detection

### AFTER (Configurable)
```javascript
// Environment variables
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Different configurations per environment
const RATE_LIMIT_CONFIG = {
  windowMs: process.env.RATE_LIMIT_WINDOW_MS || 15 * 60 * 1000,
  max: process.env.RATE_LIMIT_MAX_REQUESTS || 100,
};

// Startup
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${NODE_ENV}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});
```

**Improvements:**
- ✅ Configurable via environment variables
- ✅ Different settings per environment
- ✅ Proper startup logging
- ✅ Graceful shutdown handling

---

## 6. RESPONSE FORMAT

### BEFORE (Inconsistent)
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([...]); // Different format
});

// No error responses defined, Express returns HTML
```

**Issues:**
- ❌ Inconsistent response formats
- ❌ No standard error format
- ❌ HTML errors instead of JSON
- ❌ Hard to parse responses

### AFTER (Consistent)
```javascript
// Success response with metadata
app.get('/users', (req, res) => {
  res.json({
    data: [...],
    pagination: { limit, offset, total },
    timestamp: new Date().toISOString(),
  });
});

// Error responses with standard format
res.status(400).json({
  error: 'Invalid limit parameter',
  code: 'INVALID_INPUT',
  timestamp: new Date().toISOString(),
});

res.status(404).json({
  error: 'Not found',
  code: 'NOT_FOUND',
  path: req.path,
  timestamp: new Date().toISOString(),
});

res.status(500).json({
  error: 'Internal server error',
  code: 'INTERNAL_ERROR',
  timestamp: new Date().toISOString(),
});
```

**Improvements:**
- ✅ Consistent JSON format for all responses
- ✅ Standard error structure with code and message
- ✅ Timestamp on every response
- ✅ Metadata (pagination) included
- ✅ Easy to parse and handle

