// Enhanced Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Security headers
app.use(helmet());

// 2. CORS configuration
app.use((req, res, next) => {
  // Only allow specific origins in production
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
    res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  }

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// 3. Request logging
app.use(morgan('combined'));

// 4. Body parsing with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter limit for auth attempts
  message: 'Too many attempts, please try again later.',
  skipSuccessfulRequests: true, // Don't count successful requests
});

app.use(limiter);

// ==================== ROUTES ====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    errorHandler(error, req, res);
  }
});

// Get users endpoint with validation and sanitization
app.get(
  '/users',
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const limit = req.query.limit || 10;
      const offset = req.query.offset || 0;

      // Mock data (in real app, would come from database)
      const allUsers = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
