// Secure Express application with proper error handling and input validation
// Follows OWASP security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const validator = require('validator');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Security headers
app.use(helmet());

// 2. Body size limits (prevent DoS attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Data sanitization
app.use(mongoSanitize());

// 4. Rate limiting (prevent brute force/DoS)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// ==================== LOGGING ====================

// Simple request logging (use winston/morgan in production)
const requestLogger = (req, res, next) => {
  const timestamp = new Date().toISOString();
  const method = req.method;
  const url = req.url;
  const ip = req.ip;

  console.log(`[${timestamp}] ${method} ${url} - IP: ${ip}`);
  next();
};
app.use(requestLogger);

// ==================== ROUTES ====================

/**
 * Health check endpoint
 * No authentication required (public endpoint)
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

/**
 * Get users endpoint with pagination and input validation
 * Note: In production, add authentication/authorization
 */
app.get('/api/users', (req, res) => {
  try {
    // Input validation
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const search = req.query.search ? String(req.query.search).trim() : '';

    // Validation constraints
    if (!Number.isInteger(page) || page < 1) {
      return res.status(400).json({
        error: 'Invalid page number. Must be a positive integer.',
        code: 'INVALID_PAGE',
      });
    }

    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit. Must be between 1 and 100.',
        code: 'INVALID_LIMIT',
      });
    }

    // Search input validation (prevent injection attacks)
    if (search && !validator.isLength(search, { min: 1, max: 50 })) {
      return res.status(400).json({
        error: 'Search query too long. Maximum 50 characters.',
        code: 'INVALID_SEARCH',
      });
    }

    // Mock data (in production, fetch from secure database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter based on search
    let filteredUsers = allUsers;
    if (search) {
      // Sanitize search to prevent injection
      const sanitizedSearch = mongoSanitize(search);
      filteredUsers = allUsers.filter(
        (user) =>
          user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
          user.id.toString().includes(sanitizedSearch)
      );
    }

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Response with metadata
    res.status(200).json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        pages: Math.ceil(filteredUsers.length / limit),
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR',
    });
  }
});

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    code: 'NOT_FOUND',
    path: req.path,
  });
});

// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
  });

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    code: err.code || 'INTERNAL_ERROR',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Unhandled promise rejection
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

/**
 * Configuration Module
 * Loads and validates environment variables
 * @module config
 */

require('dotenv').config({
  path: `.env.${process.env.NODE_ENV || 'development'}`,
  override: false, // Don't override existing env vars
});

/**
 * Environment configuration object
 * @type {Object}
 */
const config = {
  // Server
  port: parseInt(process.env.PORT, 10) || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',

  // Flags
  isDevelopment: process.env.NODE_ENV === 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isTest: process.env.NODE_ENV === 'test',

  // Logging
  logLevel: process.env.LOG_LEVEL || (process.env.NODE_ENV === 'production' ? 'info' : 'debug'),

  // Rate Limiting
  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000, // 15 minutes
    max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100,
  },

  // CORS
  cors: {
    origins: process.env.ALLOWED_ORIGINS
      ? process.env.ALLOWED_ORIGINS.split(',').map(origin => origin.trim())
      : ['http://localhost:3000'],
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
  },

  // Database
  database: {
    url: process.env.DATABASE_URL,
  },

  // Authentication
  jwt: {
    secret: process.env.JWT_SECRET,
    expiresIn: '24h',
  },

  session: {
    secret: process.env.SESSION_SECRET,
  },

  // Third-party integrations
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },

  anthropic: {
    apiKey: process.env.ANTHROPIC_API_KEY,
  },

  stripe: {
    secretKey: process.env.STRIPE_SECRET_KEY,
  },

  logfire: {
    token: process.env.LOGFIRE_TOKEN,
  },
};

/**
 * Validate required configuration
 * @throws {Error} If required configuration is missing in production
 */
function validateConfig() {
  const requiredInProduction = [
    'database.url',
    'jwt.secret',
    'session.secret',
  ];

  const requiredInAll = ['nodeEnv', 'port'];

  // Check required in all environments
  const missingRequired = requiredInAll.filter(path => {
    const value = getNestedValue(config, path);
    return !value;
  });

  if (missingRequired.length > 0) {
    throw new Error(
      `Missing required configuration: ${missingRequired.join(', ')}`
    );
  }

  // Check production requirements
  if (config.isProduction) {
    const missingProduction = requiredInProduction.filter(path => {
      const value = getNestedValue(config, path);
      return !value;
    });

    if (missingProduction.length > 0) {
      throw new Error(
        `Missing required production configuration: ${missingProduction.join(', ')}`
      );
    }
  }

  // Warn about weak secrets in development
  if (config.isDevelopment) {
    if (config.jwt.secret && config.jwt.secret.length < 32) {
      console.warn('⚠️  JWT_SECRET is short. Use at least 32 characters in production.');
    }
  }
}

/**
 * Get nested object value by path
 * @param {Object} obj - Object to traverse
 * @param {string} path - Path to value (e.g., 'database.url')
 * @returns {any} Value at path or undefined
 */
function getNestedValue(obj, path) {
  return path.split('.').reduce((current, prop) => current?.[prop], obj);
}

// Validate on load
validateConfig();

/**
 * Log configuration (safe for production - secrets not logged)
 */
function logConfig() {
  const safe = {
    port: config.port,
    nodeEnv: config.nodeEnv,
    isDevelopment: config.isDevelopment,
    isProduction: config.isProduction,
    isTest: config.isTest,
    logLevel: config.logLevel,
    rateLimitWindowMs: config.rateLimit.windowMs,
    rateLimitMax: config.rateLimit.max,
    corsOrigins: config.cors.origins,
  };

  console.log('Configuration loaded:', JSON.stringify(safe, null, 2));
}

if (config.isDevelopment) {
  logConfig();
}

module.exports = config;

/**
 * Improved app.js with Security Fixes + Configuration Integration
 * Uses config.js for environment management
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const validator = require('validator');

// Load configuration (handles all env variables)
const config = require('./config');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Security headers
app.use(helmet());

// 2. Body size limits (prevent DoS attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Data sanitization
app.use(mongoSanitize());

// 4. Rate limiting (using config values)
const limiter = rateLimit({
  windowMs: config.rateLimit.windowMs,
  max: config.rateLimit.max,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// ==================== LOGGING ====================

const requestLogger = (req, res, next) => {
  if (config.logLevel !== 'error') {
    const timestamp = new Date().toISOString();
    const method = req.method;
    const url = req.url;
    const ip = req.ip;
    console.log(`[${timestamp}] ${method} ${url} - IP: ${ip}`);
  }
  next();
};
app.use(requestLogger);

// ==================== ROUTES ====================

/**
 * Health check endpoint
 * No authentication required (public endpoint)
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: config.isDevelopment ? 'development' : 'production',
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

/**
 * Get users endpoint with pagination and input validation
 * Uses configuration for security parameters
 */
app.get('/api/users', (req, res) => {
  try {
    // Input validation
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const search = req.query.search ? String(req.query.search).trim() : '';

    // Validation constraints
    if (!Number.isInteger(page) || page < 1) {
      return res.status(400).json({
        error: 'Invalid page number. Must be a positive integer.',
        code: 'INVALID_PAGE',
      });
    }

    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit. Must be between 1 and 100.',
        code: 'INVALID_LIMIT',
      });
    }

    // Search input validation (prevent injection attacks)
    if (search && !validator.isLength(search, { min: 1, max: 50 })) {
      return res.status(400).json({
        error: 'Search query too long. Maximum 50 characters.',
        code: 'INVALID_SEARCH',
      });
    }

    // Mock data (in production, fetch from secure database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter based on search
    let filteredUsers = allUsers;
    if (search) {
      // Sanitize search to prevent injection
      const sanitizedSearch = mongoSanitize(search);
      filteredUsers = allUsers.filter(
        (user) =>
          user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
          user.id.toString().includes(sanitizedSearch)
      );
    }

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Response with metadata
    res.status(200).json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        pages: Math.ceil(filteredUsers.length / limit),
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR',
    });
  }
});

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    code: 'NOT_FOUND',
    path: req.path,
  });
});

// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
  });

  // Don't expose internal error details in production
  const errorMessage = config.isDevelopment 
    ? err.message 
    : 'Internal server error';

  res.status(err.status || 500).json({
    error: errorMessage,
    code: err.code || 'INTERNAL_ERROR',
    ...(config.isDevelopment && { stack: err.stack }),
  });
});

// ==================== SERVER STARTUP ====================

/**
 * Start the server
 * Uses configuration for port
 */
function startServer() {
  const server = app.listen(config.port, () => {
    console.log(`
    =====================================
    🚀 Server started successfully
    =====================================
    Port:       ${config.port}
    Environment: ${config.nodeEnv}
    Timestamp:  ${new Date().toISOString()}
    =====================================
    `);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM received. Shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT received. Shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });

  return server;
}

// Start server (unless being imported)
const server = !module.parent ? startServer() : null;

// Unhandled promise rejection
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  if (config.isProduction) {
    process.exit(1);
  }
});

module.exports = app;

