// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================================================
// 1. SECURITY MIDDLEWARE
// ============================================================================

// Add security headers
app.use(helmet());

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// HTTP request logging
app.use(morgan('combined'));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiting to all routes
app.use(limiter);

// ============================================================================
// 2. REQUEST VALIDATION MIDDLEWARE
// ============================================================================

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================================================
// 3. ROUTES WITH VALIDATION
// ============================================================================

/**
 * Health check endpoint
 * Public endpoint - minimal data exposure
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get users endpoint
 * TODO: Add authentication/authorization before using this in production
 * TODO: Sanitize user data - consider not exposing email addresses without consent
 */
app.get('/users',
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100'),
  query('skip')
    .optional()
    .isInt({ min: 0 })
    .withMessage('skip must be a non-negative integer'),

  // Handle validation errors
  handleValidationErrors,

  // Route handler
  (req, res, next) => {
    try {
      const limit = parseInt(req.query.limit, 10) || 10;
      const skip = parseInt(req.query.skip, 10) || 0;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const paginatedUsers = users.slice(skip, skip + limit);

      res.json({
        data: paginatedUsers,
        total: users.length,
        limit,
        skip
      });
    } catch (error) {
      next(error); // Pass to error handler
    }
  }
);

/**
 * Example: Create user endpoint with validation
 * (Not in original app but shows best practices)
 */
app.post('/users',
  // Input validation
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters'),
  body('email')
    .trim()
    .isEmail().withMessage('Valid email is required')
    .normalizeEmail(),

  handleValidationErrors,

  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // TODO: Validate against database
      // TODO: Hash/encrypt sensitive data before storage

      res.status(201).json({
        id: 3,
        name,
        email
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// 4. 404 HANDLER
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path
  });
});

// ============================================================================
// 5. GLOBAL ERROR HANDLING MIDDLEWARE
// ============================================================================
// IMPORTANT: Must be defined LAST, after all other app.use() and routes

app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    status: err.status || 500,
    path: req.path,
    method: req.method
  });

  // Don't expose error details to client in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  const statusCode = err.status || 500;
  const response = {
    error: err.message || 'Internal server error'
  };

  // Only include stack trace in development
  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// 6. SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

