# Quick Reference Guide - Security Improvements

## 🎯 Before & After Comparison

### Original Code
```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

**Problems:**
- ❌ No error handling → Server crashes on exceptions
- ❌ No input validation → SQL injection, XSS, DoS attacks
- ❌ No security headers → XSS, clickjacking vulnerabilities
- ❌ No rate limiting → DDoS attacks
- ❌ No request logging → No audit trail
- ❌ Exposed data → Privacy risks

---

### Improved Code (Key Additions)

#### 1. Security Middleware Setup
```javascript
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

// Security headers
app.use(helmet());

// HTTP logging
app.use(morgan('combined'));

// Rate limiting (100 requests per 15 minutes)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests, try again later.'
});
app.use(limiter);

// Request size limits
app.use(express.json({ limit: '10kb' }));
```

#### 2. Input Validation
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be 1-100'),
  query('skip')
    .optional()
    .isInt({ min: 0 })
    .withMessage('skip must be >= 0'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process validated data
  }
);
```

#### 3. Error Handling
```javascript
app.get('/users', (req, res, next) => {
  try {
    // Route logic
    res.json(data);
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Global error handler (MUST BE LAST)
app.use((err, req, res, next) => {
  console.error(err);
  const isDev = process.env.NODE_ENV === 'development';
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'Internal server error'
  });
});
```

#### 4. 404 Handler
```javascript
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path
  });
});
```

#### 5. Graceful Shutdown
```javascript
const server = app.listen(PORT, () => {
  console.log(`Server on port ${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

