// Enhanced application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Set security HTTP headers
app.use(helmet());

// 2. Sanitize data against NoSQL injection attacks
app.use(mongoSanitize());

// 3. Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Rate limiting - prevent brute force and DDoS
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter limit for auth endpoints
  skipSuccessfulRequests: true,
  message: 'Too many authentication attempts, please try again later.',
});

app.use(generalLimiter);

// ============================================================================
// ERROR HANDLING UTILITIES
// ============================================================================

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

const catchAsync = (fn) => (req, res, next) => {
  fn(req, res, next).catch(next);
};

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

const validateQuery = (schema) => (req, res, next) => {
  const { error, value } = schema.validate(req.query, {
    abortEarly: false,
    stripUnknown: true,
  });

  if (error) {
    const messages = error.details.map((detail) => detail.message);
    return next(new AppError(`Invalid query parameters: ${messages.join(', ')}`, 400));
  }

  req.query = value;
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

app.get(
  '/health',
  catchAsync(async (req, res) => {
    // Health check endpoint - basic validation
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  })
);

app.get(
  '/users',
  authLimiter,
  catchAsync(async (req, res) => {
    // TODO: Add authentication middleware to verify user identity
    // TODO: Add authorization to check if user has permission to view users

    // Mock user data (in production, query from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Validate and sanitize query parameters
    let { page = 1, limit = 10, sort = 'id' } = req.query;

    // Type coercion and validation
    page = Math.max(1, parseInt(page, 10) || 1);
    limit = Math.min(100, Math.max(1, parseInt(limit, 10) || 10));

    // Whitelist allowed sort fields
    const allowedSortFields = ['id', 'name', 'email'];
    if (!allowedSortFields.includes(sort)) {
      throw new AppError('Invalid sort field', 400);
    }

    // Implement pagination (prevent returning all records at once)
    const start = (page - 1) * limit;
    const paginatedUsers = users.slice(start, start + limit);

    res.status(200).json({
      status: 'success',
      data: {
        users: paginatedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          pages: Math.ceil(users.length / limit),
        },
      },
    });
  })
);

// ============================================================================
// ROUTE NOT FOUND HANDLER
// ============================================================================

app.all('*', (req, res, next) => {
  next(new AppError(`Cannot find ${req.originalUrl} on this server!`, 404));
});

// ============================================================================
// GLOBAL ERROR HANDLING MIDDLEWARE
// ============================================================================

app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    statusCode: err.statusCode,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
  });

  // Send error response
  res.status(err.statusCode).json({
    status: err.status,
    message: err.message,
    // Don't expose detailed error info in production
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

# Security Review: app.js Improvement Recommendations

## Executive Summary
The current app.js implementation lacks critical security controls. This document outlines vulnerabilities and provides implementation guidance.

---

## 🔴 Critical Issues

### 1. **No Error Handling**
**Risk:** Unhandled exceptions crash the server or leak sensitive information
```javascript
// ❌ Current approach - no error handling
app.get('/users', (req, res) => {
  res.json([...]); // If this fails, server crashes
});

// ✅ Improved approach
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});
```

**Why it matters:**
- Prevents Information Disclosure (stack traces exposed)
- Prevents Denial of Service (unhandled crashes)
- Enables proper logging and monitoring

---

### 2. **No Input Validation**
**Risk:** SQL/NoSQL Injection, Command Injection, XSS
```javascript
// ❌ Without validation, attackers can send:
// GET /users?limit=999999&sort=id;DROP TABLE users;
// GET /users?page=<script>alert('xss')</script>

// ✅ Validate and sanitize ALL inputs
const page = Math.max(1, parseInt(req.query.page, 10) || 1);
const allowedFields = ['id', 'name'];
if (!allowedFields.includes(req.query.sort)) {
  throw new Error('Invalid sort field');
}
```

---

### 3. **No Rate Limiting**
**Risk:** Brute force attacks, DDoS, Resource exhaustion
```javascript
// ❌ Any client can make unlimited requests
app.get('/users', (req, res) => { ... });

// ✅ Implement rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // 100 requests per window
});
app.use(limiter);
```

---

### 4. **No Security Headers**
**Risk:** Clickjacking, MIME sniffing, XSS, CSRF attacks
```javascript
// ✅ Use helmet middleware
const helmet = require('helmet');
app.use(helmet()); // Sets:
// - Content-Security-Policy
// - X-Frame-Options: DENY
// - X-Content-Type-Options: nosniff
// - Strict-Transport-Security
```

---

### 5. **Missing Request Size Limits**
**Risk:** DoS attacks via large payloads
```javascript
// ❌ No size limit - attackers can send huge requests
app.use(express.json());

// ✅ Enforce reasonable limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb' }));
```

---

## 🟡 Medium Issues

### 6. **No Authentication/Authorization**
**Risk:** Unauthorized access to sensitive data
```javascript
// ❌ Anyone can access /users endpoint
app.get('/users', (req, res) => {
  res.json([...]); // No permission checks
});

// ✅ Add authentication and authorization
app.get('/users', authenticate, authorize('view_users'), (req, res) => {
  res.json([...]);
});
```

**Recommendation:**
- Implement JWT or session-based authentication
- Add middleware to verify authentication
- Check user permissions before returning data

---

### 7. **No Logging/Monitoring**
**Risk:** Unable to detect attacks or debug issues
```javascript
// ✅ Implement structured logging
const logger = {
  info: (msg) => console.log(`[${new Date().toISOString()}] INFO: ${msg}`),
  error: (msg) => console.error(`[${new Date().toISOString()}] ERROR: ${msg}`),
  warn: (msg) => console.warn(`[${new Date().toISOString()}] WARN: ${msg}`),
};

// Log all requests
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});
```

---

### 8. **Sensitive Data Exposure**
**Risk:** User emails exposed without authorization
```javascript
// ❌ Returning all user data including emails
{ id: 1, name: 'Alice', email: 'alice@example.com' }

// ✅ Return only necessary fields
function sanitizeUser(user) {
  return {
    id: user.id,
    name: user.name,
    // Don't expose email unless authorized
  };
}
```

---

### 9. **Missing Environment Configuration**
**Risk:** Hardcoded values, exposed secrets
```javascript
// ❌ Hardcoded port
app.listen(3000);

// ✅ Use environment variables
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const ENV = process.env.NODE_ENV || 'development';
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${ENV} mode`);
});
