// Authentication & Authorization Middleware Template
// Implement this to add authentication to your secured app

const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

// ============================================================================
// ERROR CLASSES
// ============================================================================

class AuthError extends Error {
  constructor(message, statusCode = 401) {
    super(message);
    this.statusCode = statusCode;
    this.status = 'fail';
  }
}

// ============================================================================
// JWT UTILITIES
// ============================================================================

const createJWT = (id) => {
  return jwt.sign({ id }, process.env.JWT_SECRET, {
    expiresIn: process.env.JWT_EXPIRY || '7d',
  });
};

const verifyJWT = (token) => {
  try {
    return jwt.verify(token, process.env.JWT_SECRET);
  } catch (err) {
    throw new AuthError('Invalid or expired token', 401);
  }
};

// ============================================================================
// PASSWORD HASHING
// ============================================================================

const hashPassword = async (password) => {
  // Validate password strength
  if (password.length < 8) {
    throw new AuthError('Password must be at least 8 characters', 400);
  }
  const salt = await bcrypt.genSalt(10);
  return bcrypt.hash(password, salt);
};

const comparePassword = async (password, hashedPassword) => {
  return bcrypt.compare(password, hashedPassword);
};

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticate = async (req, res, next) => {
  try {
    // 1. Get token from header
    let token = req.headers.authorization;

    if (!token) {
      throw new AuthError('No authentication token. Please log in.', 401);
    }

    // 2. Remove "Bearer " prefix if present
    if (token.startsWith('Bearer ')) {
      token = token.slice(7);
    }

    // 3. Verify token
    const decoded = verifyJWT(token);

    // 4. Get user from database (mock implementation)
    // In production: const user = await User.findById(decoded.id);
    const user = {
      id: decoded.id,
      role: 'user', // Mock role
      isActive: true,
    };

    if (!user || !user.isActive) {
      throw new AuthError('User not found or inactive', 401);
    }

    // 5. Attach user to request
    req.user = user;
    next();
  } catch (err) {
    next(err);
  }
};

// ============================================================================
// AUTHORIZATION MIDDLEWARE
// ============================================================================

const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return next(new AuthError('Not authenticated', 401));
    }

    if (!roles.includes(req.user.role)) {
      return next(
        new AuthError(
          `User role '${req.user.role}' is not authorized. Required: ${roles.join(', ')}`,
          403
        )
      );
    }

    next();
  };
};

// ============================================================================
// PERMISSION CHECKS
// ============================================================================

const isResourceOwner = (req, res, next) => {
  // Check if user is the owner of the resource
  if (req.user.id !== parseInt(req.params.id, 10) && req.user.role !== 'admin') {
    return next(
      new AuthError(
        'You do not have permission to access this resource',
        403
      )
    );
  }
  next();
};

const isAdmin = (req, res, next) => {
  if (req.user.role !== 'admin') {
    return next(
      new AuthError('Admin access required', 403)
    );
  }
  next();
};

// ============================================================================
// RATE LIMITING FOR AUTH ENDPOINTS
// ============================================================================

const authRateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: false,
  message: 'Too many login attempts, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => {
    // Rate limit by email instead of IP for auth endpoints
    return req.body.email || req.ip;
  },
});

// ============================================================================
// LOGIN ROUTE EXAMPLE
// ============================================================================

const login = async (req, res, next) => {
  try {
    // 1. Validate input
    const { email, password } = req.body;

    if (!email || !password) {
      throw new AuthError('Please provide email and password', 400);
    }

    // Email validation
    if (!validator.isEmail(email)) {
      throw new AuthError('Invalid email format', 400);
    }

    // 2. Find user (mock implementation)
    // In production: const user = await User.findOne({ email });
    const user = {
      id: 1,
      email: 'user@example.com',
      password: await hashPassword(password), // Mock
      role: 'user',
      isActive: true,
      lastLogin: null,
    };

    if (!user) {
      // Don't reveal if email exists (security best practice)
      throw new AuthError('Invalid email or password', 401);
    }

    // 3. Verify password
    const isPasswordValid = await comparePassword(password, user.password);
    if (!isPasswordValid) {
      throw new AuthError('Invalid email or password', 401);
    }

    // 4. Create JWT token
    const token = createJWT(user.id);

    // 5. Update last login (in production)
    // await User.findByIdAndUpdate(user.id, { lastLogin: new Date() });

    // 6. Log authentication attempt
    console.log(`[AUTH] Successful login for user ${user.email} from ${req.ip}`);

    // 7. Return token (never include password!)
    res.status(200).json({
      status: 'success',
      message: 'Logged in successfully',
      data: {
        token,
        user: {
          id: user.id,
          email: user.email,
          role: user.role,
        },
      },
    });
  } catch (err) {
    next(err);
  }
};

// ============================================================================
// REGISTER ROUTE EXAMPLE
// ============================================================================

const register = async (req, res, next) => {
  try {
    // 1. Validate input
    const { email, password, passwordConfirm, name } = req.body;

    if (!email || !password || !passwordConfirm || !name) {
      throw new AuthError('Please provide all required fields', 400);
    }

    // Email validation
    if (!validator.isEmail(email)) {
      throw new AuthError('Invalid email format', 400);
    }

    // Password validation
    if (password !== passwordConfirm) {
      throw new AuthError('Passwords do not match', 400);
    }

    if (password.length < 8) {
      throw new AuthError('Password must be at least 8 characters', 400);
    }

    // Name validation
    if (!validator.isLength(name, { min: 2, max: 50 })) {
      throw new AuthError('Name must be between 2 and 50 characters', 400);
    }

    // 2. Check if user already exists
    // In production: const userExists = await User.findOne({ email });
    const userExists = false;

    if (userExists) {
      throw new AuthError('Email already in use', 409);
    }

    // 3. Hash password
    const hashedPassword = await hashPassword(password);

    // 4. Create user (mock implementation)
    // In production:
    // const user = await User.create({
    //   email,
    //   password: hashedPassword,
    //   name,
    //   role: 'user',
    // });

    const user = {
      id: Date.now(),
      email,
      name,
      role: 'user',
    };

    // 5. Create JWT token
    const token = createJWT(user.id);

    // 6. Log registration
    console.log(`[AUTH] New user registered: ${email}`);

    // 7. Return token
    res.status(201).json({
      status: 'success',
      message: 'User registered successfully',
      data: {
        token,
        user: {
          id: user.id,
          email: user.email,
          name: user.name,
          role: user.role,
        },
      },
    });
  } catch (err) {
    next(err);
  }
};

// ============================================================================
// LOGOUT ROUTE EXAMPLE
// ============================================================================

const logout = (req, res) => {
  // Note: With JWT, logout is typically handled on the client
  // The token becomes invalid after expiry
  // In production, you might maintain a blacklist of revoked tokens

  console.log(`[AUTH] User ${req.user.id} logged out`);

  res.status(200).json({
    status: 'success',
    message: 'Logged out successfully',
  });
};

// ============================================================================
// PASSWORD RESET EXAMPLE (BASIC)
// ============================================================================

const requestPasswordReset = async (req, res, next) => {
  try {
    const { email } = req.body;

    if (!email || !validator.isEmail(email)) {
      throw new AuthError('Please provide a valid email', 400);
    }

    // In production:
    // 1. Find user
    // 2. Generate reset token
    // 3. Save hashed token to database with expiry
    // 4. Send email with reset link

    console.log(`[AUTH] Password reset requested for ${email}`);

    res.status(200).json({
      status: 'success',
      message: 'Password reset link sent to email',
    });
  } catch (err) {
    next(err);
  }
};

