// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Use helmet to set various HTTP headers
app.use(helmet());

// 2. Body parser with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 4. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// 5. Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============================================
// ROUTES WITH INPUT VALIDATION
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('[/health] Error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/users', (req, res) => {
  try {
    // Optional query parameter validation example
    const { limit, offset } = req.query;

    // Validate limit parameter (optional)
    if (limit !== undefined) {
      const parsedLimit = parseInt(limit, 10);
      if (
        isNaN(parsedLimit) ||
        parsedLimit < 1 ||
        parsedLimit > 100
      ) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be a number between 1 and 100.',
        });
      }
    }

    // Validate offset parameter (optional)
    if (offset !== undefined) {
      const parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative number.',
        });
      }
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      success: true,
      data: users,
      count: users.length,
    });
  } catch (error) {
    console.error('[/users] Error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Example: POST endpoint with comprehensive validation
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    const errors = [];

    // Validate name
    if (!name) {
      errors.push('Name is required');
    } else if (typeof name !== 'string') {
      errors.push('Name must be a string');
    } else if (name.trim().length === 0) {
      errors.push('Name cannot be empty or whitespace');
    } else if (name.length > 100) {
      errors.push('Name must not exceed 100 characters');
    }

    // Validate email
    if (!email) {
      errors.push('Email is required');
    } else if (!validator.isEmail(email)) {
      errors.push('Invalid email format');
    }

    // Return validation errors
    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors,
      });
    }

    // Proceed with user creation
    const newUser = {
      id: Math.floor(Math.random() * 10000),
      name: validator.trim(name), // Sanitize input
      email: validator.normalizeEmail(email), // Normalize email
    };

    res.status(201).json({
      success: true,
      data: newUser,
      message: 'User created successfully',
    });
  } catch (error) {
    console.error('[POST /users] Error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested resource ${req.path} was not found.`,
  });
});

// ============================================
// GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  const timestamp = new Date().toISOString();
  console.error(
    `[${timestamp}] Error: ${err.message}`,
    err.stack
  );

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const errorResponse = {
    error: 'Internal Server Error',
    ...(isDevelopment && { message: err.message, stack: err.stack }),
  };

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json(errorResponse);
});

// ============================================
// UNHANDLED REJECTIONS
// ============================================

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to log this to an external service
  // and/or restart the application
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, consider gracefully shutting down the application
  process.exit(1);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

